const r={categories:[{id:"lg-tf",titleZh:"判断题",noteZh:"一句话判断对错，辨清概念。"},{id:"lg-fill",titleZh:"首字母填空",noteZh:"按首字母补全单词，把术语写对。"},{id:"lg-mc",titleZh:"选择题",noteZh:"四选一，概念与流派的快问快答。"},{id:"lg-term",titleZh:"术语解释",noteZh:"先写下你的理解，再对照参考答案。"},{id:"lg-match",titleZh:"连线配对",noteZh:"把术语与它对应的领域配到一起。"},{id:"lg-seg",titleZh:"词素切分",noteZh:"把单词切成词素，用连字符分隔。"},{id:"lg-short",titleZh:"问答",noteZh:"先动笔再翻参考，练成段回答。"}],items:[{id:"lg-mc-c1-01",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 1 章",prompt:"All languages have three major components: a sound system, a system of ______ and a system of semantics.",options:["morphology","lexicogrammar","syntax","meaning"],answer:"lexicogrammar",acceptedAnswers:[],explanationZh:"语言的三大成分：语音、词汇语法、语义系统。",difficulty:2},{id:"lg-mc-c1-02",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 1 章",prompt:"Which of the following words is entirely arbitrary?",options:["tree","typewriter","bowwow","bang"],answer:"tree",acceptedAnswers:[],explanationZh:"tree 的音义结合无自然联系；typewriter、bowwow、bang 都有理据。",difficulty:2},{id:"lg-mc-c1-03",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 1 章",prompt:"The function of the sentence Water boils at 100 degrees Centigrade is ______.",options:["interpersonal","emotive","informative","performative"],answer:"informative",acceptedAnswers:[],explanationZh:"陈述客观事实，行使信息功能。",difficulty:1},{id:"lg-mc-c1-04",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 1 章",prompt:"In Chinese when someone breaks a bowl or a plate the host or the people present are likely to say 碎碎（岁岁）平安 as a means of controlling the forces which they believe might affect their lives. Which function does it perform?",options:["Interpersonal","Emotive","Informative","Performative"],answer:"Performative",acceptedAnswers:[],explanationZh:"借语言改变事态（化凶为吉），属施为功能。",difficulty:2},{id:"lg-mc-c1-05",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 1 章",prompt:"Which of the following property of language enables language users to overcome the barriers caused by time and place of speaking (due to this feature of language, speakers of a language are free to talk about anything in any situation)?",options:["Transferability","Duality","Displacement","Arbitrariness"],answer:"Displacement",acceptedAnswers:[],explanationZh:"克服时空障碍、谈论不在场事物，是移位性。",difficulty:1},{id:"lg-mc-c1-06",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 1 章",prompt:"What language function does the following conversation play? (The two chatters just met and were starting their conversation by the following dialogue.) A: A nice day, isn't it? B: Right! I really enjoy the sunlight.",options:["Emotive","Phatic","Performative","Interpersonal"],answer:"Phatic",acceptedAnswers:[],explanationZh:"见面谈天气寒暄，属应酬功能，意在维系关系。",difficulty:2},{id:"lg-mc-c1-07",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 1 章",prompt:"______ refers to the actual realization of the ideal language user's knowledge of the rules of his language in utterances.",options:["Performance","Competence","Langue","Parole"],answer:"Performance",acceptedAnswers:[],explanationZh:"performance 是语言知识在话语中的实际运用。",difficulty:2},{id:"lg-mc-c1-08",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 1 章",prompt:"When a dog is barking, you assume it is barking for something or at someone that exists here and now. It couldn't be sorrowful for some lost love or lost bone. This indicates that dog's language does not have the feature of ______.",options:["reference","productivity","displacement","duality"],answer:"displacement",acceptedAnswers:[],explanationZh:"狗只能对此时此地的事物吠叫，说明缺乏移位性。",difficulty:2},{id:"lg-mc-c1-09",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 1 章",prompt:"______ answers such questions as how we as infants acquire our first language.",options:["Psycholinguistics","Anthropological linguistics","Sociolinguistics","Applied linguistics"],answer:"Psycholinguistics",acceptedAnswers:[],explanationZh:"研究儿童母语习得的学科是心理语言学。",difficulty:1},{id:"lg-mc-c1-10",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 1 章",prompt:"______ deals with the study of dialects in different social classes in a particular region.",options:["Linguistic theory","Practical linguistics","Sociolinguistics","Comparative linguistics"],answer:"Sociolinguistics",acceptedAnswers:[],explanationZh:"研究社会阶层方言差异的是社会语言学。",difficulty:2},{id:"lg-tf-c1-01",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 1 章",prompt:"The widely accepted meaning of arbitrariness was discussed by Chomsky first.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"任意性概念最早由索绪尔系统阐述，而非乔姆斯基。",difficulty:2},{id:"lg-tf-c1-02",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 1 章",prompt:"For learners of a foreign language, it is arbitrariness that is more worth noticing than its conventionality.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"外语学习者更应关注约定俗成性，而非任意性。",difficulty:2},{id:"lg-tf-c1-03",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 1 章",prompt:"Displacement benefits human beings by giving them the power to handle generalizations and abstractions.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"移位性使人能谈论不在场事物，从而概括与抽象。",difficulty:2},{id:"lg-tf-c1-04",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 1 章",prompt:"For Jakobson and the Prague school structuralists, the purpose of communication is to refer.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"雅各布森与布拉格学派认为交际功能不止指称，还包括情感等功能。",difficulty:3},{id:"lg-tf-c1-05",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 1 章",prompt:"Interpersonal function is also called ideational function in the framework of functional grammar.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"人际功能与概念功能是两种不同的功能，不能等同。",difficulty:2},{id:"lg-tf-c1-06",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 1 章",prompt:"Emotive function is also discussed under the term expressive function.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"emotive 功能又称 expressive 功能，二者同义。",difficulty:1},{id:"lg-tf-c1-07",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 1 章",prompt:"The relationship between competence and performance in Chomsky's theory is that between a language community and an individual language user.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"语言社团与个人的关系对应 langue 与 parole，而非 competence 与 performance。",difficulty:3},{id:"lg-tf-c1-08",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 1 章",prompt:"A study of the features of the English used in Shakespeare's time is an example of the diachronic study of language.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"研究特定时期的语言属共时研究，历时研究才考察演变。",difficulty:2},{id:"lg-tf-c1-09",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 1 章",prompt:"Articulatory phonetics investigates the properties of the sound waves.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"研究声波属性的是声学语音学，发音语音学研究发音过程。",difficulty:2},{id:"lg-tf-c1-10",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 1 章",prompt:"The nature of linguistics as a science determines its preoccupation with prescription instead of description.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"语言学作为科学重在描写语言事实，而非规定用法。",difficulty:1},{id:"lg-fill-c1-01",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 1 章",prompt:"Nowadays, two kinds of research methods co-exist in linguistic studies, namely, qualitative and q______ research approaches.",options:[],answer:"quantitative",acceptedAnswers:[],explanationZh:"与定性研究（qualitative）相对的是定量研究。",difficulty:2},{id:"lg-fill-c1-02",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 1 章",prompt:"In ang language words can be used in new ways to mean new things and can be combined into innumerable sentences based on limited rules. This feature is usually termed as p______.",options:[],answer:"productivity",acceptedAnswers:[],explanationZh:"有限规则造无限新句，是能产性（productivity）。",difficulty:2},{id:"lg-fill-c1-03",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 1 章",prompt:"Language has many functions. We can use language to talk about language. This function is m______ function.",options:[],answer:"metalingual",acceptedAnswers:[],explanationZh:"用语言谈论语言，是元语言功能（metalingual）。",difficulty:2},{id:"lg-fill-c1-04",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 1 章",prompt:"The claim that language originated by primitive man involuntary making vocal noises while performing heavy work has been called the y______ theory.",options:[],answer:"Yo-he-ho",acceptedAnswers:["Yo- he- ho","Yo he ho"],explanationZh:"劳动号子起源说称 yo-he-ho 理论。",difficulty:3},{id:"lg-fill-c1-05",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 1 章",prompt:"P______ is often said to be concerned with the organization of speech within specific languages, or with the systems and patterns of sounds that occur in particular languages.",options:[],answer:"Phonology",acceptedAnswers:[],explanationZh:"研究具体语言语音系统的学科是音系学。",difficulty:2},{id:"lg-fill-c1-06",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 1 章",prompt:"Modern linguistics is d______ in the sense that the linguist tries to discover what language is rather than lay down some rules for people to observe.",options:[],answer:"descriptive",acceptedAnswers:[],explanationZh:"描写语言实况，现代语言学是描写性的。",difficulty:1},{id:"lg-fill-c1-07",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 1 章",prompt:"One general principle of linguistic analysis is the primacy of s______ over writing.",options:[],answer:"speech",acceptedAnswers:[],explanationZh:"口语先于书面语，是语言分析的首要原则。",difficulty:2},{id:"lg-fill-c1-08",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 1 章",prompt:"The description of a language as it changes through time is a d______ linguistic study.",options:[],answer:"diachronic",acceptedAnswers:[],explanationZh:"研究语言随时间的演变，是历时语言学。",difficulty:2},{id:"lg-fill-c1-09",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 1 章",prompt:"Saussure put forward the concept l______ to refer to the abstract linguistic system shared by all members of a speech community.",options:[],answer:"langue",acceptedAnswers:[],explanationZh:"langue 指社团共有的抽象语言系统。",difficulty:2},{id:"lg-fill-c1-10",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 1 章",prompt:"Linguistic potential is similar to Saussure's langue and Chomsky's c______.",options:[],answer:"Competence",acceptedAnswers:[],explanationZh:"语言潜势对应 langue 与 competence。",difficulty:2},{id:"lg-term-c1-01",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 1 章",prompt:"名词解释：Design features。先写下你的理解，再对照参考答案。",options:[],answer:"It refers to the defining properties of human language that tell the difference between human language and any system of animal communication.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c1-02",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 1 章",prompt:"名词解释：Displacement。先写下你的理解，再对照参考答案。",options:[],answer:"It means that human languages enable their users to symbolize objects, events and concepts, which are not present (in time and space) at the moment of communication.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c1-03",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 1 章",prompt:"名词解释：Competence。先写下你的理解，再对照参考答案。",options:[],answer:"It is a term brought about by Chomsky. It is the speaker's knowledge of his or her language; that is, of its sound structure, its words, and its grammatical rules. Competence is, in a way, an encyclopedia of language. Moreover, the knowledge involved in competence is generally unconscious.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c1-04",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 1 章",prompt:"名词解释：Synchronic linguistics。先写下你的理解，再对照参考答案。",options:[],answer:"It refers to the study of a language at a given point in time. The time studied may be either the present or a particular point in the past; synchronic analysis can also be made of dead languages, such as Latin. Synchronic linguistics is contrasted with diachronic linguistics, the study of a language over a period of time.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-match-c1-01",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 1 章",prompt:'"shape of syllable" 属于下列哪个语言学分支？',options:["phonology","phonetics","syntax","semantics"],answer:"phonology",acceptedAnswers:[],explanationZh:"音节的形状与结构属音系学研究对象。",difficulty:2},{id:"lg-match-c1-02",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 1 章",prompt:'"word formation" 属于下列哪个语言学分支？',options:["morphology","phonology","semantics","pragmatics"],answer:"morphology",acceptedAnswers:[],explanationZh:"构词规则属形态学研究范围。",difficulty:2},{id:"lg-match-c1-03",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 1 章",prompt:'"production of speech" 属于下列哪个语言学分支？',options:["phonetics","phonology","morphology","syntax"],answer:"phonetics",acceptedAnswers:[],explanationZh:"语音的产生属语音学研究范围。",difficulty:2},{id:"lg-match-c1-04",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 1 章",prompt:'"denotation of words" 属于下列哪个语言学分支？',options:["semantics","phonetics","phonology","pragmatics"],answer:"semantics",acceptedAnswers:[],explanationZh:"词的外延意义属语义学研究范围。",difficulty:2},{id:"lg-mc-c2-01",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 2 章",prompt:"In a syllable, a vowel often serves as ______.",options:["Peak or Nucleus","Onset","Coda","Rhyme"],answer:"Peak or Nucleus",acceptedAnswers:[],explanationZh:"音节中元音通常充当节峰（peak/nucleus）。",difficulty:1},{id:"lg-mc-c2-02",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 2 章",prompt:"Conventionally a ______ is put in slashes / /.",options:["allophone","phone","phoneme","morpheme"],answer:"phoneme",acceptedAnswers:[],explanationZh:"音位习惯放在斜线 // 中，音素放在方括号里。",difficulty:1},{id:"lg-mc-c2-03",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 2 章",prompt:"An aspirated [ph], an unaspirated [Po] and an unreleased [p┓] are ______ of the /p/ phoneme.",options:["analogues","tagmemes","morphemes","allophones"],answer:"allophones",acceptedAnswers:[],explanationZh:"同一音位的不同实现形式称音位变体。",difficulty:2},{id:"lg-mc-c2-04",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 2 章",prompt:"The opening between the vocal cords is sometimes referred to as ______.",options:["glottis","vocal cavity","pharynx","uvula"],answer:"glottis",acceptedAnswers:[],explanationZh:"声带之间的开口称声门（glottis）。",difficulty:1},{id:"lg-mc-c2-05",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 2 章",prompt:"The diphthongs that are made with a movement of the tongue towards the center are known as ______ diphthongs.",options:["wide","closing","narrow","centering"],answer:"centering",acceptedAnswers:[],explanationZh:"舌位向中央滑动形成的双元音称集中双元音。",difficulty:2},{id:"lg-mc-c2-06",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 2 章",prompt:"A phoneme is realized by a group of similar sounds called ______.",options:["minimal pairs","allomorphs","phones","allophones"],answer:"allophones",acceptedAnswers:[],explanationZh:"音位由一组语音相似的音位变体来实现。",difficulty:1},{id:"lg-mc-c2-07",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 2 章",prompt:"Which of the following sounds is a voiceless bilabial stop?",options:["[p]","[m]","[b]","[t]"],answer:"[p]",acceptedAnswers:[],explanationZh:"[p] 是清双唇爆破音；[b] 浊音，[m] 鼻音，[t] 齿龈音。",difficulty:2},{id:"lg-mc-c2-08",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 2 章",prompt:"Which one is different from the others according to places of articulation?",options:["[n]","[m]","[b]","[p]"],answer:"[n]",acceptedAnswers:[],explanationZh:"[n] 是齿龈音，[m]、[b]、[p] 都是双唇音。",difficulty:2},{id:"lg-mc-c2-09",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 2 章",prompt:"Which vowel is different from the others according to the characteristics of vowels?",options:["[i:]","[u]","[e]","[i]"],answer:"[u]",acceptedAnswers:[],explanationZh:"[u] 是后元音，其余都是前元音。",difficulty:2},{id:"lg-mc-c2-10",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 2 章",prompt:"What kind of sounds can we make when the vocal cords are vibrating?",options:["Voiceless","Voiced","Glottal stop","Consonant"],answer:"Voiced",acceptedAnswers:[],explanationZh:"声带振动发出的音是浊音（voiced）。",difficulty:1},{id:"lg-tf-c2-01",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 2 章",prompt:"[f] is a dental consonant.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"[f] 是唇齿音（labiodental），不是齿音（dental）。",difficulty:1},{id:"lg-tf-c2-02",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 2 章",prompt:"Phonology is a branch of linguistics which studies the sentence patterns of a language.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"音系学研究音位系统，研究句型的是句法学。",difficulty:1},{id:"lg-tf-c2-03",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 2 章",prompt:"[p] is a voiced bilabial stop.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"[p] 是清双唇爆破音，浊音对应 [b]。",difficulty:1},{id:"lg-tf-c2-04",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 2 章",prompt:"The speech sounds which are in complementary distribution are not always allophones of the same phoneme.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"互补分布还须语音相似才能归并，故不一定是同一音位。",difficulty:3},{id:"lg-tf-c2-05",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 2 章",prompt:"The last sound of cut can be articulated as an unreleased or released plosive. These different realizations of the same phoneme are NOT in complementary distribution.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"cut 尾音爆破与否属自由变异，不在互补分布。",difficulty:3},{id:"lg-tf-c2-06",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 2 章",prompt:"Phonology is language specific but phonetics is not.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"音位随语言而异，语音描写具普遍性。",difficulty:2},{id:"lg-tf-c2-07",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 2 章",prompt:"Distinctive features can show phonological contrasts or oppositions of language sounds.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"区别特征正是显示音位对立的手段。",difficulty:2},{id:"lg-tf-c2-08",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 2 章",prompt:"The maximal onset principle states that when there is a choice as to where to place a consonant. It is put into the coda rather than the onset.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"最大节首原则把辅音尽量归入节首，而非韵尾。",difficulty:3},{id:"lg-tf-c2-09",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 2 章",prompt:"When the vocal folds are apart, the air can pass through easily and the sound produced is said to be voiced.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"声带分开气流畅通产生清音；合拢振动才是浊音。",difficulty:2},{id:"lg-tf-c2-10",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 2 章",prompt:"Phonetic similarity means that the allophones of a phoneme must bear some morphological resemblance.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"音位变体间要求语音相似，与形态相似无关。",difficulty:2},{id:"lg-fill-c2-01",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 2 章",prompt:"V______ is made with the back of the tongue and the soft palate. An example in English is [k] as in cat.",options:[],answer:"Velar",acceptedAnswers:[],explanationZh:"舌根与软腭构成 [k]，是软腭音（velar）。",difficulty:2},{id:"lg-fill-c2-02",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 2 章",prompt:"Consonant sounds can also be made when two organs of speech in the mouth are brought close together so that the air is pushed out between them, causing f______.",options:[],answer:"friction",acceptedAnswers:[],explanationZh:"两器官靠近、气流挤出产生摩擦（friction）。",difficulty:2},{id:"lg-fill-c2-03",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 2 章",prompt:"The qualities of vowels depend upon the position of the t______ and the lips.",options:[],answer:"tongue",acceptedAnswers:[],explanationZh:"元音音质取决于舌位与唇形。",difficulty:1},{id:"lg-fill-c2-04",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 2 章",prompt:"One element in the description of vowels is the part of the tongue which is at the highest point in the mouth. A second element is the h______ to which that part of the tongue is raised.",options:[],answer:"height",acceptedAnswers:[],explanationZh:"元音描写要素：舌位前后与抬起高度（height）。",difficulty:2},{id:"lg-fill-c2-05",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 2 章",prompt:"Consonants differ from vowels in that the latter are produced without o______.",options:[],answer:"obstruction",acceptedAnswers:[],explanationZh:"元音发音时气流无阻碍（obstruction）。",difficulty:2},{id:"lg-fill-c2-06",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 2 章",prompt:"In phonological analysis the words fail / veil are distinguishable simply because of the two phonemes /f/-/v/. This is an example for illustrating m______ pairs.",options:[],answer:"minimal",acceptedAnswers:[],explanationZh:"fail/veil 仅 /f/ 与 /v/ 对立，是最小对立对。",difficulty:2},{id:"lg-fill-c2-07",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 2 章",prompt:"In English there are a number of d______, which are produced by moving from one vowel position to another through intervening positions.",options:[],answer:"diphthongs",acceptedAnswers:[],explanationZh:"从一舌位滑向另一舌位的是双元音。",difficulty:1},{id:"lg-fill-c2-08",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 2 章",prompt:"C______ refers to the phenomenon of sounds continually show the influence of their neighbors.",options:[],answer:"Co-articulation",acceptedAnswers:["Co articulation"],explanationZh:"语音受邻音影响的现象是协同发音。",difficulty:3},{id:"lg-fill-c2-09",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 2 章",prompt:"P______ is the smallest phonemic unit.",options:[],answer:"Phoneme",acceptedAnswers:[],explanationZh:"音位是最小的区别意义语音单位。",difficulty:1},{id:"lg-fill-c2-10",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 2 章",prompt:"Speech takes place when the organs of speech move to produce patterns of sound. These movements have an effect on the a______ coming from the lungs.",options:[],answer:"air-stream",acceptedAnswers:["air stream"],explanationZh:"发音器官运动作用于肺部气流（air-stream）。",difficulty:2},{id:"lg-term-c2-01",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 2 章",prompt:"名词解释：Assimilation。先写下你的理解，再对照参考答案。",options:[],answer:"Speech sounds seldom occur in isolation. In connected speech, under the influence of their neighbors, are replaced by other sounds. Sometimes two neighboring sounds influence each other and are replaced by a third sound which is different from both original sounds. This process is called sound assimilation.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c2-02",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 2 章",prompt:"名词解释：Suprasegmental feature。先写下你的理解，再对照参考答案。",options:[],answer:"The phonetic features that occur above the level of the segments are called suprasegmental features; these are the phonological properties of such units as the syllable, the word, and the sentence. The main suprasegmental features include stress, intonation, and tone.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c2-03",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 2 章",prompt:"名词解释：Complementary distribution。先写下你的理解，再对照参考答案。",options:[],answer:"The different allophones of the same phoneme never occur in the same phonetic context. When two or more allophones of one phoneme never occur in the same linguistic environment they are said to be in complementary distribution.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c2-04",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 2 章",prompt:"名词解释：Distinctive features。先写下你的理解，再对照参考答案。",options:[],answer:"It refers to the features that can distinguish one phoneme from another. If we can group the phonemes into two categories: one with this feature and the other without, this feature is called a distinctive feature.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-match-c2-01",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 2 章",prompt:'"approximant" 对应下列哪一项？',options:["[w]","[v]","tool and stool","tool and pool"],answer:"[w]",acceptedAnswers:[],explanationZh:"approximant 是无摩擦延续音，[w] 是典型例子。",difficulty:3},{id:"lg-match-c2-02",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 2 章",prompt:'"labiodental" 对应下列哪一项？',options:["[v]","[w]","tool and stool","tool and pool"],answer:"[v]",acceptedAnswers:[],explanationZh:"labiodental 唇齿音，[v] 由下唇与上齿构成。",difficulty:2},{id:"lg-match-c2-03",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 2 章",prompt:'"minimal pair" 对应下列哪一项？',options:["tool and pool","tool and stool","[w]","[v]"],answer:"tool and pool",acceptedAnswers:[],explanationZh:"tool 与 pool 仅首音 [t]/[p] 不同，构成最小对立对。",difficulty:2},{id:"lg-match-c2-04",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 2 章",prompt:'"pulmonic" 对应下列哪一项？',options:["produced by pushing air out","produced by sucking air in","tool and stool","tool and pool"],answer:"produced by pushing air out",acceptedAnswers:[],explanationZh:"pulmonic 指靠肺部气流排出而发音。",difficulty:2},{id:"lg-mc-c3-01",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"In terms of the meaning expressed by words, they can be classified into ____.",options:["grammatical words and lexical words","Content words and lexical words","Grammatical words and function words","Pro-forms and auxiliaries"],answer:"grammatical words and lexical words",acceptedAnswers:[],explanationZh:"按表达的意义，词分语法词与词汇词。",difficulty:2},{id:"lg-mc-c3-02",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"______ other than compounds may be divided into roots and affixes.",options:["Polymorphemic words","Bound morphemes","Free morphemes","Monomorphemic words"],answer:"Polymorphemic words",acceptedAnswers:[],explanationZh:"多词素词可再分为词根与词缀。",difficulty:2},{id:"lg-mc-c3-03",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"Which two terms can best describe the following pairs of words: table-tables, day break-daybreak?",options:["Inflection and compound","Compound and derivation","Inflection and derivation","Derivation and inflection"],answer:"Inflection and compound",acceptedAnswers:[],explanationZh:"tables 属屈折变化，daybreak 属复合构词。",difficulty:2},{id:"lg-mc-c3-04",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"Which of the following is NOT a morphological process?",options:["COINAGE","ACRONYM","LEXICON","BLENDING"],answer:"LEXICON",acceptedAnswers:[],explanationZh:"LEXICON 是词库，不是构词过程。",difficulty:1},{id:"lg-mc-c3-05",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"Which of the following is NOT a pre-determiner?",options:["all","three times","half","that"],answer:"that",acceptedAnswers:[],explanationZh:"that 是中位限定词，其余是前位限定词。",difficulty:2},{id:"lg-mc-c3-06",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"Nouns, verbs and adjectives can be classified as ______.",options:["lexical words","grammatical words","function words","form words"],answer:"lexical words",acceptedAnswers:[],explanationZh:"名、动、形都承载实义，属词汇词。",difficulty:1},{id:"lg-mc-c3-07",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"Morphemes that represent tense, number, gender and case are called ______ morpheme.",options:["inflectional","free","bound","derivational"],answer:"inflectional",acceptedAnswers:[],explanationZh:"表示时、数、性、格的词素是屈折词素。",difficulty:2},{id:"lg-mc-c3-08",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"There are _____ morphemes in the word denationalization.",options:["three","four","five","six"],answer:"five",acceptedAnswers:[],explanationZh:"de-nation-al-iz-ation 共 5 个词素。",difficulty:2},{id:"lg-mc-c3-09",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"In English, -ise and -al are called _____.",options:["prefixes","suffixes","infixes","stems"],answer:"suffixes",acceptedAnswers:[],explanationZh:"-ise、-al 都附着在词基之后，是后缀。",difficulty:1},{id:"lg-mc-c3-10",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"The three subtypes of affixes are: prefix, suffix and _____.",options:["derivational affix","inflectional affix","infix","back-formation"],answer:"infix",acceptedAnswers:[],explanationZh:"词缀三种：前缀、后缀、中缀。",difficulty:1},{id:"lg-mc-c3-11",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"_______ is a way in which new words may be formed from already existing words by subtracting an affix which is thought to be part of the old word.",options:["Affixation","Back-formation","Insertion","Addition"],answer:"Back-formation",acceptedAnswers:[],explanationZh:"去掉原本不属于它的词缀构新词，是逆构词法。",difficulty:2},{id:"lg-mc-c3-12",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"The word TV is formed in the way of _______.",options:["acronymy","clipping","initialism","blending"],answer:"initialism",acceptedAnswers:[],explanationZh:"TV 按字母逐个读，是首字母缩拼词。",difficulty:2},{id:"lg-mc-c3-13",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"The words like comsat and sitcom are formed by _____.",options:["blending","clipping","back-formation","acronymy"],answer:"blending",acceptedAnswers:[],explanationZh:"comsat、sitcom 由两词首尾拼合，属混成法。",difficulty:2},{id:"lg-mc-c3-14",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"The stem of internationalists is _______.",options:["nationalist","nation","nationalist","internationalist"],answer:"internationalist",acceptedAnswers:[],explanationZh:"去掉屈折词缀 -s 后的词干是 internationalist。",difficulty:2},{id:"lg-mc-c3-15",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 3 章",prompt:"All of them are meaningful EXCEPT for _____.",options:["lexeme","phone","morpheme","allomorph"],answer:"phone",acceptedAnswers:[],explanationZh:"phone 只是语音单位，本身不表义。",difficulty:2},{id:"lg-tf-c3-01",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 3 章",prompt:"Phonetically, the stress of a compound always falls on the first element, while the second element receives secondary stress.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"复合词重音通常落在第一成分，第二成分只带次重音。",difficulty:2},{id:"lg-tf-c3-02",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 3 章",prompt:"Base refers to the part of the word that remains when all inflectional affixes are removed.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"去掉所有屈折词缀剩下的是词干；词基要去掉全部词缀。",difficulty:3},{id:"lg-tf-c3-03",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 3 章",prompt:"In most cases, prefixes change the meaning of the base whereas suffixes change the word-class of the base.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"前缀多改变词基意义，后缀多改变词基词类。",difficulty:2},{id:"lg-tf-c3-04",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 3 章",prompt:"The morphemes -s in dogs and -al in national are both bound morphemes.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"-s 与 -al 都不能独立成词，都是粘着词素。",difficulty:1},{id:"lg-tf-c3-05",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 3 章",prompt:"Reduplicative compound is formed by repeating the same morpheme of a word.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"叠词复合词重复的是整个词（如 bye-bye），而非只重复一个词素。",difficulty:3},{id:"lg-tf-c3-06",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 3 章",prompt:"The words whisper and whistle are formed in the way of onomatopoeia.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"whisper、whistle 都是模拟声音的拟声词。",difficulty:2},{id:"lg-tf-c3-07",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 3 章",prompt:"In most cases, the number of syllables of a word corresponds to the number of morphemes.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"音节数与词素数并不对应，如 taught 一个音节含两个词素。",difficulty:2},{id:"lg-tf-c3-08",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 3 章",prompt:"Back-formation is a productive way of word-formations.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"逆构词属次要构词法，不是能产方式。",difficulty:2},{id:"lg-tf-c3-09",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 3 章",prompt:"Inflection is a minor way of word-formations.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"屈折变化只改词形表语法关系，不构成新词，不算构词法。",difficulty:3},{id:"lg-tf-c3-10",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 3 章",prompt:"Coinage is a form of compounding, in which two words are blended by joining the initial part of the first word and the final part of the second word, or by joining the initial parts of the two words.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"句中所描述的是混成法；coinage 是凭空造新词（如商标名 Kodak）。",difficulty:2},{id:"lg-fill-c3-01",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 3 章",prompt:"Different from compounds, d______ shows a relationship between roots and affixes.",options:[],answer:"derivation",acceptedAnswers:[],explanationZh:"词根与词缀的关系是派生，区别于复合。",difficulty:2},{id:"lg-fill-c3-02",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 3 章",prompt:"B______ morphemes cannot be used independently but has to be combined with other morphemes.",options:[],answer:"Bound",acceptedAnswers:[],explanationZh:"不能独立使用的词素是粘着词素。",difficulty:1},{id:"lg-fill-c3-03",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 3 章",prompt:"M______ is a branch of grammar which studies the internal structure of words and rules by which words are formed.",options:[],answer:"Morphology",acceptedAnswers:[],explanationZh:"研究词内部结构与构词规则的是形态学。",difficulty:1},{id:"lg-fill-c3-04",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 3 章",prompt:"All words may be said to contain a root m______.",options:[],answer:"morpheme",acceptedAnswers:[],explanationZh:"每个词都含一个词根词素。",difficulty:1},{id:"lg-fill-c3-05",nodeId:"lg-fill",categoryId:"lg-fill",kind:"short-answer",label:"第 3 章",prompt:"A small set of conjunctions, prepositions and pronouns belong to c______ class, while the largest part of nouns, verbs, adjectives and adverbs belongs to o______ class.",options:[],answer:"closed; open",acceptedAnswers:["closed open","closed, open"],explanationZh:"连词、介词、代词属封闭类；名动形副属开放类。",difficulty:3},{id:"lg-fill-c3-06",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 3 章",prompt:"B______ is a reverse process of derivation, and therefore is a process of shortening.",options:[],answer:"Back-formation",acceptedAnswers:["Back formation"],explanationZh:"去词缀构词是逆构词法。",difficulty:2},{id:"lg-fill-c3-07",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 3 章",prompt:"C______ is a process of word formation in which one can, by shifting the word class, change the meaning of a word from a concrete entity or notion to a process or attribution.",options:[],answer:"Conversion",acceptedAnswers:[],explanationZh:"转换词类改变意义是转类法（conversion）。",difficulty:2},{id:"lg-fill-c3-08",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 3 章",prompt:"Words are divided into simple, compound and derived words on the m______ level.",options:[],answer:"morpheme",acceptedAnswers:[],explanationZh:"按词素层面分简单词、复合词、派生词。",difficulty:2},{id:"lg-fill-c3-09",nodeId:"lg-fill",categoryId:"lg-fill",kind:"short-answer",label:"第 3 章",prompt:"A word formed by derivation is called a d______, and a word formed by compounding is called a c______.",options:[],answer:"derivative; compound",acceptedAnswers:["derivative compound","derivative, compound"],explanationZh:"派生构词得派生词，复合构词得复合词。",difficulty:3},{id:"lg-fill-c3-10",nodeId:"lg-fill",categoryId:"lg-fill",kind:"short-answer",label:"第 3 章",prompt:"Bound morphemes are classified into two types: a______ and bound r______.",options:[],answer:"affix; root",acceptedAnswers:["affix root","affix, root"],explanationZh:"粘着词素分词缀与粘着词根两类。",difficulty:2},{id:"lg-term-c3-01",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 3 章",prompt:"名词解释：Blending。先写下你的理解，再对照参考答案。",options:[],answer:"It is a process of word-formation in which a new word is formed by combining the meanings and sounds of two words, one of which is not in its full form or both of which are not in their full forms, like brunch (breakfast + lunch).",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c3-02",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 3 章",prompt:"名词解释：Allomorph。先写下你的理解，再对照参考答案。",options:[],answer:"It is any of the variant forms of a morpheme as conditioned by position or adjoining sounds.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c3-03",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 3 章",prompt:"名词解释：Closed-class word。先写下你的理解，再对照参考答案。",options:[],answer:"It is a word whose membership is fixed or limited. Pronouns, prepositions, conjunctions, articles, etc. are all closed-class words.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c3-04",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 3 章",prompt:"名词解释：Morphological rule。先写下你的理解，再对照参考答案。",options:[],answer:"It is the rule that governs which affix can be added to what type of base to form a new word, e. g. -1y can be added to a noun to form an adjective.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-seg-c3-01",nodeId:"lg-seg",categoryId:"lg-seg",kind:"short-answer",label:"第 3 章",prompt:"把下列单词切分成词素，用连字符分隔：disappointed",options:[],answer:"dis-appoint-ed",acceptedAnswers:["dis appoint ed"],explanationZh:"dis-（前缀）+ appoint（词根）+ -ed（屈折后缀）。",difficulty:3},{id:"lg-seg-c3-02",nodeId:"lg-seg",categoryId:"lg-seg",kind:"short-answer",label:"第 3 章",prompt:"把下列单词切分成词素，用连字符分隔：illegal",options:[],answer:"il-legal",acceptedAnswers:["il legal"],explanationZh:"il- 是 in- 的变体 + 词根 legal。",difficulty:2},{id:"lg-seg-c3-03",nodeId:"lg-seg",categoryId:"lg-seg",kind:"short-answer",label:"第 3 章",prompt:"把下列单词切分成词素，用连字符分隔：intercontinental",options:[],answer:"inter-continent-al",acceptedAnswers:["inter continent al"],explanationZh:"前缀 inter- + 词根 continent + 后缀 -al。",difficulty:3},{id:"lg-seg-c3-04",nodeId:"lg-seg",categoryId:"lg-seg",kind:"short-answer",label:"第 3 章",prompt:"把下列单词切分成词素，用连字符分隔：refusal",options:[],answer:"refus-al",acceptedAnswers:["refus al","refuse-al","refuse al"],explanationZh:"词根 refus(e) + 派生后缀 -al。",difficulty:3},{id:"lg-seg-c3-05",nodeId:"lg-seg",categoryId:"lg-seg",kind:"short-answer",label:"第 3 章",prompt:"把下列单词切分成词素，用连字符分隔：lukewarm",options:[],answer:"luke-warm",acceptedAnswers:["luke warm"],explanationZh:"两个自由词根 luke 与 warm 复合。",difficulty:2},{id:"lg-seg-c3-06",nodeId:"lg-seg",categoryId:"lg-seg",kind:"short-answer",label:"第 3 章",prompt:"把下列单词切分成词素，用连字符分隔：globalization",options:[],answer:"globe-al-iz-ation",acceptedAnswers:["globe al iz ation"],explanationZh:"globe + -al + -iz(e) + -ation，多层派生。",difficulty:3},{id:"lg-seg-c3-07",nodeId:"lg-seg",categoryId:"lg-seg",kind:"short-answer",label:"第 3 章",prompt:"把下列单词切分成词素，用连字符分隔：uncomfortably",options:[],answer:"un-comfort-abl-ly",acceptedAnswers:["un comfort abl ly"],explanationZh:"un- + comfort + -abl(e) + -ly，三层词缀。",difficulty:3},{id:"lg-seg-c3-08",nodeId:"lg-seg",categoryId:"lg-seg",kind:"short-answer",label:"第 3 章",prompt:"把下列单词切分成词素，用连字符分隔：receiving",options:[],answer:"re-ceiv-ing",acceptedAnswers:["re ceiv ing"],explanationZh:"前缀 re- + 粘着词根 ceiv(e) + 屈折后缀 -ing。",difficulty:3},{id:"lg-mc-c4-01",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"Which of the following term does NOT mean the same as the relation of substitutability?",options:["Associative relation","Paradigmatic relation","Vertical relation","Horizontal relation"],answer:"Horizontal relation",acceptedAnswers:[],explanationZh:"可替换性对应纵聚合关系，而非横组合关系。",difficulty:3},{id:"lg-mc-c4-02",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"Clauses can be used as subordinate constituents and the three basic types of subordinate clauses are complement clauses, adjunct clauses and _____.",options:["relative clauses","adverbial clauses","coordinate clauses","subordinate clauses"],answer:"relative clauses",acceptedAnswers:[],explanationZh:"三大从属分句：补语、附加语、关系分句。",difficulty:2},{id:"lg-mc-c4-03",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"Names of the syntactic functions are expressed in all the following terms EXCEPT ______.",options:["subjects and objects","objects and predicators","modifiers and complements","endocentric and exocentric"],answer:"endocentric and exocentric",acceptedAnswers:[],explanationZh:"endocentric/exocentric 是结构类型，不是句法功能。",difficulty:2},{id:"lg-mc-c4-04",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"In English, case is a special form of the noun which frequently corresponds to a combination of preposition and noun and it is realized in all the following channels EXCEPT ______.",options:["inflection","following a preposition","word order","vertical relation"],answer:"vertical relation",acceptedAnswers:[],explanationZh:"case 的实现途径有屈折、介词、语序，无 vertical relation。",difficulty:3},{id:"lg-mc-c4-05",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"The sentence John likes linguistics, but Mary is interested in history is a ________ sentence.",options:["simple","coordinate","complex","relational"],answer:"coordinate",acceptedAnswers:[],explanationZh:"两个小句由 but 连接，属并列句。",difficulty:1},{id:"lg-mc-c4-06",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"Phrase structure rules have _______ properties.",options:["recursive","grammatical","social","functional"],answer:"recursive",acceptedAnswers:[],explanationZh:"短语结构规则具有递归性，可无限套叠。",difficulty:2},{id:"lg-mc-c4-07",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"Which of the following is NOT among the three basic ways to classify languages in the world?",options:["Word order","Genetic classification","Areal classification","Social classification"],answer:"Social classification",acceptedAnswers:[],explanationZh:"语言分类三大途径：语序、发生学、地域；social classification 不在其中。",difficulty:2},{id:"lg-mc-c4-08",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"The head of the phrase the city Rome is ____.",options:["the city","Rome","city","The city Rome"],answer:"The city Rome",acceptedAnswers:[],explanationZh:"the city Rome 是同位结构，两个成分同为 head。",difficulty:3},{id:"lg-mc-c4-09",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"The phrase on the shelf belongs to ______ construction.",options:["endocentric","exocentric","subordinate","coordinate"],answer:"exocentric",acceptedAnswers:[],explanationZh:"on the shelf 是介词短语，属离心结构。",difficulty:2},{id:"lg-mc-c4-10",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"The sentence They were wanted to remain quiet and not to expose themselves is a _______ sentence.",options:["simple","coordinate","compound","complex"],answer:"simple",acceptedAnswers:[],explanationZh:"全句只有一个限定主谓结构（被动 they were wanted），是简单句。",difficulty:3},{id:"lg-mc-c4-11",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"In the sentence Mary told Jane that John liked linguistics the introductory word that is called _______.",options:["coordinating conjunction","conjunction","subordinator","embedded word"],answer:"subordinator",acceptedAnswers:[],explanationZh:"引导补语分句的 that 是从属连词（subordinator）。",difficulty:2},{id:"lg-mc-c4-12",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"The student// likes/ the new linguistics professor. The above segmentation reveals the __________ nature of sentence structure.",options:["hierarchical","linear","horizontal","parallel"],answer:"hierarchical",acceptedAnswers:[],explanationZh:"句子可逐层二分，说明结构具有层级性。",difficulty:2},{id:"lg-mc-c4-13",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:`According to the following tree diagram, V can only be replaced by ______.
S
NP  VP
V  PP
The boy ______ in the chair`,options:["sat","brought","pushed","none"],answer:"sat",acceptedAnswers:[],explanationZh:"空位动词后接介词短语，需不及物动词 sat；brought、pushed 需宾语。",difficulty:3},{id:"lg-mc-c4-14",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"Clauses can be classified into finite and non-finite clauses, ______ including the traditional infinitive phrase, participial phrase and gerundial phrase.",options:["the former","the latter","both","neither"],answer:"the latter",acceptedAnswers:[],explanationZh:"后者指非限定分句，含不定式、分词、动名词短语。",difficulty:1},{id:"lg-mc-c4-15",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 4 章",prompt:"In the phrase structure rule S→NP VP, the arrow can be read as ______.",options:["has","generates","consists of","is equal to"],answer:"consists of",acceptedAnswers:[],explanationZh:"S→NP VP 中箭头读作 consists of。",difficulty:2},{id:"lg-tf-c4-01",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 4 章",prompt:"The relations of co-occurrence partly belong to syntagmatic relations, partly to paradigmatic relations.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"词的共现既受横组合支配，也受纵聚合选择影响。",difficulty:3},{id:"lg-tf-c4-02",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 4 章",prompt:"One property coordination reveals is that there is a limit on the number of coordinated categories that can appear prior to the conjunction.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"并列结构的重要特征恰是并列项数量没有限制。",difficulty:3},{id:"lg-tf-c4-03",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 4 章",prompt:"Classes and functions determine each other, but not in any one-to-one relation.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"词类与句法功能相互决定，但非一一对应。",difficulty:2},{id:"lg-tf-c4-04",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 4 章",prompt:"Usually noun phrases, prepositional phrases and adverbial phrases belong to endocentric types of constriction.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"介词短语属离心结构，故「通常都属向心」不成立。",difficulty:2},{id:"lg-tf-c4-05",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 4 章",prompt:"A noun phrase must contain a noun, but other elements are optional.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"名词短语必须有名词作中心语，其余成分可选。",difficulty:1},{id:"lg-tf-c4-06",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 4 章",prompt:"In a coordinate sentence, two (or more) S constituents occur as co-head of a higher S.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"并列句中多个小句同作更高层 S 的共同中心语。",difficulty:3},{id:"lg-fill-c4-01",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 4 章",prompt:"The subordinate constituents are words which modify the Head and consequently, they can be called m______.",options:[],answer:"modifiers",acceptedAnswers:[],explanationZh:"修饰中心语的从属成分叫修饰语（modifier）。",difficulty:2},{id:"lg-fill-c4-02",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 4 章",prompt:"John believes (that the airplane was invented by an Irishman). The part in the bracket is a c______ clause.",options:[],answer:"complement",acceptedAnswers:[],explanationZh:"that 从句作 believes 的补语，是补语分句。",difficulty:2},{id:"lg-fill-c4-03",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 4 章",prompt:"There is a tendency to make a distinction between phrase and w______, which is an extension of word of a particular class by way of modification with its main features of the class unchanged.",options:[],answer:"word group",acceptedAnswers:["word-group"],explanationZh:"词组是词的扩展，与所属词类功能相同。",difficulty:3},{id:"lg-fill-c4-04",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 4 章",prompt:"Traditionally, p______ is seen as part of a structural hierarchy, positioned between clause and word.",options:[],answer:"phrase",acceptedAnswers:[],explanationZh:"短语位于结构层级中分句与词之间。",difficulty:1},{id:"lg-fill-c4-05",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 4 章",prompt:"The case category is used in the analysis of word classes to identify the s______ relationship between words in a sentence.",options:[],answer:"syntactic",acceptedAnswers:[],explanationZh:"格范畴标明句法（syntactic）关系。",difficulty:2},{id:"lg-fill-c4-06",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 4 章",prompt:"Clause can be classified into FINITE and NON-FINITE clauses, the latter including the traditional infinitive phrase, p______, and gerundial phrase.",options:[],answer:"participial",acceptedAnswers:[],explanationZh:"非限定分句含不定式、分词、动名词短语。",difficulty:2},{id:"lg-fill-c4-07",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 4 章",prompt:"Gender displays such contrasts as masculine; feminine; n______.",options:[],answer:"neuter",acceptedAnswers:[],explanationZh:"性的对立有阳性、阴性、中性（neuter）。",difficulty:2},{id:"lg-fill-c4-08",nodeId:"lg-fill",categoryId:"lg-fill",kind:"short-answer",label:"第 4 章",prompt:"In the sentence the man was bitten by a dog, the man is both the g______ subject and the l______ object.",options:[],answer:"grammatical; logical",acceptedAnswers:["grammatical logical","grammatical, logical"],explanationZh:"the man 是语法主语，逻辑上是宾语（受事）。",difficulty:3},{id:"lg-fill-c4-09",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 4 章",prompt:"In the sentence it is no use crying over the milk, crying over the milk is a Non F______ clause.",options:[],answer:"Finite",acceptedAnswers:[],explanationZh:"crying over the milk 是动名词短语，属非限定分句。",difficulty:3},{id:"lg-fill-c4-10",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 4 章",prompt:"In the sentence the woman (that I love) is moving to the south, the part in the bracket is a r______ clause.",options:[],answer:"relative",acceptedAnswers:[],explanationZh:"that I love 修饰 the woman，是关系分句。",difficulty:2},{id:"lg-term-c4-01",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 4 章",prompt:"名词解释：IC analysis。先写下你的理解，再对照参考答案。",options:[],answer:"Immediate constituent analysis, IC analysis for short, refers to the analysis of a sentence in terms of its immediate constituents-word groups (phrases), which are in turn analyzed into the immediate constituents of their own, and the process goes unitl the ultimate sake of convenience.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c4-02",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 4 章",prompt:"名词解释：Relation of co-occurrence。先写下你的理解，再对照参考答案。",options:[],answer:"By the relation of co-occurrence, one means that words of different sets of clauses may permit, or require, the occurrence of a word of another set of class to form a sentence or a particular part of a sentence. For instance, a nominal phrase can be preceded by a determiner and adjective and followed by a verbal phrase.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c4-03",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 4 章",prompt:"名词解释：Category。先写下你的理解，再对照参考答案。",options:[],answer:"The term category in some approaches refers to classes and functions in its narrow sense, e.g., noun, verb, subject, predicate, noun phrase, verb phrase, etc. More specifically, it refers to the defining properties of these general units: the categories of the noun, for example, include number, gender, case and countability; and of the verb, for example, include tense, aspect, voice, etc.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c4-04",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 4 章",prompt:"名词解释：Recursiveness。先写下你的理解，再对照参考答案。",options:[],answer:"Though it mainly means that a phrasal constituent can be embedded within another constituent having the same category, recursiveness has become an umbrella term, under which may be brought together several important linguistic umbrella term, under which may be brought together several important linguistic hypotactic and paratactic. All these are means to extend sentences.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-match-c4-01",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 4 章",prompt:'"syntactic function" 对应下列哪一项？',options:["subject, predicate and object","Number, gender and case","coordination and subordination","conjunction, ellipsis, reference"],answer:"subject, predicate and object",acceptedAnswers:[],explanationZh:"句法功能包括主语、谓语、宾语等。",difficulty:2},{id:"lg-match-c4-02",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 4 章",prompt:'"category" 对应下列哪一项？',options:["Number, gender and case","subject, predicate and object","coordination and subordination","syntagmatic relation"],answer:"Number, gender and case",acceptedAnswers:[],explanationZh:"名词的范畴包括数、性、格等。",difficulty:2},{id:"lg-match-c4-03",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 4 章",prompt:'"positional relation" 对应下列哪一项？',options:["syntagmatic relation","paradigmatic relation","substitutability","conjoining and embedding"],answer:"syntagmatic relation",acceptedAnswers:[],explanationZh:"位置关系即横组合关系。",difficulty:3},{id:"lg-match-c4-04",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 4 章",prompt:'"associative relation" 对应下列哪一项？',options:["paradigmatic relation","syntagmatic relation","substitutability","conjoining and embedding"],answer:"paradigmatic relation",acceptedAnswers:[],explanationZh:"联想关系即纵聚合关系。",difficulty:3},{id:"lg-mc-c5-01",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"Which of the following is NOT included in G. Leech's seven types of meaning？",options:["Connotative meaning","Denotative meaning","Conceptual meaning","Affective meaning"],answer:"Denotative meaning",acceptedAnswers:[],explanationZh:"Leech 的七类意义不含 denotative meaning，其余三项都在其中。",difficulty:2},{id:"lg-mc-c5-02",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"Of the following pairs of words, ______ belongs to the type of complementary antonyms.",options:["teacher/student","captive/free","rich/poor","fast/slow"],answer:"captive/free",acceptedAnswers:[],explanationZh:"互补反义非此即彼：captive 与 free 互补，无中间状态。",difficulty:2},{id:"lg-mc-c5-03",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"Which of the following is concerned with word meaning?",options:["Compositionality principle","Truth value judgment","Logic semantics","Componential analysis"],answer:"Componential analysis",acceptedAnswers:[],explanationZh:"成分分析把词义分解为语义特征，直接研究词的意义。",difficulty:2},{id:"lg-mc-c5-04",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"______ is a way in which the meaning of a word can be dissected into meaning components, called semantic features.",options:["Predication analysis","Componential analysis","Phonemic analysis","Grammatical analysis"],answer:"Componential analysis",acceptedAnswers:[],explanationZh:"把词义分解为语义成分的方法即成分分析。",difficulty:2},{id:"lg-mc-c5-05",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"______ deals with the relationship between the linguistic element and the non-linguistic word of experience.",options:["Reference","Concept","Semantics","Sense"],answer:"Reference",acceptedAnswers:[],explanationZh:"指称研究语言形式与非语言世界的联系。",difficulty:2},{id:"lg-mc-c5-06",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"______ refers to the phenomenon that words having different meanings have the same form.",options:["Polysemy","Synonymy","Homonymy","Hyponymy"],answer:"Homonymy",acceptedAnswers:[],explanationZh:"同形异义（homonymy）：不同意义共享同一形式。",difficulty:2},{id:"lg-mc-c5-07",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"______ antonyms are also called relational opposites.",options:["Gradable","Complementary","Converse","Controversial"],answer:"Converse",acceptedAnswers:[],explanationZh:"反向反义词又称关系对立（relational opposites）。",difficulty:2},{id:"lg-mc-c5-08",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"In Leech's definition of meanings, ______ meaning is what is communicated by virtue of what language refers to.",options:["conceptual","social","connotative","collocative"],answer:"connotative",acceptedAnswers:[],explanationZh:"Leech 认为内涵意义是凭借语言所指传达的意义。",difficulty:3},{id:"lg-mc-c5-09",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"______ refers to the abstract properties of an entity；while ______ refers to the concrete entities having these properties.",options:["Reference, denotation","Connotation, denotation","Sense, connotation","Denotation, connotation"],answer:"Connotation, denotation",acceptedAnswers:[],explanationZh:"内涵指实体的抽象属性，外延指具有这些属性的具体实体。",difficulty:3},{id:"lg-mc-c5-10",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"To some extent, the difference between gradable and complementary antonyms can be compared to the traditional logical distinction between ______ and ______.",options:["denotation, connotation","contrary, contradictory","partially different, totally different","totally different, partially different"],answer:"contrary, contradictory",acceptedAnswers:[],explanationZh:"等级/互补反义之别可比作逻辑上的 contrary 与 contradictory。",difficulty:3},{id:"lg-mc-c5-11",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"______ is not the study of the truth conditions for propositions.",options:["Propositional logic","Propositional calculus","Sentential conditions","Sentential calculus"],answer:"Sentential conditions",acceptedAnswers:[],explanationZh:"研究命题真值条件的是命题逻辑、命题演算与语句演算。",difficulty:2},{id:"lg-mc-c5-12",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"A（n）______ is what is expressed by a declarative sentence when that sentence is uttered to make a statement.",options:["sentence","utterance","proposition","statement"],answer:"proposition",acceptedAnswers:[],explanationZh:"命题是陈述句用以作陈述时所表达的内容。",difficulty:2},{id:"lg-mc-c5-13",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"A very important property of the proposition is that it has a ______. It is either true or false.",options:["reality status","truth feature","false value","truth value"],answer:"truth value",acceptedAnswers:[],explanationZh:"命题具有真值（truth value），非真即假。",difficulty:2},{id:"lg-mc-c5-14",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"______ studies the internal structure of simple propositions.",options:["Semantic calculus","Propositional logic","Predicate calculus","Sentential logic"],answer:"Predicate calculus",acceptedAnswers:[],explanationZh:"谓词演算研究简单命题的内部结构。",difficulty:2},{id:"lg-mc-c5-15",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"The truth value of a proposition varies with the ______.",options:["predicate","argument","verb","place"],answer:"argument",acceptedAnswers:[],explanationZh:"命题真值随论元（argument）的不同而变化。",difficulty:3},{id:"lg-mc-c5-16",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"______ is the collection of all the features of the linguistic form；it is abstract and decontextualized.",options:["Sense","Referent","Denotation","Symbol"],answer:"Sense",acceptedAnswers:[],explanationZh:"意义（sense）是语言形式全部特征的集合，抽象且去语境化。",difficulty:2},{id:"lg-mc-c5-17",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"Componential analysis is a way proposed by the ______ semanticists to analyze the word meaning.",options:["structural","contextual","behavioral","conceptual"],answer:"structural",acceptedAnswers:[],explanationZh:"成分分析由结构主义语义学家提出。",difficulty:2},{id:"lg-mc-c5-18",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"Among the following pairs of words, ______ can be called converse opposites.",options:["old-young","alive-dead","male-female","doctor-patient"],answer:"doctor-patient",acceptedAnswers:[],explanationZh:"doctor-patient 体现两者关系的反转，属反向反义。",difficulty:2},{id:"lg-mc-c5-19",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"The word which is more general in meaning is called the ______, and the more specific words are called its ______.",options:["homophone, homograph","hyponym, co-hyponyms","synonymy, synonyms","superordinate, co-hyponyms"],answer:"superordinate, co-hyponyms",acceptedAnswers:[],explanationZh:"意义较一般的是上义词，较具体的是其同下义词。",difficulty:2},{id:"lg-mc-c5-20",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 5 章",prompt:"The following are factors that cause near synonyms EXCEPT ______.",options:["conceptual difference","stylistic difference","dialectal difference","connotative difference"],answer:"conceptual difference",acceptedAnswers:[],explanationZh:"近义词的差别在文体、方言、内涵，概念意义相同。",difficulty:3},{id:"lg-tf-c5-01",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 5 章",prompt:"Linguistic forms having the same sense may have different references in different situations.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"同义形式可随语境指称不同对象，如 the President 在不同时期指不同人。",difficulty:2},{id:"lg-tf-c5-02",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 5 章",prompt:"In the complementary pair true-false, there is no cover term.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"互补反义对有 cover term，如 truth value 涵盖 true 与 false。",difficulty:3},{id:"lg-tf-c5-03",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 5 章",prompt:"Every word has sense, but not every word has reference.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"每个词都有意义，但虚词（如 but、if）没有现实指称对象。",difficulty:2},{id:"lg-tf-c5-04",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 5 章",prompt:"Compositionality is a principle for sentence analysis, in which the meaning of a sentence depends on the meanings of the constituent words and the way they are combined.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"组合性原则：句义取决于成分词的意义及其组合方式。",difficulty:2},{id:"lg-tf-c5-05",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 5 章",prompt:"The meaning of a sentence is the sum total of the meanings of all its components.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"句义不是成分义的简单相加，还取决于组合方式。",difficulty:2},{id:"lg-tf-c5-06",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 5 章",prompt:"Semantics is the study of the meaning of linguistic units, words, phonemes and sentences in particular.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"音位本身没有意义，不是语义学的研究对象。",difficulty:2},{id:"lg-tf-c5-07",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 5 章",prompt:"Conceptual meaning is connotative in that it is concerned with the relationship between a word and the thing it connotes, or refers to.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"概念意义是外延性的（denotative），不是 connotative。",difficulty:3},{id:"lg-tf-c5-08",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 5 章",prompt:"There is usually an intermediate degree between the pair of two gradable antonyms, and usually the intermediate degree may be lexicalized.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"等级反义词之间常有中间程度并被词汇化，如 hot–warm–cool–cold。",difficulty:3},{id:"lg-tf-c5-09",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 5 章",prompt:"The adjectives in complementary antonymy can not be modified by very.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"互补反义无程度差别，不能说 very alive 或 very dead。",difficulty:2},{id:"lg-tf-c5-10",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 5 章",prompt:"If a pair of words is in relationship of converse antonymy, then the members of this pair do not only constitute a positive-negative opposition, but also show the reversal of a relationship between two entities.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"反向反义不构成正反对立，只体现两实体关系的反转，如 buy-sell。",difficulty:3},{id:"lg-fill-c5-01",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 5 章",prompt:"S______ can be defined as the study of meaning.",options:[],answer:"Semantics",acceptedAnswers:[],explanationZh:"语义学（Semantics）研究意义。",difficulty:2},{id:"lg-fill-c5-02",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 5 章",prompt:"Predict l______, also called predicate calculus, studies the internal structure of a simple proposition.",options:[],answer:"Logic",acceptedAnswers:[],explanationZh:"谓词逻辑（predicate logic）又称谓词演算。",difficulty:2},{id:"lg-fill-c5-03",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 5 章",prompt:"R______ means what a linguistic form refers to in the real, physical world, it deals with the relationship between the linguistic element and the non-linguistic world of experience.",options:[],answer:"Reference",acceptedAnswers:[],explanationZh:"指称（Reference）是语言形式在现实世界中所指的事物。",difficulty:2},{id:"lg-fill-c5-04",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 5 章",prompt:"The word that can be presented by the following semantic components BECOME(x,(~ALIVE(X))) should be d______.",options:[],answer:"die",acceptedAnswers:[],explanationZh:"BECOME(x,(~ALIVE(x))) 表示 x 变为非活着，即 die。",difficulty:3},{id:"lg-fill-c5-05",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 5 章",prompt:"Two words, or two expressions, which have the same semantic c______, will be synonymous with each other.",options:[],answer:"components",acceptedAnswers:[],explanationZh:"语义成分相同的两个词互为同义词。",difficulty:2},{id:"lg-fill-c5-06",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 5 章",prompt:"A theory which explicitly employs the notion of c______ is the semantic triangle proposed by Ogden and Richards. In their theory the notion functions as the relation mediator between a word and the thing it refers to.",options:[],answer:"concept",acceptedAnswers:[],explanationZh:"语义三角中，概念（concept）居中联系词与所指事物。",difficulty:3},{id:"lg-fill-c5-07",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 5 章",prompt:"C______ analysis is based upon the belief that the meaning of a word can be divided into meaning components.",options:[],answer:"Componential",acceptedAnswers:[],explanationZh:"成分分析（Componential analysis）认为词义可分解为语义成分。",difficulty:2},{id:"lg-fill-c5-08",nodeId:"lg-fill",categoryId:"lg-fill",kind:"short-answer",label:"第 5 章",prompt:"There are generally three kinds of sense relations recognized, namely, a______, s______ and h______.",options:[],answer:"antonymy, synonymy, hyponymy",acceptedAnswers:["antonymy synonymy hyponymy","antonymy,synonymy,hyponymy"],explanationZh:"三种意义关系：反义、同义、上下义。",difficulty:2},{id:"lg-fill-c5-09",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 5 章",prompt:"An a______ is a term which refers to some entity about which a statement is being made in predicate logic analysis.",options:[],answer:"argument",acceptedAnswers:[],explanationZh:"论元（argument）是谓词逻辑中命题所关涉的实体。",difficulty:3},{id:"lg-fill-c5-10",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 5 章",prompt:"The connective d______ (V) corresponds to the English “or”.",options:[],answer:"disjunction",acceptedAnswers:[],explanationZh:"连接词 disjunction（V）对应英语的 or。",difficulty:2},{id:"lg-term-c5-01",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 5 章",prompt:"名词解释：Converse antonymy。先写下你的理解，再对照参考答案。",options:[],answer:"Converse antonyms are also called relational opposites. This is a specific type of antonymy in that the members of a pair do not constitute a positive-negative opposition. They show the reversal of a relationship between two entities, e g. buy-sell, parent-child, above-below, etc.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c5-02",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 5 章",prompt:"名词解释：Hyponymy。先写下你的理解，再对照参考答案。",options:[],answer:"Hyponymy involves us in the notion of meaning inclusiveness. It is a matter of class membership. That is to say, when X is a kind of Y, the lower term X is the hyponym, and the upper term Y is the superordinate. Two or more hyponyms of the same One superordinate are called co-hyponyms, e g. under flower, there are peony, jasmine, tulip, violet, rose, etc. flower is the superordinate of peony, jasmine, etc., peony is the hyponym of flower, and peony, jasmine, tulip, violet, rose, etc. are co-hyponyms.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c5-03",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 5 章",prompt:"名词解释：Componential analysis。先写下你的理解，再对照参考答案。",options:[],answer:"Compositional analysis：It defines the meaning of a lexical element in terms of semantic components, or semantic features. For example, the meaning of the word boy may be analyzed into three components：HUMAN, YOUNG and MALE. Similarly, girl may be analyzed into HUMAN, YOUNG and FEMALE.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c5-04",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 5 章",prompt:"名词解释：Reference。先写下你的理解，再对照参考答案。",options:[],answer:"Reference：It is what a linguistic form refers to in the real world. It is a matter of the relationship between the form and the reality.",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"lg-short-c5-01",nodeId:"lg-short",categoryId:"lg-short",kind:"short-answer",label:"第 5 章",prompt:"What are the three kinds of antonymy?",options:[],answer:"Antonymy is the term for oppositeness relation. There are three subtypes：gradable, complementary and converse antonymy. （1）Gradable antonymy Gradable antonymy refers to the gradable oppositeness of meaning, because there are often intermediate forms between two gradable antonyms. Gradable antonymy is the commonest type of antonymy. They are mainly adjectives, eg. good-bad, long-short, big-small, etc. （2）Complementary antonymy The members in a pair in Complementary antonymy are complementary to each other. That is, they divide up the whole of a semantic field completely. Not only the assertion of one means the denial of the other, the denial of one also means the assertion of the other, e.g. alive-dead, hit-miss, male-female, boy-girl. etc. （3）Converse antonymy Converse antonyms are also called relational opposites. This is a special type of antonymy in that the members of a pair do not constitute a positive-negative opposition. They show the reversal of a relationship between two entities, e g. buy-sell, parent-child, above-below, etc.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-short-c5-02",nodeId:"lg-short",categoryId:"lg-short",kind:"short-answer",label:"第 5 章",prompt:"Give the logic expression of the following predications. 1) The flower is beautiful. 2) The boy likes football. 3) The man makes the room clean.",options:[],answer:"1) B(f) 2) L(b,f) 3) M(m,(C(r)))",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-short-c5-03",nodeId:"lg-short",categoryId:"lg-short",kind:"short-answer",label:"第 5 章",prompt:"Give the logic expression of the following existential and universal quantifier predications. Change the third one into an existential quantifiers expression. 1) Some girls wear short hairs. 2) All girls like beautiful clothes. 3) All roads lead to Rome.",options:[],answer:"1) ∃ x(G(x) ∧ W(x,sh)) 2) ∀ x (G(x) → L(x,bc)) 3) ∀ x (R(x) → Lt(x,r)) ≡ ~∃ x(R(x) ∧ ~Lt(x,r))",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"lg-mc-c6-01",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 6 章",prompt:"The formal approach of the study of language and cognition does NOT include the study of ______ structure.",options:["morphological","syntactic","lexical","semantic"],answer:"semantic",acceptedAnswers:[],explanationZh:"形式法研究形态、句法、词汇结构，不包括语义结构。",difficulty:2},{id:"lg-mc-c6-02",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 6 章",prompt:"______ lays in the central position in language comprehension because of its extremely important role in transmitting the meaning.",options:["Morpheme","word","phrase","Sentence"],answer:"word",acceptedAnswers:[],explanationZh:"词在传递意义中作用关键，处于语言理解的中心位置。",difficulty:2},{id:"lg-mc-c6-03",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 6 章",prompt:"Psycholinguists have proposed that the human sentence processor is primarily guided by information about specific words that is stored in the ______.",options:["lexicon","syntax","semantics","sound system"],answer:"lexicon",acceptedAnswers:[],explanationZh:"句法处理器主要依赖心理词库（lexicon）中的词信息。",difficulty:2},{id:"lg-mc-c6-04",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 6 章",prompt:"Reader abstract the main threads of a discourse and infer missing connections, constrained by limitations of short-term memory and guided by how ______ overlap across propositions and by linguistic cues signaled by the text.",options:["themes","arguments","subjects","objects"],answer:"arguments",acceptedAnswers:[],explanationZh:"读者依据命题间论元（arguments）的重叠来推断缺失的联系。",difficulty:3},{id:"lg-mc-c6-05",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 6 章",prompt:"Which of the following is NOT one of the aspects of process of language production?",options:["Conceptualization and linearization","Self-monitoring","gesturing during speech","Self-instructing"],answer:"Self-instructing",acceptedAnswers:[],explanationZh:"自我指令不属于语言产出的环节，概念化、自我监控与手势都是。",difficulty:2},{id:"lg-mc-c6-06",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 6 章",prompt:"______ is the process of classifying our experiences into different categories based on commonalities and differences.",options:["Judgment","Comparison","Categorization","Salience"],answer:"Categorization",acceptedAnswers:[],explanationZh:"按异同把经验分类即范畴化（categorization）。",difficulty:2},{id:"lg-mc-c6-07",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 6 章",prompt:"______ metaphor means that human experiences with physical objects provide the basis for ways of viewing events, activities, emotions, ideas, etc, as entities and substances.",options:["Structural","Orientational","Ontological","Semiotic"],answer:"Ontological",acceptedAnswers:[],explanationZh:"本体隐喻把事件、活动、情感等视为实体和物质。",difficulty:2},{id:"lg-mc-c6-08",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 6 章",prompt:"A ______ schema is an image schema that involves a physical or metaphorical boundary, enclosed area or volume, or excluded area or volume.",options:["containment","center-periphery","cycle","force"],answer:"containment",acceptedAnswers:[],explanationZh:"容器图式涉及物理或隐喻的边界与内外空间。",difficulty:2},{id:"lg-mc-c6-09",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 6 章",prompt:"A ______ schema involves a physical or metaphorical core and edge, and degrees of distance from the core.",options:["containment","center-periphery","cycle","force"],answer:"center-periphery",acceptedAnswers:[],explanationZh:"中心-边缘图式包含核心、边缘及距核心的距离程度。",difficulty:2},{id:"lg-mc-c6-10",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 6 章",prompt:"A ______ schema consists of two or more entities, connected physically or metaphorically, and the bond between them.",options:["link","part-whole","path","scale"],answer:"link",acceptedAnswers:[],explanationZh:"连接图式由两个以上实体及其间的纽带构成。",difficulty:2},{id:"lg-tf-c6-01",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 6 章",prompt:"The conceptual approach includes the study of morphological, syntactic, and lexical structure.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"研究形态、句法、词汇结构的是形式法；概念法关注概念内容的组织。",difficulty:2},{id:"lg-tf-c6-02",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 6 章",prompt:"The conceptual approach is concerned with the patterns in which and the processes by which conceptual content is organized in language.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"概念法关注概念内容在语言中的组织模式与过程。",difficulty:2},{id:"lg-tf-c6-03",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 6 章",prompt:"An important focus of psycholinguistics is the largely unconscious application of grammatical rules that enable people to produce and comprehend intelligible sentences.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"心理语言学关注人们无意识地运用语法规则产出和理解句子。",difficulty:3},{id:"lg-tf-c6-04",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 6 章",prompt:"In the 1960s and early 1970s numerous psychologists and linguists used the transformational-generative model proposed by Rene Dirven to discover how children come to know the grammatical processes that underlie the speech they hear and to investigate the processing and comprehension of language: spoken or written.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"转换生成模型由 Chomsky 提出，不是 Rene Dirven。",difficulty:2},{id:"lg-tf-c6-05",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 6 章",prompt:"In 1989, the first conference on cognitive linguistics was organized in Duisburg Germany, by Chomsky.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"1989 年首届认知语言学大会由 Rene Dirven 组织，不是 Chomsky。",difficulty:2},{id:"lg-tf-c6-06",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 6 章",prompt:"Charles Darwin, the founder of Evolution Theory, was one of the first keeping the dairy of his son's speech development.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"达尔文是最早记录儿子言语发展日记的人之一。",difficulty:2},{id:"lg-tf-c6-07",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 6 章",prompt:"Shortly before their first birthday, babies begin to understand words and around that birthday, they start to produce them.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"婴儿约一岁前开始理解词语，一岁前后开始产出词语。",difficulty:2},{id:"lg-tf-c6-08",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 6 章",prompt:"Around 12 months, language changes in two ways. Vocabulary growth increases; the child begins to learn words at a rate of one every two waking hours, and will keep learning that rate or faster through adolescence.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"词汇快速增长约从 18 个月开始，不是 12 个月。",difficulty:3},{id:"lg-tf-c6-09",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 6 章",prompt:"Before they put words together, babies cannot comprehend a sentence.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"婴儿在会组词之前就已能理解句子，理解先于产出。",difficulty:2},{id:"lg-tf-c6-10",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 6 章",prompt:"Normal children can differ by a year or more in their rate of language development though the stages they pass through are generally the same regardless of how stretcher out or compressed and many children speak in complex sentences before they turn two.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"正常儿童语言发展速度可相差一年以上，但所经阶段大体相同。",difficulty:3},{id:"lg-fill-c6-01",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"C______ linguistics has addressed the structuring within language of such basic conceptual categories as those of space and time, scenes and event, entities and processes, motion and location, and force and causation.",options:[],answer:"Cognitive",acceptedAnswers:[],explanationZh:"认知语言学研究空间、时间等基本概念范畴的语言结构。",difficulty:2},{id:"lg-fill-c6-02",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"Shortly before their f______ birthday, babies begin to understand words, and around that birthday, they start to produce them.",options:[],answer:"first",acceptedAnswers:[],explanationZh:"一岁前不久婴儿开始理解词，一岁左右开始产出。",difficulty:1},{id:"lg-fill-c6-03",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"P______ models emphasize that the comprehension system is sensitive to a vast range of information, including grammatical, lexical, and contextual, as well as knowledge of the speaker / writer and of the world in general.",options:[],answer:"Parallel",acceptedAnswers:[],explanationZh:"并行模型强调理解系统对各类信息都敏感。",difficulty:3},{id:"lg-fill-c6-04",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"In generating sentences, the first step is again c______ preparation - deciding what to say.",options:[],answer:"conceptual",acceptedAnswers:[],explanationZh:"生成句子的第一步是概念准备，即决定说什么。",difficulty:2},{id:"lg-fill-c6-05",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"The most popular principle interpreting sentence comprehension with respect to the grammatical constraints is Minimal a______ which defines structurally simpler, and it claims that structural simplicity guides all initial analyses in sentence comprehension.",options:[],answer:"attachment",acceptedAnswers:[],explanationZh:"最小附着原则主张结构越简单越优先。",difficulty:3},{id:"lg-fill-c6-06",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"Evidence for the distinction between functional and positional processes comes from the finding that some speech errors can best be explained as errors of functional e______.",options:[],answer:"encoding",acceptedAnswers:[],explanationZh:"某些言语失误可用功能编码错误来解释。",difficulty:3},{id:"lg-fill-c6-07",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"C______ operations are conceptualizing processes used in language process by human beings.",options:[],answer:"Construal",acceptedAnswers:[],explanationZh:"误解操作是语言加工中的概念化过程。",difficulty:3},{id:"lg-fill-c6-08",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"In cognitive terms, d______ is the use of elements of subjects situatedness to designate something in the scene.",options:[],answer:"deixis",acceptedAnswers:[],explanationZh:"指示（deixis）利用说话者所处情境来指称场景中的事物。",difficulty:3},{id:"lg-fill-c6-09",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"Linguistically, names for s______ categories are often mass nouns when basic level terms are count nouns.",options:[],answer:"superordinate",acceptedAnswers:[],explanationZh:"上位范畴名称常用物质名词，基本层次词用可数名词。",difficulty:3},{id:"lg-fill-c6-10",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"Often the names for s______ level categories are morphologically complex. They are typically composite terms.",options:[],answer:"subordinate",acceptedAnswers:[],explanationZh:"下位层次范畴名称形态复杂，多为复合词。",difficulty:3},{id:"lg-fill-c6-11",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"Mark Johnson defines an image s______ as a recurring, dynamic pattern of our perceptual interactions and motor programs that gives coherence and structure to our experience.",options:[],answer:"schema",acceptedAnswers:[],explanationZh:"意象图式是知觉互动与运动程序的复现模式。",difficulty:3},{id:"lg-fill-c6-12",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"The t______ domain is the experience being described by the metaphor and the source domain is the means that we use in order to describe the experience.",options:[],answer:"target",acceptedAnswers:[],explanationZh:"目标域是被隐喻描述的体验，源域是描述它的手段。",difficulty:2},{id:"lg-fill-c6-13",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"O______ metaphors are based on human physical and cultural experience. For example, in some cultures the future is in front of us, whereas in others it is in back of us",options:[],answer:"Orientational",acceptedAnswers:[],explanationZh:"方位隐喻基于人的身体与文化经验。",difficulty:2},{id:"lg-fill-c6-14",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"M______ in the cognitive literature is modeled as idealized cognitive models (ICMs).",options:[],answer:"Metonymy",acceptedAnswers:[],explanationZh:"转喻在认知文献中被建模为理想化认知模型。",difficulty:2},{id:"lg-fill-c6-15",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 6 章",prompt:"Fauconnier and Turner propose and discuss B______ theory, a cognitive operation whereby elements of two or more mental spaces are integrated via projection into a new, blended space which has its unique structure.",options:[],answer:"Blending",acceptedAnswers:[],explanationZh:"Fauconnier 与 Turner 提出概念整合（Blending）理论。",difficulty:3},{id:"lg-term-c6-01",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 6 章",prompt:"名词解释：Link schema。先写下你的理解，再对照参考答案。",options:[],answer:"Link schema consists of two or more entities, connected physically or metaphorically, and the bond between them. Here are some examples of link schemas: a child holding her mother's hand, someone plugging a lamp into the wall, a causal connection, kinship ties.",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"lg-match-c6-01",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 6 章",prompt:"Thing-and-part ICM 对应下列哪个例子？",options:["England for “the Great Britain”","jerk for “stupidity”","the pill for “birth control”","Bill smoked marijuana"],answer:"England for “the Great Britain”",acceptedAnswers:[],explanationZh:"部分代整体：England 是 Great Britain 的组成部分。",difficulty:3},{id:"lg-match-c6-02",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 6 章",prompt:"Constitution ICM 对应下列哪个例子？",options:["wood for “forest”","crude for “crude oil”","How old are you? for “what is your age?”","to author a new book"],answer:"wood for “forest”",acceptedAnswers:[],explanationZh:"材料代整体：wood 是构成 forest 的材料。",difficulty:3},{id:"lg-match-c6-03",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 6 章",prompt:"Category-and-Member ICM 对应下列哪个例子？",options:["the pill for “birth control”","England for “the Great Britain”","sight for “thing seen”","wood for “forest”"],answer:"the pill for “birth control”",acceptedAnswers:[],explanationZh:"成员代范畴：the pill 是避孕药范畴的典型成员。",difficulty:3},{id:"lg-match-c6-04",nodeId:"lg-match",categoryId:"lg-match",kind:"multiple-choice",label:"第 6 章",prompt:"Perception ICM 对应下列哪个例子？",options:["sight for “thing seen”","slow road for “slow traffic resulting from the poor state of the road”","Bill smoked marijuana","crude for “crude oil”"],answer:"sight for “thing seen”",acceptedAnswers:[],explanationZh:"感知代被感知物：sight（看）代所看到的事物。",difficulty:3},{id:"lg-short-c6-01",nodeId:"lg-short",categoryId:"lg-short",kind:"short-answer",label:"第 6 章",prompt:"Analyze the following metaphor with your linguistic knowledge. HAPPY IS UP; SAD IS DOWN",options:[],answer:"Orientational metaphor gives a concept a spatial orientation. They are characterized not so much by structuring one concept in terms of another, but by a co-occurrence in our experience. The orientational metaphors are grounded in an experiential basis, which link together the two parts of the metaphor. The link verb is, part of the metaphor, should be seen as the link of two different co-occurring experiences. For example, MORE IS UP. This metaphor is grounded in the co-occurrence of two different kinds of experiences: adding more of a substance and perceiving the level of the substance rise. Orientational metaphors are based on human physical and cultural experience. For example, in some cultures the future is in front of us, whereas in others it is in back of us. Now let us study some orientational metaphors and give a brief hint about how each metaphorical concept might have arisen from human physical and cultural experience (Lakoff & Johnson, 1980): HAPPY IS UP; SAD IS DOWN a. I'm feeling up. b. That boosted my spirits. c. My spirits rose. d. You're in high spirits. e. Thinking about her always gives me a lift. f. I'm feeling down. g. I'm depressed． h. He's really low these days. i. I fell into a depression. j. My spirits sank From these sentences above, it is obvious that drooping posture typically goes along with sadness and depression, erect posture with a positive state.",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"lg-mc-c7-01",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 7 章",prompt:"______ is concerned with the social significance of language variation and language use in different speech communities.",options:["Psycholinguistics","Sociolinguistics","Applied linguistics","General linguistics"],answer:"Sociolinguistics",acceptedAnswers:[],explanationZh:"社会语言学关注语言变异的社会意义与社团使用。",difficulty:1},{id:"lg-mc-c7-02",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 7 章",prompt:"Which of the following is NOT seen as the representatives of an anthropological orientation from North America?",options:["Franz Boas","Edward Sapir","John Firth","Benjamin Lee"],answer:"John Firth",acceptedAnswers:[],explanationZh:"John Firth 是英国学者，不属于北美人类学取向代表。",difficulty:2},{id:"lg-mc-c7-03",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 7 章",prompt:"______ developed his own theory of Context of Situation.",options:["Franz Boas","Edward Sapir","John Firth","Benjamin Lee"],answer:"John Firth",acceptedAnswers:[],explanationZh:"情景语境理论由 Firth 提出。",difficulty:2},{id:"lg-mc-c7-04",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 7 章",prompt:"______ is the first three stages in the Evolutionary Stages of Basic Color Words proposed by Berlin and Kay.",options:["White/black → green → yellow → red","Red → green/yellow → white/ black","White/ black → red → green/ yellow","Green/ yellow → white/ black → red"],answer:"White/ black → red → green/ yellow",acceptedAnswers:[],explanationZh:"Berlin 与 Kay 颜色词演化前三阶段：白/黑 → 红 → 绿/黄。",difficulty:3},{id:"lg-mc-c7-05",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 7 章",prompt:"______ do(es) NOT belong to the sociolinguistic study of language.",options:["Address forms","Bilingualism","Gender differences","Pidgin"],answer:"Gender differences",acceptedAnswers:[],explanationZh:"此题按 Keys 选 C：address forms、bilingualism、pidgin 均为社会语言学议题。",difficulty:3},{id:"lg-mc-c7-06",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 7 章",prompt:"______ in a person's speech or writing usually ranges on a continuum from casual or colloquial to formal or polite according to the type of communicative situation.",options:["Regional variation","Changes in emotions","Variation in connotations","Stylistic variation"],answer:"Stylistic variation",acceptedAnswers:[],explanationZh:"文体变异随交际场合在随便与正式之间连续变化。",difficulty:2},{id:"lg-mc-c7-07",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 7 章",prompt:"A ______ is a variety of language that serves as a medium of communication among groups of people for diverse linguistic backgrounds.",options:["lingua franca","register","Creole","National language"],answer:"lingua franca",acceptedAnswers:[],explanationZh:"供不同语言背景人群交流的通用语是 lingua franca。",difficulty:2},{id:"lg-mc-c7-08",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 7 章",prompt:"Although ______ are simplified languages with reduced grammatical features, they are rule-governed, like any human language.",options:["vernacular languages","creoles","pidgins","Sociolects"],answer:"pidgins",acceptedAnswers:[],explanationZh:"皮钦语语法特征简化，但仍像任何人类语言一样受规则支配。",difficulty:2},{id:"lg-mc-c7-09",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 7 章",prompt:"In normal situations, ______ speakers tend to use more prestigious forms than their ______ counterparts with the same social background.",options:["female; male","male; female","old; young","young; old"],answer:"female; male",acceptedAnswers:[],explanationZh:"同等社会背景下，女性比男性更倾向使用声望形式。",difficulty:2},{id:"lg-mc-c7-10",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 7 章",prompt:"A linguistic ______ refers to a word or expression that is prohibited by the polite society from general use.",options:["slang","euphemism","Jargon","taboo"],answer:"taboo",acceptedAnswers:[],explanationZh:"被礼貌社会禁止使用的词或表达叫禁忌语（taboo）。",difficulty:2},{id:"lg-tf-c7-01",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 7 章",prompt:"At the start of the 19th century, an anthropological orientation in the study of language was developed both in England and North America.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"人类学取向兴起于 20 世纪初，不是 19 世纪初。",difficulty:2},{id:"lg-tf-c7-02",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 7 章",prompt:"The Firthian tradition was further developed by the founder of systemic-functional linguistics, Halliday.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"Firth 传统由系统功能语言学创始人 Halliday 进一步发展。",difficulty:2},{id:"lg-tf-c7-03",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 7 章",prompt:"The investigation of basic color vocabulary conducted by Brent Berlin and Paul Kay revealed the same findings as the Sapir-Whorf Hypothesis.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"Berlin 与 Kay 发现颜色词有普遍规律，与 Sapir-Whorf 假说相左。",difficulty:3},{id:"lg-tf-c7-04",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 7 章",prompt:"There are ONLY two basic color words in the language Dani",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"Dani 语只有两个基本颜色词（黑与白）。",difficulty:2},{id:"lg-tf-c7-05",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 7 章",prompt:"Kaplan claims that the structural organization of a text tends to be culturally specific.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"Kaplan 认为语篇的结构组织具有文化特殊性。",difficulty:2},{id:"lg-tf-c7-06",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 7 章",prompt:"There has been a maxim from Robin Lakoff in sociolinguistics which claims that you are what you say.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"Robin Lakoff 的名言：you are what you say，言语体现说话者。",difficulty:2},{id:"lg-tf-c7-07",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 7 章",prompt:"William Labov's objective for having the sociolinguistic investigation was to examine the relationships between speakers' gender and their phonological variations.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"Labov 考察的是社会阶层与语音变异的关系，不是性别。",difficulty:3},{id:"lg-tf-c7-08",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 7 章",prompt:"Carl Rogers states that real communication takes place when we listen with understanding.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"Carl Rogers 认为带着理解倾听才是真正的交流。",difficulty:2},{id:"lg-tf-c7-09",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 7 章",prompt:"Linguistic universality is a property that all languages have, or a statement that holds for all languages.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"语言普遍性指所有语言共有的属性或普遍成立的陈述。",difficulty:2},{id:"lg-tf-c7-10",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 7 章",prompt:"The bound root “-gate” enjoys a rich productivity in American English, such as in the words Billy gate, Debate gate and Ricegate.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"-gate 是源自 Watergate 的后缀（组合形式），不是 bound root。",difficulty:3},{id:"lg-fill-c7-01",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 7 章",prompt:"The social group isolated for any given study is called the speech c______",options:[],answer:"community",acceptedAnswers:[],explanationZh:"言语社团（speech community）是为研究所划定的社会群体。",difficulty:2},{id:"lg-fill-c7-02",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 7 章",prompt:"As early as in the 1920s, a school of a______ study of linguistics came into being in England.",options:[],answer:"anthropological",acceptedAnswers:[],explanationZh:"20 世纪 20 年代英国兴起了人类学取向的语言研究。",difficulty:2},{id:"lg-fill-c7-03",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 7 章",prompt:"What Firth emphasized in the theory of Context of Situation is quite similar to a more updating sociological a______ in language use.",options:[],answer:"axiom",acceptedAnswers:[],explanationZh:"Firth 强调的情景语境近似语言使用中的社会学公理。",difficulty:3},{id:"lg-fill-c7-04",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 7 章",prompt:"The experience and his study of Hopi, an American Indian language, helped Whorf develop his unique understanding of linguistic r______, which is widely known as the SAPIR-WHORF HYPOTHESES.",options:[],answer:"relativity",acceptedAnswers:[],explanationZh:"对 Hopi 语的研究使 Whorf 形成语言相对论。",difficulty:2},{id:"lg-fill-c7-05",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 7 章",prompt:"The resurrection of a d______ view of linguistic inquiry, however, came into being in the 1960s, along with the development of sociolinguistics as an opposition to the dominant theory of Chomskyan linguistics.",options:[],answer:"dualistic",acceptedAnswers:[],explanationZh:"20 世纪 60 年代二元论语言研究观随社会语言学复兴。",difficulty:3},{id:"lg-fill-c7-06",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 7 章",prompt:"Robin Lakoff's hypotheses suggest that here exists a women r______ in the language.",options:[],answer:"register",acceptedAnswers:[],explanationZh:"Lakoff 假设语言中存在女性语域（women's register）。",difficulty:2},{id:"lg-fill-c7-07",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 7 章",prompt:"We can either classify sociolinguistic studies by means of hierarchical division, or alternatively, by means of an o______ categorization.",options:[],answer:"orientational",acceptedAnswers:[],explanationZh:"社会语言学研究可按层级划分或按取向分类。",difficulty:3},{id:"lg-fill-c7-08",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 7 章",prompt:"Hymes' theory of Communicative C______ was introduced into language teaching in the middle of the 1970s.",options:[],answer:"Competence",acceptedAnswers:[],explanationZh:"Hymes 的交际能力理论 70 年代中期进入语言教学。",difficulty:2},{id:"lg-fill-c7-09",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 7 章",prompt:"Successful communication occurs when the two parties adopt a d______ dialogue pattern.",options:[],answer:"dynamic",acceptedAnswers:[],explanationZh:"双方采取动态对话模式时，交际才能成功。",difficulty:2},{id:"lg-fill-c7-10",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 7 章",prompt:"A pidgin typically lacks in i______ morphemes.",options:[],answer:"inflectional",acceptedAnswers:[],explanationZh:"皮钦语通常缺乏屈折语素。",difficulty:2},{id:"lg-term-c7-01",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 7 章",prompt:"名词解释：Speech Community。先写下你的理解，再对照参考答案。",options:[],answer:"Speech community refers to any group of people whose language or use of language can be taken as a coherent object of study. Speakers of English can be treated as such a community; also, e. g. speakers of a distinct variety that one might call “Birmingham English”, spoken or usually spoken by part of the population of Birmingham. So might any other population that meets some test of coherence, whether large or small, bilingual or monolingual, in a single place or scattered.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c7-02",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 7 章",prompt:"名词解释：Communicative Competence。先写下你的理解，再对照参考答案。",options:[],answer:"Communicative competence: Coined by D. Hymes in his ethnography of communication, this term is a critical expansion of N. Chomsky's concept of competence. Communicative competence is the fundamental concept of a pragma-linguistic model of linguistic communication: it refers to the repertoire of know-how that individuals must develop if they are to be able to communicate with one another appropriately in the changing situations and conditions. In this model, speaking is understood as the action of transmitting symbols (i. e. interaction). Communicative competence is the descriptive goal of various social-psychological disciplines.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c7-03",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 7 章",prompt:"名词解释：Context of Situation。先写下你的理解，再对照参考答案。",options:[],answer:"Context of situation: Used by Firth to cover all the relevant circumstances in which a specific act of speech takes place. It can be summarized as the relevant features, the verbal action, and the non-verbal action of the participants, the relevant objects and the effects of the verbal action. The term was originally that of the anthropologist B Malinowski. E. g. when a specific person says on a specific occasion Well played!, it might be part of the context of situation that the speaker is sitting, with others, watching a cricket match, that a batsman has driven for four through covers, that the speaker is from a certain background, and so on. In the analysis of a language, features recurring in individual utterances (considered again as specific acts of speech) will be related to specific types of situation and to specific features in them.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c7-04",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 7 章",prompt:"名词解释：Linguistic Universality。先写下你的理解，再对照参考答案。",options:[],answer:"Linguistic universality is a property that all languages have, or a statement that holds for all languages.",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"lg-mc-c8-01",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 8 章",prompt:"What essentially distinguishes semantics and pragmatics is whether in the study of meaning ______ is considered.",options:["reference","speech act","practical usage","context"],answer:"context",acceptedAnswers:[],explanationZh:"语义学与语用学的本质区别在于是否考虑语境。",difficulty:2},{id:"lg-mc-c8-02",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 8 章",prompt:"A sentence is a ______ concept, and the meaning of a sentence is often studied in isolation.",options:["pragmatic","grammatical","mental","conceptual"],answer:"grammatical",acceptedAnswers:[],explanationZh:"句子是语法概念，句义常脱离语境孤立研究。",difficulty:2},{id:"lg-mc-c8-03",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 8 章",prompt:"If we think of a sentence as what people actually utter in the course of communication, it becomes a (n) ______.",options:["constative","directive","utterance","expressive"],answer:"utterance",acceptedAnswers:[],explanationZh:"句子在交际中被实际说出就成为话语（utterance）。",difficulty:2},{id:"lg-mc-c8-04",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 8 章",prompt:"Which of the following is true?",options:["Utterances usually do not take the form of sentences","Some utterances cannot be restored to complete sentences","No utterances can take the form of sentences","All utterances can be restored to complete sentences"],answer:"Some utterances cannot be restored to complete sentences",acceptedAnswers:[],explanationZh:"有些话语（如 Hello!、Fire!）不能还原为完整句。",difficulty:2},{id:"lg-mc-c8-05",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 8 章",prompt:"Speech act theory did not come into being until ______.",options:["in the late 50's of the 20the century","in the early 1950's","in the late 1960's","in the early 21st century"],answer:"in the late 50's of the 20the century",acceptedAnswers:[],explanationZh:"言语行为理论 20 世纪 50 年代末才出现。",difficulty:2},{id:"lg-mc-c8-06",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 8 章",prompt:"______ is the act performed by or resulting from saying something; it is the consequence of, or the change brought about by the utterance.",options:["A locutionary act","An illocutionary act","A perlocutionary act","A performative act"],answer:"A perlocutionary act",acceptedAnswers:[],explanationZh:"取效行为是话语带来的结果或变化。",difficulty:2},{id:"lg-mc-c8-07",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 8 章",prompt:"According to Searle, the illocutionary point of the representative is ______.",options:["to get the hearer to do something","to commit the speaker to something's being the case","to commit the speaker to some future course of action","to express the feelings or attitude towards an existing state of affairs"],answer:"to commit the speaker to something's being the case",acceptedAnswers:[],explanationZh:"阐述类的言外之的是使说话人承诺某事为真。",difficulty:3},{id:"lg-mc-c8-08",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 8 章",prompt:"All the acts that belong to the same category share the same purpose, but they differ ______.",options:["in their illocutionary acts","in their intentions expressed","in their strength or force","in their effect brought about"],answer:"in their strength or force",acceptedAnswers:[],explanationZh:"同类言语行为目的相同，但力度（force）不同。",difficulty:2},{id:"lg-mc-c8-09",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 8 章",prompt:"______ is advanced by Paul Grice",options:["Cooperative Principle","Politeness Principle","The General Principle of Universal Grammar","Adjacency Principle"],answer:"Cooperative Principle",acceptedAnswers:[],explanationZh:"合作原则由 Paul Grice 提出。",difficulty:1},{id:"lg-mc-c8-10",nodeId:"lg-mc",categoryId:"lg-mc",kind:"multiple-choice",label:"第 8 章",prompt:"When any of the maxims under the cooperative principle is flouted, ______ might arise.",options:["impoliteness","contradictions","mutual understanding","conversational implicatures"],answer:"conversational implicatures",acceptedAnswers:[],explanationZh:"违反合作原则准则会产生会话含义。",difficulty:2},{id:"lg-tf-c8-01",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 8 章",prompt:"Pragmatics treats the meaning of language as something intrinsic and inherent.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"把意义视为内在固有的是语义学视角；语用学关注语境。",difficulty:2},{id:"lg-tf-c8-02",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 8 章",prompt:"It would be impossible to give an adequate description of meaning if the context of language use was left unconsidered.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"不考虑语境就无法充分描写意义。",difficulty:2},{id:"lg-tf-c8-03",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 8 章",prompt:"What essentially distinguishes semantics and pragmatics is whether in the study of meaning the context of use is considered.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"语义学与语用学的分野在于是否考虑使用语境。",difficulty:2},{id:"lg-tf-c8-04",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 8 章",prompt:"The major difference between a sentence and an utterance is that a sentence is not uttered while an utterance is.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"句子是抽象单位，utterance 是具体说出的事件，被说出的句子即成为话语。",difficulty:3},{id:"lg-tf-c8-05",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 8 章",prompt:"The meaning of a sentence is abstract, but context-dependent.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"句义抽象但去语境化；依赖语境的是话语意义。",difficulty:2},{id:"lg-tf-c8-06",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 8 章",prompt:"The meaning of an utterance is decontexualized, therefore stable.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"话语意义依赖语境，并不稳定。",difficulty:2},{id:"lg-tf-c8-07",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 8 章",prompt:"Utterances always take the form of complete sentences",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"话语常以不完整句形式出现，如 Hello!、Fire!",difficulty:1},{id:"lg-tf-c8-08",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 8 章",prompt:"Speech act theory was originated with the British philosopher John Searle.",options:["True","False"],answer:"False",acceptedAnswers:[],explanationZh:"言语行为理论源自英国哲学家 John Austin，Searle 是其系统化者。",difficulty:3},{id:"lg-tf-c8-09",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 8 章",prompt:"Speech act theory started in the late 50's of the 20th century.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"言语行为理论始于 20 世纪 50 年代末。",difficulty:1},{id:"lg-tf-c8-10",nodeId:"lg-tf",categoryId:"lg-tf",kind:"true-false",label:"第 8 章",prompt:"Austin made the distinction between a constative and a performative.",options:["True","False"],answer:"True",acceptedAnswers:[],explanationZh:"Austin 区分了表述句（constative）与施为句（performative）。",difficulty:2},{id:"lg-fill-c8-01",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 8 章",prompt:"The notion of ______ is essential to the pragmatic study of language.",options:[],answer:"context",acceptedAnswers:[],explanationZh:"语境（context）概念是语用学研究的关键。",difficulty:2},{id:"lg-fill-c8-02",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 8 章",prompt:"If we think of a sentence as what people actually utter in the course of communication, it becomes an ______.",options:[],answer:"utterance",acceptedAnswers:[],explanationZh:"实际说出的句子即话语（utterance）。",difficulty:2},{id:"lg-fill-c8-03",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 8 章",prompt:"The meaning of a sentence is ______, and decontexualized.",options:[],answer:"abstract",acceptedAnswers:[],explanationZh:"句义抽象且去语境化。",difficulty:2},{id:"lg-fill-c8-04",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 8 章",prompt:"______ are statements that either state or describe, and are thus verifiable.",options:[],answer:"Constatives",acceptedAnswers:[],explanationZh:"表述句陈述或描写事实，因此可验证。",difficulty:2},{id:"lg-fill-c8-05",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 8 章",prompt:"______ are sentences that do not state a fact or describe a state, and are not verifiable.",options:[],answer:"Performatives",acceptedAnswers:[],explanationZh:"施为句不陈述事实，不可验证。",difficulty:2},{id:"lg-fill-c8-06",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 8 章",prompt:"A(n) ______ act is the act of uttering words, phrases, clauses. It is the act of conveying literal meaning by means of syntax, lexicon and phonology.",options:[],answer:"locutionary",acceptedAnswers:[],explanationZh:"言内行为是说出词句、传达字面意义的行为。",difficulty:2},{id:"lg-fill-c8-07",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 8 章",prompt:"A(n) ______ act is the act of expressing the speaker's intention; it is the act performed in saying something.",options:[],answer:"illocutionary",acceptedAnswers:[],explanationZh:"言外行为表达说话者的意图。",difficulty:2},{id:"lg-fill-c8-08",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 8 章",prompt:"A(n) ______ is to commit the speaker himself to some future course of action.",options:[],answer:"commissive",acceptedAnswers:[],explanationZh:"承诺类使说话人承诺未来的行动。",difficulty:2},{id:"lg-fill-c8-09",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 8 章",prompt:"A(n) ______ is to express feelings or attitude towards an existing state.",options:[],answer:"expressive",acceptedAnswers:[],explanationZh:"表达类表达对现存事态的情感或态度。",difficulty:2},{id:"lg-fill-c8-10",nodeId:"lg-fill",categoryId:"lg-fill",kind:"spelling",label:"第 8 章",prompt:"There are four maxims under the cooperative principle: the maxim of ______, the maxim of quality, the maxim of relation and the maxim of manner.",options:[],answer:"quantity",acceptedAnswers:[],explanationZh:"合作原则四准则：量、质、关系、方式。",difficulty:2},{id:"lg-term-c8-01",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 8 章",prompt:"名词解释：Conversational implicature。先写下你的理解，再对照参考答案。",options:[],answer:"In our daily life, speakers and listeners involved in conversation are generally cooperating with each other. In other words, when people are talking with each other, they must try to converse smoothly and successfully. In accepting speakers' presuppositions, listeners have to assume that a speaker is not trying to mislead them. This sense of cooperation is simply one in which people having a conversation are not normally assumed to be trying to confuse, trick, or withhold relevant information from one another. However, in real communication, the intention of the speaker is often not the literal meaning of what he or she says. The real intention implied in the words is called conversational implicature.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-term-c8-02",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 8 章",prompt:"名词解释：Performative。先写下你的理解，再对照参考答案。",options:[],answer:"In speech act theory an utterance which performs an act, such as Watch out (= a warning).",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"lg-term-c8-03",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 8 章",prompt:"名词解释：Locutionary act。先写下你的理解，再对照参考答案。",options:[],answer:"A locutionary act is the saying of something which is meaningful and can be understood.",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"lg-term-c8-04",nodeId:"lg-term",categoryId:"lg-term",kind:"short-answer",label:"第 8 章",prompt:"名词解释：Q-principle (Horn)。先写下你的理解，再对照参考答案。",options:[],answer:"Horn's Q-principle: (1) Make your contribution sufficient (cf. quantity); (2) Say as much as you can (given R).",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-short-c8-01",nodeId:"lg-short",categoryId:"lg-short",kind:"short-answer",label:"第 8 章",prompt:'Explain the following remarks with examples or make some comments. "Both semantics and pragmatics are concerned with meaning, but the difference between them can be traced to two different uses of the verb mean: (a) What does X mean? (b) What did you mean by X?"',options:[],answer:"Pragmatics is the study of the use of language in communication, particularly the relationships between sentences and the contexts and situations in which they are used. Pragmatics includes the study of (1) How the interpretation and use of utterances depends on knowledge of the real world; (2) How speakers use and understand speech acts; (3) How the structure of sentences is influenced by the relationship between the speaker and the hearer. Pragmatics is sometimes contrasted with semantics, which deals with meaning without reference to the users and communicative functions of sentences.",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"lg-short-c8-02",nodeId:"lg-short",categoryId:"lg-short",kind:"short-answer",label:"第 8 章",prompt:"Do you think B is cooperative in the following dialogue? Support your argument with Cooperative Principle. A: When is the bus coming? B: There has been an accident further up the road.",options:[],answer:`Yes, B is cooperative. On the face of it, B's statement is not an answer to A's question. B doesn't say "when." However, A will immediately interpret the statement as meaning "I don't know" or "I am not sure." Just assume that B is being "relevant" and "informative." Given that B's answer contains relevant information, A can work out that "an accident further up the road" conventionally involves "traffic jam," and "traffic jam" preludes "bus coming." Thus, B's answer is not simply a statement of "when the bus comes"; it contains an implicature concerning "when the bus comes."`,acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"lg-short-c8-03",nodeId:"lg-short",categoryId:"lg-short",kind:"short-answer",label:"第 8 章",prompt:"What kind of linguistic phenomenon can you identify in the following dialogue? Define, analyze and explain the phenomenon. 甲：上车请买票。乙：三张天安门。甲：您拿好。",options:[],answer:"According to Speech Act Theory, we are performing actions when we are speaking, and a speaker might be performing three acts simultaneously when speaking: locutionary act, illocutionary act, and perlocutionary act. A) A locutionary act is the act of uttering words, phrases, clauses. It is the act of conveying literal meaning by means of syntax lexicon and phonology. B) An illocutionary act is the act of expressing the speaker's intention; it is the act performed in saying something. C) A perlocutionary act is the act performed by or resulting from saying something; it is the consequence of, or the change brought about by the utterance; it is the act performed by saying something. According to the Speech Act Theory, when 甲 said：''上车请买票。''，its locutionary act is that the ticket seller is speaking the sentence. Its illocutionary act is to ask the passengers to buy tickets for their ride. Since the passengers give an active correspondence, the ticket seller realized his intention so the perlocutionary act of the first sentence is that the passengers bought the tickets for their ride. When 乙 said:“三张天安门。”，its locutionary act is that he is speaking the sentence. Its illocutionary act is to buy three tickets to Tian An Men, and its perlocutionary act is that the ticket seller give him the tickets, and he said“您拿好。”",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"lg-short-c8-04",nodeId:"lg-short",categoryId:"lg-short",kind:"short-answer",label:"第 8 章",prompt:"What do you know about Grice's Cooperative Principle? Explain with examples.",options:[],answer:"Grice's idea is that in making conversation, the participants must first of all be willing to cooperate; otherwise, it would not be possible for them to carry on the talk. This general principle is called the Cooperative Principle, abbreviated as CP. It goes as follows: make your conversational contribution such as required at the stage at which it occurs by the accepted purpose or direction of the talk exchange in which you are engaged. To be more specific, there are four maxims under this general principle: The maxim of quantity: a. Make your contribution as informative as required. b. Don't make your contribution more informative than is required. The maxim of quality a. Don't say what you believe to be false. b. Don't say that for which you lack adequate evidence. The maxim of relation: Say things that are relevant. The maxim of manner: Be perspicuous.. a. Avoid obscurity of expression. b. Avoid ambiguity. c. Be brief. d. Be orderly.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0}]},l={categories:[{id:"vb-root",titleZh:"词根词缀",noteZh:"看词根线索写单词，构词有法可循。"},{id:"vb-disc",titleZh:"近义辨析",noteZh:"近义词里选对的，先辨义再落笔。"},{id:"vb-colloc",titleZh:"固定搭配",noteZh:"补上那个合拍的词。"},{id:"vb-test",titleZh:"实战演练",noteZh:"四选一综合演练，练词汇手感。"}],items:[{id:"vb-root-01",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 spect",prompt:"根据词根写出单词：spect（看）→ 前景；展望（首字母 p，共 8 个字母）：p______",options:[],answer:"prospect",acceptedAnswers:[],explanationZh:"pro（向前）+ spect（看），向前看即“前景、展望”。",difficulty:2},{id:"vb-root-02",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 dict",prompt:"根据词根写出单词：dict（说话，断言，宣告）→ 预言；预报（首字母 p，共 7 个字母）：p______",options:[],answer:"predict",acceptedAnswers:[],explanationZh:"pre（预先）+ dict（说），预先说出即“预言”。",difficulty:1},{id:"vb-root-03",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 duc",prompt:"根据词根写出单词：duc（引导，带领）→ 教育；培养（首字母 e，共 7 个字母）：e______",options:[],answer:"educate",acceptedAnswers:[],explanationZh:"e-（向外）+ duc（引导），把潜能引导出来即“教育”。",difficulty:1},{id:"vb-root-04",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 port",prompt:"根据词根写出单词：port（搬运，携带）→ 出口；输出（首字母 e，共 6 个字母）：e______",options:[],answer:"export",acceptedAnswers:[],explanationZh:"ex（向外）+ port（搬运），搬出去即“出口”。",difficulty:1},{id:"vb-root-05",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 scrib",prompt:"根据词根写出单词：scrib（写）→ 描述；形容（首字母 d，共 8 个字母）：d______",options:[],answer:"describe",acceptedAnswers:[],explanationZh:"de（向下）+ scrib（写），写下来即“描述”。",difficulty:1},{id:"vb-root-06",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 audi",prompt:"根据词根写出单词：audi（听）→ 礼堂；会堂（首字母 a，共 10 个字母）：a______",options:[],answer:"auditorium",acceptedAnswers:[],explanationZh:"audi（听）+ -orium（场所），听演讲的场所即“礼堂”。",difficulty:3},{id:"vb-root-07",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 bio",prompt:"根据词根写出单词：bio（生命，生物）→ 生物学（首字母 b，共 7 个字母）：b______",options:[],answer:"biology",acceptedAnswers:[],explanationZh:"bio（生命）+ -logy（学科），研究生命的学科。",difficulty:1},{id:"vb-root-08",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 graph",prompt:"根据词根写出单词：graph（书写或记录符号）→ 段落（首字母 p，共 9 个字母）：p______",options:[],answer:"paragraph",acceptedAnswers:[],explanationZh:"para（旁边）+ graph（写），正文旁边另起的文字。",difficulty:2},{id:"vb-root-09",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 ann",prompt:"根据词根写出单词：ann（年）→ 每年的；一年一次的（首字母 a，共 6 个字母）：a______",options:[],answer:"annual",acceptedAnswers:[],explanationZh:"ann（年）+ -ual，每年的、一年一次的。",difficulty:2},{id:"vb-root-10",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 ceive",prompt:"根据词根写出单词：ceive（拿，抓住）→ 察觉；意识到（首字母 p，共 8 个字母）：p______",options:[],answer:"perceive",acceptedAnswers:[],explanationZh:"per（贯穿）+ ceive（拿），完全抓住信息即“察觉”。",difficulty:2},{id:"vb-root-11",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 cred",prompt:"根据词根写出单词：cred（相信）→ 信用；信任（首字母 c，共 6 个字母）：c______",options:[],answer:"credit",acceptedAnswers:[],explanationZh:"cred（相信）+ -it，可相信的依据即“信用”。",difficulty:1},{id:"vb-root-12",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 rupt",prompt:"根据词根写出单词：rupt（破裂）→ 打断；中断（首字母 i，共 9 个字母）：i______",options:[],answer:"interrupt",acceptedAnswers:[],explanationZh:"inter（在中间）+ rupt（破裂），从中间破开即“打断”。",difficulty:2},{id:"vb-root-13",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 ject",prompt:"根据词根写出单词：ject（投掷）→ 拒绝；排斥（首字母 r，共 6 个字母）：r______",options:[],answer:"reject",acceptedAnswers:[],explanationZh:"re（向后）+ ject（投掷），扔回去即“拒绝”。",difficulty:1},{id:"vb-root-14",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 vis",prompt:"根据词根写出单词：vis（看）→ 看得见的；可见的（首字母 v，共 7 个字母）：v______",options:[],answer:"visible",acceptedAnswers:[],explanationZh:"vis（看）+ -ible（可…的），看得见的。",difficulty:1},{id:"vb-root-15",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 form",prompt:"根据词根写出单词：form（形成，形状）→ 改变；改观（首字母 t，共 9 个字母）：t______",options:[],answer:"transform",acceptedAnswers:[],explanationZh:"trans（跨越）+ form（形状），改变形状即“改观”。",difficulty:2},{id:"vb-root-16",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 chron",prompt:"根据词根写出单词：chron（时间）→ 长期的；慢性的（首字母 c，共 7 个字母）：c______",options:[],answer:"chronic",acceptedAnswers:[],explanationZh:"chron（时间）+ -ic，时间久长即“慢性的”。",difficulty:3},{id:"vb-root-17",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 mit",prompt:"根据词根写出单词：mit（发送，放开）→ 传输；传送（首字母 t，共 8 个字母）：t______",options:[],answer:"transmit",acceptedAnswers:[],explanationZh:"trans（跨越）+ mit（发送），从一处发送到另一处。",difficulty:2},{id:"vb-root-18",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"词根 struct",prompt:"根据词根写出单词：struct（建造）→ 指导；教授（首字母 i，共 8 个字母）：i______",options:[],answer:"instruct",acceptedAnswers:[],explanationZh:"in（向内）+ struct（建造），在头脑中构建知识即“指导”。",difficulty:2},{id:"vb-root-19",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"前缀 tele",prompt:"根据前缀写出单词：tele（电的，远的）→ 望远镜（首字母 t，共 9 个字母）：t______",options:[],answer:"telescope",acceptedAnswers:[],explanationZh:"tele（远）+ scope，看远处事物的仪器。",difficulty:1},{id:"vb-root-20",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"前缀 anti",prompt:"根据前缀写出单词：anti（相反，反对）→ 抗生素；抗菌素（首字母 a，共 10 个字母）：a______",options:[],answer:"antibiotic",acceptedAnswers:[],explanationZh:"anti（反对）+ bio（生命）+ -tic，对抗细菌的药物。",difficulty:3},{id:"vb-root-21",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"前缀 auto",prompt:"根据前缀写出单词：auto（自己，自动的）→ 自动的（首字母 a，共 9 个字母）：a______",options:[],answer:"automatic",acceptedAnswers:[],explanationZh:"auto（自己）+ -matic，自己动作、无需人为的。",difficulty:1},{id:"vb-root-22",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"前缀 inter",prompt:"根据前缀写出单词：inter（在…之间）→ 国际的（首字母 i，共 13 个字母）：i______",options:[],answer:"international",acceptedAnswers:[],explanationZh:"inter（在…之间）+ national，国家之间的。",difficulty:1},{id:"vb-root-23",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"后缀 less",prompt:"根据后缀写出单词：-less（没有…的）→ 无价的；极贵重的（首字母 p，共 9 个字母）：p______",options:[],answer:"priceless",acceptedAnswers:[],explanationZh:"price（价格）+ -less（没有…的），无法定价即“无价的”。",difficulty:2},{id:"vb-root-24",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"后缀 ment",prompt:"根据后缀写出单词：-ment（动作或过程的结果）→ 环境（首字母 e，共 11 个字母）：e______",options:[],answer:"environment",acceptedAnswers:[],explanationZh:"environ（环绕）+ -ment，环绕四周的一切即“环境”。",difficulty:1},{id:"vb-root-25",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"后缀 able",prompt:"根据后缀写出单词：-able（可…的，能）→ 可靠的；可信赖的（首字母 r，共 8 个字母）：r______",options:[],answer:"reliable",acceptedAnswers:[],explanationZh:"rely（依靠）+ -able（可…的），可依靠的。",difficulty:1},{id:"vb-root-26",nodeId:"vb-root",categoryId:"vb-root",kind:"spelling",label:"后缀 ist",prompt:"根据后缀写出单词：-ist（从事…的人）→ 专家；专科医生（首字母 s，共 10 个字母）：s______",options:[],answer:"specialist",acceptedAnswers:[],explanationZh:"special（专门的）+ -ist（从事…的人），专攻某领域的人。",difficulty:1},{id:"vb-colloc-01",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 absorb",prompt:"填上合适的词：be absorbed ______（聚精会神于）",options:[],answer:"in",acceptedAnswers:[],explanationZh:"be absorbed in 聚精会神于，介词固定用 in。",difficulty:2},{id:"vb-colloc-02",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 abide",prompt:"填上合适的词：abide ______（忠于；遵守）",options:[],answer:"by",acceptedAnswers:[],explanationZh:"abide by 为固定搭配，表示遵守、忠于。",difficulty:3},{id:"vb-colloc-03",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 accuse",prompt:"填上合适的词：accuse sb. ______ sth.（指控，控告）",options:[],answer:"of",acceptedAnswers:[],explanationZh:"accuse sb. of sth. 指控某人犯某事。",difficulty:2},{id:"vb-colloc-04",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 accustom",prompt:"填上合适的词：be accustomed ______（习惯于）",options:[],answer:"to",acceptedAnswers:[],explanationZh:"be accustomed to 习惯于，to 是介词。",difficulty:2},{id:"vb-colloc-05",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 allow",prompt:"填上合适的词：allow ______（考虑到，估计到）",options:[],answer:"for",acceptedAnswers:[],explanationZh:"allow for 表示考虑到、估计到。",difficulty:3},{id:"vb-colloc-06",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 arise",prompt:"填上合适的词：arise ______（由…引起）",options:[],answer:"from",acceptedAnswers:[],explanationZh:"arise from 表示由…引起，主语是结果。",difficulty:2},{id:"vb-colloc-07",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 aware",prompt:"填上合适的词：be aware ______（意识到，知道）",options:[],answer:"of",acceptedAnswers:[],explanationZh:"be aware of 意识到、知道。",difficulty:1},{id:"vb-colloc-08",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 base",prompt:"填上合适的词：be based ______（基于）",options:[],answer:"on",acceptedAnswers:["upon"],explanationZh:"be based on/upon 基于，两种写法均可。",difficulty:1},{id:"vb-colloc-09",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 compensate",prompt:"填上合适的词：compensate ______（补偿，赔偿，弥补）",options:[],answer:"for",acceptedAnswers:[],explanationZh:"compensate for 补偿、弥补。",difficulty:2},{id:"vb-colloc-10",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 bear",prompt:"填上合适的词：bear ______ mind（记住）",options:[],answer:"in",acceptedAnswers:[],explanationZh:"bear in mind 记住，bear 义为“怀有”。",difficulty:2},{id:"vb-colloc-11",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 bring",prompt:"填上合适的词：bring ______ effect（实行；使生效）",options:[],answer:"into",acceptedAnswers:[],explanationZh:"bring into effect 实行、使生效。",difficulty:3},{id:"vb-colloc-12",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 cast",prompt:"填上合适的词：cast light ______（阐明，使了解）",options:[],answer:"on",acceptedAnswers:["upon"],explanationZh:"cast light on/upon 阐明、使了解。",difficulty:3},{id:"vb-colloc-13",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 catch",prompt:"填上合适的词：catch ______（着火，烧着）",options:[],answer:"fire",acceptedAnswers:[],explanationZh:"catch fire 着火，fire 前不加冠词。",difficulty:1},{id:"vb-colloc-14",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 come",prompt:"填上合适的词：come ______（实现）",options:[],answer:"true",acceptedAnswers:[],explanationZh:"come true 实现，true 作表语补足语。",difficulty:1},{id:"vb-colloc-15",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 give",prompt:"填上合适的词：give ______（让步，让路）",options:[],answer:"way",acceptedAnswers:[],explanationZh:"give way 让步、让路。",difficulty:2},{id:"vb-colloc-16",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 go",prompt:"填上合适的词：go ______（出错，出故障）",options:[],answer:"wrong",acceptedAnswers:[],explanationZh:"go wrong 出错、出故障。",difficulty:1},{id:"vb-colloc-17",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 keep",prompt:"填上合适的词：keep one's ______（守信用）",options:[],answer:"word",acceptedAnswers:[],explanationZh:"keep one's word 守信用，word 用单数。",difficulty:2},{id:"vb-colloc-18",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 learn",prompt:"填上合适的词：learn ______ heart（背诵，记住）",options:[],answer:"by",acceptedAnswers:[],explanationZh:"learn by heart 背诵、记住。",difficulty:1},{id:"vb-colloc-19",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 take",prompt:"填上合适的词：take … into ______（把……考虑进去）",options:[],answer:"account",acceptedAnswers:[],explanationZh:"take sth. into account 把……考虑进去。",difficulty:2},{id:"vb-colloc-20",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 fond",prompt:"填上合适的词：be fond ______（喜欢）",options:[],answer:"of",acceptedAnswers:[],explanationZh:"be fond of 喜欢。",difficulty:1},{id:"vb-colloc-21",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 keen",prompt:"填上合适的词：be keen ______（爱好，很喜欢）",options:[],answer:"on",acceptedAnswers:[],explanationZh:"be keen on 爱好、很喜欢。",difficulty:1},{id:"vb-colloc-22",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 loyal",prompt:"填上合适的词：be loyal ______（忠于）",options:[],answer:"to",acceptedAnswers:[],explanationZh:"be loyal to 忠于。",difficulty:1},{id:"vb-colloc-23",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 patient",prompt:"填上合适的词：be patient ______（有耐心）",options:[],answer:"with",acceptedAnswers:[],explanationZh:"be patient with 对…有耐心。",difficulty:1},{id:"vb-colloc-24",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 prior",prompt:"填上合适的词：be prior ______（在…之前）",options:[],answer:"to",acceptedAnswers:[],explanationZh:"prior to 在…之前，相当于 before。",difficulty:3},{id:"vb-colloc-25",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 typical",prompt:"填上合适的词：be typical ______（是典型的，特有的）",options:[],answer:"of",acceptedAnswers:[],explanationZh:"be typical of 是典型的、特有的。",difficulty:2},{id:"vb-colloc-26",nodeId:"vb-colloc",categoryId:"vb-colloc",kind:"short-answer",label:"搭配 curious",prompt:"填上合适的词：be curious ______（好奇，想知道）",options:[],answer:"about",acceptedAnswers:[],explanationZh:"be curious about 对…好奇。",difficulty:1},{id:"vb-disc-01",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"I will ______ by the director's decision.",options:["abide","adhere","conform","comply"],answer:"abide",acceptedAnswers:[],explanationZh:"abide 接 by，adhere、conform 接 to，comply 接 with；介词搭配是区分关键。",difficulty:3},{id:"vb-disc-02",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「概要，摘要，尤其指对学术论文或法律论据作的简述」？",options:["digest","abstract","outline","summary"],answer:"abstract",acceptedAnswers:[],explanationZh:"abstract 特指学术论文或法律论据的简述；summary 用寥寥数语概括要点。",difficulty:3},{id:"vb-disc-03",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"The meeting has been ______ because of the flu.",options:["abolish","cancel","eliminate","erase"],answer:"cancel",acceptedAnswers:[],explanationZh:"cancel 取消预先安排的活动；abolish 废除制度法律，eliminate 淘汰，erase 擦除。",difficulty:2},{id:"vb-disc-04",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「剧烈的，严重的；急性的（病）」？",options:["critical","crucial","acute","urgent"],answer:"acute",acceptedAnswers:[],explanationZh:"acute 指剧烈的、严重的或急性的病；urgent 只强调时间上的紧急。",difficulty:3},{id:"vb-disc-05",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"This hotel can ______ up to 500 guests.",options:["afford","furnish","accommodate","reserve"],answer:"accommodate",acceptedAnswers:[],explanationZh:"accommodate 提供住宿；afford 多指提供抽象事物，furnish 提供生活所需之物。",difficulty:2},{id:"vb-disc-06",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「供认（罪行、过错等），含有坦白、招认的意思」？",options:["admit","concede","deny","confess"],answer:"confess",acceptedAnswers:[],explanationZh:"confess 供认罪行过错；admit 指经说服追问后承认，deny 意为否认。",difficulty:2},{id:"vb-disc-07",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"It is through learning that the individual ______ many habitual ways of reacting to situations.",options:["acquire","obtain","attain","gain"],answer:"acquire",acceptedAnswers:[],explanationZh:"acquire 强调经学习逐步获得并长期持有；obtain 用于正式语体，attain 多指达到目标。",difficulty:3},{id:"vb-disc-08",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「愤恨，怨恨，不满，是正式用语，尤指由于受侮辱或自尊心受到伤害后而产生的愤慨」？",options:["indignation","resentment","anger","fury"],answer:"resentment",acceptedAnswers:[],explanationZh:"resentment 指受辱或自尊受伤后的愤恨；indignation 是出于道义的义愤。",difficulty:3},{id:"vb-disc-09",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"He ______ the mistake in the contract by changing its wording.",options:["amend","alter","rectify","modify"],answer:"rectify",acceptedAnswers:[],explanationZh:"rectify 纠正错误；amend 修改法律文件，alter、modify 泛指改动事物。",difficulty:2},{id:"vb-disc-10",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「明白的，明显的，多用于推理或由事实证明的事物」？",options:["obvious","manifest","evident","apparent"],answer:"evident",acceptedAnswers:[],explanationZh:"evident 强调由推理或事实证明；obvious 指无可辩白、不需证明。",difficulty:3},{id:"vb-disc-11",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"I ______ a note to my report with a paper clip.",options:["attach","append","link","affiliate"],answer:"attach",acceptedAnswers:[],explanationZh:"attach 把一物系、贴、附在另一物上；append 特指在文字后附加。",difficulty:2},{id:"vb-disc-12",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「正式用词，用于对具体功绩或成就表示嘉奖，通常指上级对下级、长辈对晚辈的赞赏」？",options:["praise","applaud","commend","clap"],answer:"commend",acceptedAnswers:[],explanationZh:"commend 是正式用语，多指上级对下级的嘉奖；praise 是普通用词。",difficulty:3},{id:"vb-disc-13",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"He is the only person who can ______ in this case, because the other witnesses were killed mysteriously.",options:["certify","testify","verify","rectify"],answer:"testify",acceptedAnswers:[],explanationZh:"testify 指在法庭上宣誓作证；certify 证明，verify 用事实核实，rectify 纠正。",difficulty:2},{id:"vb-disc-14",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「周围地区，附近地区」？",options:["area","district","region","vicinity"],answer:"vicinity",acceptedAnswers:[],explanationZh:"vicinity 指附近地区；area 泛指大地区，region 是行政区划上的大地区。",difficulty:2},{id:"vb-disc-15",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"I hurt my foot, then ______ it by trying to walk too soon.",options:["strengthen","intensify","reinforce","aggravate"],answer:"aggravate",acceptedAnswers:[],explanationZh:"aggravate 加重病情、负担使恶化；intensify 使程度更强烈（色彩、仇恨等）。",difficulty:3},{id:"vb-disc-16",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「根本性的，一般只用于抽象的事物」？",options:["basic","fundamental","elementary","essential"],answer:"fundamental",acceptedAnswers:[],explanationZh:"fundamental 根本性的、只用于抽象事物；essential 侧重核心、必不可少。",difficulty:3},{id:"vb-disc-17",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"We watched the ______ broadcast of the opera on TV.",options:["alive","lively","live","living"],answer:"live",acceptedAnswers:[],explanationZh:"live 现场直播的；alive 多作表语，living 活着的，lively 活泼的。",difficulty:1},{id:"vb-disc-18",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「（书面语）吃吃的笑，抿嘴笑，轻声笑，多指因得意或领会到某事中的趣味而暗自发笑」？",options:["giggle","grin","sneer","chuckle"],answer:"chuckle",acceptedAnswers:[],explanationZh:"chuckle 抿嘴轻声笑；giggle 咯咯地笑，grin 露齿而笑，sneer 冷笑。",difficulty:3},{id:"vb-disc-19",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"He ______ our invitation to dinner.",options:["decline","decrease","diminish","reduce"],answer:"decline",acceptedAnswers:[],explanationZh:"decline 婉言谢绝邀请；decrease、diminish、reduce 都指数量程度的减少。",difficulty:2},{id:"vb-disc-20",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「三言两语的，简短的，常含有草率的意思」？",options:["concise","curt","brief","succinct"],answer:"curt",acceptedAnswers:[],explanationZh:"curt 简短却含草率无礼之意；concise、succinct 侧重简练精要。",difficulty:4},{id:"vb-disc-21",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"We ______ the salad forks from the dinner forks.",options:["divide","detach","separate","allocate"],answer:"separate",acceptedAnswers:[],explanationZh:"separate 把相连或靠近的东西分隔开；divide 指把整体分成若干部分。",difficulty:2},{id:"vb-disc-22",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「力劝，强迫，与 compel 意思相近，但更多强调内心情感（如道德、怜悯等）的强迫和限制作用，一般用于正式的场合」？",options:["compel","oblige","constrain","force"],answer:"constrain",acceptedAnswers:[],explanationZh:"constrain 强调内心情感、道德上的约束；force 侧重暴力威胁。",difficulty:4},{id:"vb-disc-23",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"He has some ______ ideas about what to do, but nothing specific.",options:["ambiguous","vague","obscure","unclear"],answer:"vague",acceptedAnswers:[],explanationZh:"vague 指言辞笼统、轮廓模糊；ambiguous 指字句有歧义，obscure 多指深奥难懂。",difficulty:4},{id:"vb-disc-24",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「保留，储备（强调为某一特殊目的）；订（座位），预订」？",options:["conserve","preserve","reserve","secure"],answer:"reserve",acceptedAnswers:[],explanationZh:"reserve 为特定目的保留或预订；conserve 强调节约，preserve 强调保护。",difficulty:2},{id:"vb-disc-25",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"The pullover ______ after I had worn it a few times.",options:["stretch","expand","enlarge","magnify"],answer:"stretch",acceptedAnswers:[],explanationZh:"stretch 指有弹性地伸展、撑大；expand 指范围、体积的扩大。",difficulty:2},{id:"vb-disc-26",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「不断的，经常的，强调始终如一地经常出现」？",options:["continual","continuous","incessant","constant"],answer:"constant",acceptedAnswers:[],explanationZh:"constant 强调始终如一、经常出现；continuous 强调中间不停顿。",difficulty:3},{id:"vb-disc-27",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"The girl ______ sugar, butter, and flour to make the dough.",options:["unite","combine","associate","ally"],answer:"combine",acceptedAnswers:[],explanationZh:"combine 把不同的人或物混合成一个整体；unite 强调结果的一致性。",difficulty:2},{id:"vb-disc-28",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「抛弃，不采纳，主语可以是人或物，后接名词，不能接动词不定式」？",options:["reject","refuse","decline","deny"],answer:"reject",acceptedAnswers:[],explanationZh:"reject 后接名词表示不采纳；decline 是婉言谢绝，refuse 语气坚决。",difficulty:3},{id:"vb-disc-29",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"In ______, the economy is doing well now.",options:["common","usual","average","general"],answer:"general",acceptedAnswers:[],explanationZh:"in general 是固定搭配，强调整体性；common 强调常见，usual 指惯常。",difficulty:1},{id:"vb-disc-30",nodeId:"vb-disc",categoryId:"vb-disc",kind:"multiple-choice",prompt:"下面哪个词意为「人体感官受到外部刺激时产生的感觉，知觉」？",options:["emotion","sensation","feeling","passion"],answer:"sensation",acceptedAnswers:[],explanationZh:"sensation 指感官受刺激产生的知觉；emotion 指喜怒哀乐等激动的情绪。",difficulty:2},{id:"vb-test-001",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The ______ conclusion by scientists until recently had been that rising air temperatures were causing the Antarctic Peninsula to melt.",options:["prevailing","prevalent","persuasive","popular"],answer:"prevailing",acceptedAnswers:[],explanationZh:"prevailing 指「占主导地位的、通行的」，常修饰观点、结论等，表示当前被普遍接受的主流看法；prevalent 也表「普遍」，但侧重现象在某一范围广泛存在，不强调主流地位。",difficulty:3},{id:"vb-test-002",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Ecologists have been analyzing more than 500,000 plant ______ and finding 11,676 different tree types in the rainforest.",options:["samples","collections","examples","selections"],answer:"samples",acceptedAnswers:[],explanationZh:"samples 指供研究、分析用的「样本」，plant samples 即植物样本；collections 是收藏品，selections 指挑选出的精选物，都不适用于科研采样语境。",difficulty:2},{id:"vb-test-003",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Unable to continue at her job and to pay rent, Vicky and her family were ______ from their home.",options:["evicted","revoked","evacuated","rejected"],answer:"evicted",acceptedAnswers:[],explanationZh:"evicted 意为「（依法）驱逐、赶出」，be evicted from their home 指被逐出住所；evacuated 是「疏散、撤离」，主语通常是人而非被逐的对象；revoked 是「撤销」，rejected 是「拒绝」。",difficulty:3},{id:"vb-test-004",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The archaeological dig is almost without ______ the most revelatory of its kind, and it has begun to transform our knowledge of life in the Bronze Age.",options:["predecessor","premise","precedent","preference"],answer:"precedent",acceptedAnswers:[],explanationZh:"without precedent 是固定搭配，意为「史无前例的」；predecessor 指前任（人或事物），premise 指前提，preference 指偏好，都不能与 without 构成此义。",difficulty:2},{id:"vb-test-005",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Both official and unofficial records indicate that the war ______ over 6 million people, resulting in the creation of the largest refugee population worldwide today.",options:["misplaced","displaced","replaced","placed"],answer:"displaced",acceptedAnswers:[],explanationZh:"displaced 意为「使流离失所、使背井离乡」，与后文 largest refugee population 呼应；misplaced 是「放错地方」，replaced 是「取代」，placed 是「放置」。",difficulty:2},{id:"vb-test-006",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Few are spared from suffering in The Kite Runner, and the author ______ from offering a simplistic happy ending.",options:["strains","restrains","constrains","refrains"],answer:"refrains",acceptedAnswers:[],explanationZh:"refrain from doing sth. 是固定搭配，意为「克制不做某事」，指作者自身忍住不写简单化的大团圆结局；restrain 和 constrain 都是及物动词，需带宾语（restrain sb. from）。",difficulty:3},{id:"vb-test-007",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Through the story of two boys, this haunting and ______ tale demonstrates the importance of preserving our humanity at all costs.",options:["expelling","dispelling","impelling","compelling"],answer:"compelling",acceptedAnswers:[],explanationZh:"compelling 意为「引人入胜的、扣人心弦的」，与 haunting（萦绕心头的）并列修饰 tale；expelling 是「驱逐」，dispelling 是「驱散」，impelling 是「推动」，均不合语境。",difficulty:2},{id:"vb-test-008",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The editor of Merriam-Webster pointed out that there are many reasons to look up a word in the dictionary ______ than learning its meaning.",options:["rather","other","more","different"],answer:"other",acceptedAnswers:[],explanationZh:"other than 意为「除了」，句意是查词典除弄清词义之外还有很多理由；rather than 是「而不是」，more than 是「多于」，different than 用于比较差异，均不合句意。",difficulty:2},{id:"vb-test-009",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Ten soldiers were ambushed and ______ injured after the gunmen attacked the camp late at night.",options:["vehemently","periodically","enormously","critically"],answer:"critically",acceptedAnswers:[],explanationZh:"critically 意为「严重地、危急地」，critically injured 指伤势危重；vehemently 是「激烈地」（多修饰言辞），periodically 是「定期地」，enormously 是「巨大地」，均不能修饰受伤程度。",difficulty:2},{id:"vb-test-010",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Although Gutenberg developed his printing press with a limited use in mind, the cultural effects of mass printing have been ______.",options:["escalating","grave","profound","in-depth"],answer:"profound",acceptedAnswers:[],explanationZh:"profound 意为「深远的、深刻的」，修饰影响时指影响深远；grave 虽也表「严重」，但多指局势、后果的严重；escalating 是「不断升级的」，in-depth 是「深入的」（多修饰研究等）。",difficulty:3},{id:"vb-test-011",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Ann hurried back, having a guilty ______ at leaving her daughter at home alone.",options:["conscience","congestion","conservation","consciousness"],answer:"conscience",acceptedAnswers:[],explanationZh:"guilty conscience 是固定搭配，意为「内疚、负罪感」；consciousness 指「意识、知觉」（如 lose consciousness），congestion 是「拥堵」，conservation 是「保护」。",difficulty:2},{id:"vb-test-012",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Your earnings will be in ______ to the amount of work you do.",options:["addition","percentage","relationship","proportion"],answer:"proportion",acceptedAnswers:[],explanationZh:"in proportion to 意为「与……成比例」，符合「收入与工作量成正比」的句意；in addition to 是「除……之外」，in relationship to 是「与……的关系」，in percentage to 不是固定搭配。",difficulty:2},{id:"vb-test-013",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"This drink is very tasty, and it is nutritious as well, as it is ______ with vitamin C.",options:["enriched","strengthened","increased","consolidated"],answer:"enriched",acceptedAnswers:[],explanationZh:"enriched with 意为「富含、添加了（营养成分）」，be enriched with vitamin C 即富含维生素 C；strengthened 是「加强」，increased 是「增加（数量）」，consolidated 是「巩固」。",difficulty:2},{id:"vb-test-014",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The discovery of the New World is a ______ in the world history.",options:["landmark","standard","recognition","triumph"],answer:"landmark",acceptedAnswers:[],explanationZh:"landmark 意为「里程碑、标志性事件」，发现新大陆是世界史上的里程碑；standard 是「标准」，recognition 是「认可」，triumph 是「胜利」。",difficulty:1},{id:"vb-test-015",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"It is ______ to keep a note of these important data, so we won't lose them.",options:["sensitive","sensational","sensible","senseless"],answer:"sensible",acceptedAnswers:[],explanationZh:"sensible 意为「明智的、合情理的」，记下重要数据以免丢失是明智之举；sensitive 是「敏感的」，sensational 是「耸人听闻的」，senseless 是「无意义的」，均不合句意。",difficulty:2},{id:"vb-test-016",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"I don't think that was a mistake; I think it was ______ made so.",options:["methodically","accidentally","carelessly","deliberately"],answer:"deliberately",acceptedAnswers:[],explanationZh:"deliberately 意为「故意地」，与上文 not a mistake 相对：那不是失误，而是故意为之；accidentally 是「偶然地」，carelessly 是「粗心地」，methodically 是「有条不紊地」。",difficulty:2},{id:"vb-test-017",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"You need to contact your doctor if the symptoms ______ for a day.",options:["perceive","persist","perform","perplex"],answer:"persist",acceptedAnswers:[],explanationZh:"persist 意为「持续」，症状持续一天，符合句意；perceive 是「察觉」，perform 是「表现、执行」，perplex 是「使困惑」，均为形近干扰。",difficulty:1},{id:"vb-test-018",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"There is a strong ______ between the father and the son.",options:["illustration","reflection","resemblance","correspondence"],answer:"resemblance",acceptedAnswers:[],explanationZh:"resemblance 意为「相似、相像」，There is a strong resemblance between... and... 是固定句式，指父子长得很像；correspondence 是「通信、一致」，reflection 是「映照、反思」，illustration 是「插图、说明」。",difficulty:2},{id:"vb-test-019",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The smartphone manufacturer blamed ______ batteries for last year's humiliating recall of its flagship smartphone.",options:["wrong","faulty","mistaken","incorrect"],answer:"faulty",acceptedAnswers:[],explanationZh:"faulty 意为「有缺陷的、出故障的」，修饰产品（电池）最地道；wrong 指「错误的」（答案、方向等），mistaken 指人「弄错的」，incorrect 多指信息「不正确的」。",difficulty:2},{id:"vb-test-020",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"While he says his next job won't be as a head coach for the current team, he's ______ several possibilities, including working overseas.",options:["recollecting","enjoying","reconciling","entertaining"],answer:"entertaining",acceptedAnswers:[],explanationZh:"entertain 除「款待」外还有「考虑（想法、可能性）」之义，entertain possibilities 即权衡各种可能性；recollecting 是「回忆」，reconciling 是「调和」，enjoying 是「享受」。",difficulty:3},{id:"vb-test-021",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"He tricked the kid ______ trusting him by pretending that he had super power.",options:["from","into","to","of"],answer:"into",acceptedAnswers:[],explanationZh:"trick sb. into doing sth. 是固定搭配，意为「诱骗某人做某事」；其他介词均不与 trick 构成这一结构。",difficulty:1},{id:"vb-test-022",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Everyone in the company agrees that their boss is a very resourceful and ______ man.",options:["self-centered","self-employed","self-willed","self-assured"],answer:"self-assured",acceptedAnswers:[],explanationZh:"self-assured 意为「自信的」，与 resourceful（足智多谋的）并列称赞老板；self-centered 是「以自我为中心的」，self-employed 是「个体经营的」，self-willed 是「任性的」。",difficulty:2},{id:"vb-test-023",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"In ______ of the strong earthquake last week, many families are deep in mourning.",options:["outcome","effect","consequence","result"],answer:"consequence",acceptedAnswers:[],explanationZh:"in consequence of 是固定搭配，意为「由于」，与 as a result of 同义；in effect 是「实际上」，outcome 不与 in...of 连用，result 的正确搭配是 as a result of。",difficulty:3},{id:"vb-test-024",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The factory is looking for better ways to ______ operations so as to improve productivity.",options:["stretch","strike","strain","streamline"],answer:"streamline",acceptedAnswers:[],explanationZh:"streamline 意为「精简、使（流程）更高效」，streamline operations 即优化运营流程；stretch 是「拉伸」，strike 是「打击、罢工」，strain 是「拉伤、使紧张」。",difficulty:2},{id:"vb-test-025",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The unique wall paintings in the old town are once again under the media ______.",options:["spotlight","standpoint","superiority","symmetry"],answer:"spotlight",acceptedAnswers:[],explanationZh:"spotlight 本义「聚光灯」，under the media spotlight 指成为媒体关注的焦点；standpoint 是「立场」，superiority 是「优越性」，symmetry 是「对称」。",difficulty:2},{id:"vb-test-026",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Please excuse me. I must ______ to some urgent business now.",options:["attach","attribute","attract","attend"],answer:"attend",acceptedAnswers:[],explanationZh:"attend to 意为「处理、料理」，attend to some urgent business 即处理急事；attach to 是「附上」，attribute to 是「归因于」，attract 是「吸引」。",difficulty:1},{id:"vb-test-027",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Not sophisticated at all, Tim is easy to lose his ______, which may hurt people around him sometimes.",options:["disposition","personality","temper","potential"],answer:"temper",acceptedAnswers:[],explanationZh:"lose one's temper 是固定搭配，意为「发脾气」，与后文 hurt people around him 呼应；disposition 是「性情」，personality 是「个性」，potential 是「潜力」。",difficulty:1},{id:"vb-test-028",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"She often let the children play in the yard to keep them out of ______.",options:["mischief","disobedience","misfortune","disgrace"],answer:"mischief",acceptedAnswers:[],explanationZh:"mischief 意为「恶作剧、捣蛋」，keep them out of mischief 指让孩子在院里玩以免淘气闯祸；disobedience 是「不服从」，misfortune 是「不幸」，disgrace 是「耻辱」。",difficulty:2},{id:"vb-test-029",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The overall economic ______ for the newly emerging economy is very promising.",options:["outbreak","outlook","outset","outrage"],answer:"outlook",acceptedAnswers:[],explanationZh:"outlook 意为「前景、展望」，economic outlook 即经济前景；outbreak 是「爆发」，outset 是「开端」（at the outset），outrage 是「愤怒」。",difficulty:2},{id:"vb-test-030",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"They normally ______ one of their three arguments when criticizing their opponents.",options:["fall back on","fall out with","fall behind","fall into"],answer:"fall back on",acceptedAnswers:[],explanationZh:"fall back on 意为「转而依靠、退而求助于」，批评对手时总要搬出三大论据之一；fall out with 是「与……争吵」，fall behind 是「落后」，fall into 是「落入、分成」。",difficulty:3},{id:"vb-test-031",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"For whatever ______, I know everyone would have been incredibly proud of you tonight.",options:["worthy","worth","it's worth","it's worthy"],answer:"it's worth",acceptedAnswers:[],explanationZh:"for whatever it's worth 是固定习语，意为「不管怎样、姑且这么说」；worthy 表「值得的」需接 of，worth 前不能直接加 whatever 构成这一结构。",difficulty:3},{id:"vb-test-032",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"We are so delighted to have you here; it is not often we are consulted by men of science, especially one of your ______.",options:["prominence","deference","imminence","homage"],answer:"prominence",acceptedAnswers:[],explanationZh:"prominence 意为「声望、显赫」，one of your prominence 指像您这样有声望的人；deference 是「尊重、听从」，imminence 是「临近」，homage 是「敬意」。",difficulty:3},{id:"vb-test-033",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"It is recently found that two colleagues who are ______ basketball fans or share a fascination with rare books are more likely to swap information on work.",options:["adamant","avid","formidable","vehement"],answer:"avid",acceptedAnswers:[],explanationZh:"avid 意为「热衷的、狂热的」，avid basketball fans 即铁杆球迷；adamant 是「坚决的」（多指态度），formidable 是「令人生畏的」，vehement 是「激烈的」（多指言辞）。",difficulty:3},{id:"vb-test-034",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"As her mind reeled back in time, she wondered what she could possibly have done ______.",options:["distinguishingly","distinctly","differently","differentially"],answer:"differently",acceptedAnswers:[],explanationZh:"differently 意为「以不同方式地」，wondered what she could have done differently 指后悔当初没换种做法；distinctly 是「清楚地」，differentially 是「有区别地」，distinguishingly 很少单独作副词使用。",difficulty:2},{id:"vb-test-035",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"When transmission speed is prioritized, instant messaging can beat both e-mail and telephone in ______.",options:["sufficiency","efficiency","deficiency","efficaciousness"],answer:"efficiency",acceptedAnswers:[],explanationZh:"in efficiency 指「在效率方面」，即时通讯在传输速度优先时胜过电邮和电话；sufficiency 是「充足」，deficiency 是「不足、缺陷」，efficaciousness 是「有效性」（多指药物疗效）。",difficulty:2},{id:"vb-test-036",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The university has a policy of hiring men and women of a variety of ages and cultures because diversity of experience and perspective gives it a competitive ______.",options:["brink","rim","blade","edge"],answer:"edge",acceptedAnswers:[],explanationZh:"competitive edge 是固定搭配，意为「竞争优势」；brink 是「边缘」（on the brink of），rim 指圆形物体的边缘，blade 是「刀刃」。",difficulty:2},{id:"vb-test-037",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"______ the travel and business sections of any decent bookstore, and you're likely to find many volumes detailing kaleidoscopic cultures around the world.",options:["Wander","Graze","Browse","Surf"],answer:"Browse",acceptedAnswers:[],explanationZh:"browse 意为「随意翻阅、浏览」，逛书店翻看某类书架用 browse；wander 是「漫步、闲逛」（后接地点），graze 是「吃草、擦过」，surf 用于「上网冲浪」。",difficulty:2},{id:"vb-test-038",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Turning a blind eye to intracultural variations can lead to ______ people from different backgrounds.",options:["appraising","categorizing","ascertaining","stereotyping"],answer:"stereotyping",acceptedAnswers:[],explanationZh:"stereotype 意为「对……形成刻板印象」，无视文化内部差异会导致对不同背景的人产生刻板印象；appraising 是「评估」，categorizing 是「分类」，ascertaining 是「查明」。",difficulty:2},{id:"vb-test-039",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"In North America, first names are seen as friendly and ______ of fondness and attachment.",options:["inductive","indicative","deductive","evocative"],answer:"indicative",acceptedAnswers:[],explanationZh:"be indicative of 意为「表明、显示」，名字被视作友好，并体现喜爱与依恋；inductive 是「归纳的」，deductive 是「演绎的」，evocative 是「唤起回忆的」。",difficulty:3},{id:"vb-test-040",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"There is growing recognition that businesses that operate in a globalizing economy need a universal ______ of business ethics.",options:["code","law","rule","principle"],answer:"code",acceptedAnswers:[],explanationZh:"code 在此指「准则、规范」，a code of business ethics 即商业道德准则；law 是「法律」，rule 是「规则」，principle 是「原则」，均不如 code 与 ethics 搭配自然。",difficulty:2},{id:"vb-test-041",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"His greatest ______ is his utterly natural and profoundly good musical instinct.",options:["capacity","competence","gift","aptitude"],answer:"gift",acceptedAnswers:[],explanationZh:"gift 意为「天赋」，与后文 musical instinct（音乐直觉）呼应，greatest gift 即最大的天赋；capacity 是「能力、容量」，competence 是「胜任」，aptitude 指学习某技能的天资。",difficulty:2},{id:"vb-test-042",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"My aunt tried her best to ______ the situation, but the damage was already done.",options:["adjust","regulate","rectify","amend"],answer:"rectify",acceptedAnswers:[],explanationZh:"rectify 意为「纠正、矫正」，rectify the situation 指挽回局面、纠正状况；adjust 是「调节」（小的调整），regulate 是「调控」（按规则管理），amend 是「修订」（文件、法律等）。",difficulty:3},{id:"vb-test-043",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Michael is holding a ______ position in the company and expects to be promoted soon.",options:["minor","inferior","secondary","subordinate"],answer:"subordinate",acceptedAnswers:[],explanationZh:"subordinate 意为「下级的、从属的」，subordinate position 即下级职位，与后文 expects to be promoted 呼应；inferior 也表「下级」但含「低劣」贬义，minor 和 secondary 表「次要的」。",difficulty:2},{id:"vb-test-044",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"I wish you break a leg in the coming English speech contest. The underlined part means ______.",options:["get injured","play well","good luck","have fun"],answer:"good luck",acceptedAnswers:[],explanationZh:"break a leg 是习语，意为「祝好运」，常用于演出、比赛前的祝福，不能按字面理解为「受伤」。",difficulty:1},{id:"vb-test-045",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"I have the car now but my sister was the ______ owner.",options:["initial","original","primitive","primary"],answer:"original",acceptedAnswers:[],explanationZh:"original 意为「最初的、原来的」，original owner 即原车主（此前没有更早的主人）；initial 强调「起始阶段的」（如 initial stage），primitive 是「原始的」，primary 是「首要的」。",difficulty:2},{id:"vb-test-046",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The principal stressed using multimedia teaching would never replace the one-to-one ______ between pupil and teacher.",options:["perceptions","consultations","interactions","interruptions"],answer:"interactions",acceptedAnswers:[],explanationZh:"interaction 意为「互动、交流」，one-to-one interactions 指师生一对一的互动；perceptions 是「感知」，consultations 是「咨询」，interruptions 是「打断」。",difficulty:1},{id:"vb-test-047",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"They've made a great ______ forward with their road building in the last few years.",options:["bounce","bound","hop","leap"],answer:"leap",acceptedAnswers:[],explanationZh:"make a great leap forward 是常用搭配，意为「向前迈进一大步」；bound 指「跳跃」（如 by leaps and bounds），hop 是「单脚跳」，bounce 是「弹跳」。",difficulty:2},{id:"vb-test-048",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Your books and magazines are almost in a ______; go and put them in order.",options:["chaos","disorder","mess","riot"],answer:"mess",acceptedAnswers:[],explanationZh:"in a mess 是固定搭配，意为「一团糟、凌乱不堪」，与后文 put them in order 呼应；chaos 前不用冠词 a（in chaos），disorder 用 in disorder，riot 是「骚乱」。",difficulty:2},{id:"vb-test-049",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The animal protection group is calling on people to ______ fur coats and care for wild animals.",options:["ban","forbid","veto","boycott"],answer:"boycott",acceptedAnswers:[],explanationZh:"boycott 意为「抵制、拒绝购买」，动物保护组织号召公众抵制皮草；ban 是官方从法律层面「禁止」，forbid 是个人命令式「禁止」，veto 是「否决」。",difficulty:3},{id:"vb-test-050",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"No one could ever ______ this government of not caring about the poor.",options:["accuse","charge","condemn","prosecute"],answer:"accuse",acceptedAnswers:[],explanationZh:"accuse 与 of 连用表「指责」；charge 接 with，condemn、prosecute 接 for。",difficulty:3},{id:"vb-test-051",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Yu Dan and Lecture Room program gain popularity in modern China, which is ______ of a new attitude towards Sinology.",options:["informative","indicative","initiative","instructive"],answer:"indicative",acceptedAnswers:[],explanationZh:"be indicative of 意为「表明、暗示」，正合题意；initiative 为名词，其余两项语义不符。",difficulty:3},{id:"vb-test-052",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The program includes an ______ of program options for ESL/EFL teachers.",options:["array","arrangement","agreement","assortment"],answer:"array",acceptedAnswers:[],explanationZh:"an array of 意为「一大批、一系列」，与 options 搭配自然；assortment 侧重花色品种混杂。",difficulty:3},{id:"vb-test-053",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The volcano ______ on Friday, opening up an 800-meter-long crack in its crater.",options:["ejected","erupted","spewed","ignited"],answer:"erupted",acceptedAnswers:[],explanationZh:"erupt 专指火山「爆发」；eject 意为「弹出、驱逐」，spew 意为「喷涌」，ignite 意为「点燃」。",difficulty:2},{id:"vb-test-054",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"As previously suspected, the inhabitants of the region had been hunter-gatherers living relatively ______ lifestyles.",options:["separated","remote","lonely","solitary"],answer:"solitary",acceptedAnswers:[],explanationZh:"solitary 意为「独自的、独居的」，修饰生活方式；lonely 侧重内心寂寞，remote 指地点偏僻。",difficulty:3},{id:"vb-test-055",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The country is making progress on its bailout reform commitments but bad bank loans could ______ a fledgling recovery.",options:["divert","deconstruct","distract","derail"],answer:"derail",acceptedAnswers:[],explanationZh:"derail 原指火车脱轨，引申为「使……受阻」；divert、distract 意为「转移、分散」。",difficulty:4},{id:"vb-test-056",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The parents almost collapsed upon learning that their child had been diagnosed ______ a rare disease.",options:["for","as","with","over"],answer:"with",acceptedAnswers:[],explanationZh:"be diagnosed with 为固定搭配，表示「被诊断患有……」，介词用 with。",difficulty:2},{id:"vb-test-057",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Major airlines have banned the transport of hunting trophies from Africa in the ______ of the outrage over the shooting death of a lion in Zimbabwe.",options:["call","wake","result","midst"],answer:"wake",acceptedAnswers:[],explanationZh:"in the wake of 表「随着……之后」；in the midst of 意为「正当……之中」，不合题意。",difficulty:3},{id:"vb-test-058",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The ______ cited study suggested that parental involvement in homework can boost a student's academic performance.",options:["widely","likely","popularly","eventually"],answer:"widely",acceptedAnswers:[],explanationZh:"widely cited 意为「被广泛引用的」，副词 widely 修饰 cited 表程度；其余三项语义不符。",difficulty:2},{id:"vb-test-059",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Salespeople here are paid on a commission basis; however, continued employment is based on their ability to sell service contracts rather than ______.",options:["commodity","product","produce","merchandise"],answer:"merchandise",acceptedAnswers:[],explanationZh:"merchandise 是商品总称，与「服务合同」相对；commodity 多指大宗商品，produce 指农产品。",difficulty:3},{id:"vb-test-060",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Anthropologists were intrigued to learn that Kennewick Man was ______ different from today's native Americans.",options:["anonymously","autonomously","anatomically","analogously"],answer:"anatomically",acceptedAnswers:[],explanationZh:"anatomically 意为「解剖学上」，符合人类学家的研究语境；其余三项为「匿名地、自主地、类比地」。",difficulty:4},{id:"vb-test-061",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"We work to make money, but it's a ______ that people who work hard and long often do not make the most money.",options:["dilemma","struggle","collision","paradox"],answer:"paradox",acceptedAnswers:[],explanationZh:"paradox 意为「悖论」，指看似矛盾却真实存在的现象；dilemma 强调进退两难的选择。",difficulty:3},{id:"vb-test-062",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Jane was determined to ______ herself in the African way of life.",options:["immerse","dip","duck","submerge"],answer:"immerse",acceptedAnswers:[],explanationZh:"immerse oneself in 为固定搭配，意为「沉浸于、全身心投入」，此处指融入当地生活方式。",difficulty:2},{id:"vb-test-063",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"We ______ any attempts to infiltrate company networks to obtain user information.",options:["sentence","condemn","reproach","scold"],answer:"condemn",acceptedAnswers:[],explanationZh:"condemn 意为「谴责」，可接行为作宾语；reproach、scold 多责备人。",difficulty:3},{id:"vb-test-064",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"You have to blow your own ______ sometimes-- no one else will do it for you.",options:["trumpet","whistle","bugle","flute"],answer:"trumpet",acceptedAnswers:[],explanationZh:"blow one's own trumpet 为习语，意为「自吹自擂、自我标榜」，与后半句「没人会替你吹」呼应。",difficulty:3},{id:"vb-test-065",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"When it comes to job performance, Michael can't hold a candle to Tom. The underlined part means ______.",options:["is weaker than","is no better than","isn't compatible with","can't keep his temper with"],answer:"is weaker than",acceptedAnswers:[],explanationZh:"can't hold a candle to 意为「远不如、无法与……相比」，即「比……弱、差」。",difficulty:3},{id:"vb-test-066",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"He has been grinding out cheap romantic stories at the ______ of one a week.",options:["ratio","percentage","proportion","rate"],answer:"rate",acceptedAnswers:[],explanationZh:"at the rate of 表「以……的速度」，与「每周一本」的频率搭配；ratio、proportion 指比例。",difficulty:2},{id:"vb-test-067",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"After three years' hard study, he gained his ______ in psychometrics.",options:["warrant","degree","diploma","certificate"],answer:"diploma",acceptedAnswers:[],explanationZh:"diploma 指毕业文凭；certificate 多指培训证书，degree 指学位，warrant 意为「令状」。",difficulty:3},{id:"vb-test-068",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The boxer got ______ and fell down when his opponent gave him the final blow.",options:["staggered","stamped","scattered","shattered"],answer:"staggered",acceptedAnswers:[],explanationZh:"stagger 意为「踉跄、摇晃」，形容挨拳后站立不稳；scatter 意为「散开」，shatter 意为「破碎」。",difficulty:3},{id:"vb-test-069",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"People who work in the city actually ______ in neighbouring towns.",options:["stay","reside","lodge","inhabit"],answer:"reside",acceptedAnswers:[],explanationZh:"reside 为正式用词，意为「居住」，常与 in 连用；inhabit 是及物动词直接接地点，lodge 指临时寄宿。",difficulty:3},{id:"vb-test-070",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Choosing a car is not unlike choosing a dress. You should not only read the price ______ but also consider the image it conveys.",options:["brand","label","tag","trademark"],answer:"tag",acceptedAnswers:[],explanationZh:"price tag 指价格标签，此处喻指价格；label 泛指各种标签，brand、trademark 指品牌、商标。",difficulty:2},{id:"vb-test-071",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The president ______ the speech by making some additions and deletions.",options:["amended","patched","rectified","restored"],answer:"amended",acceptedAnswers:[],explanationZh:"amend 指对文本、文件作「修改、修订」，符合对演讲稿增删；patch 指修补，rectify 指纠正错误。",difficulty:3},{id:"vb-test-072",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The radio trumpeted the presidential ______ across the country.",options:["champion","champagne","campaign","chamber"],answer:"campaign",acceptedAnswers:[],explanationZh:"presidential campaign 指总统竞选；其余三项为形近词干扰。",difficulty:2},{id:"vb-test-073",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"You have to ______ by the judge's decision.",options:["abide","adhere","conform","comply"],answer:"abide",acceptedAnswers:[],explanationZh:"abide by 为固定搭配，意为「遵守」；adhere、conform 接 to，comply 接 with。",difficulty:3},{id:"vb-test-074",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"My neighbor ______ her own daughter as an excellent secretary!",options:["acquainted","introduced","recommended","presented"],answer:"recommended",acceptedAnswers:[],explanationZh:"recommend sb. as 意为「推荐某人担任」；acquaint 搭配 with，语义不符。",difficulty:2},{id:"vb-test-075",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Using this scope to ______ your view can make it easier to see the distant targets.",options:["amplify","extend","magnify","expand"],answer:"magnify",acceptedAnswers:[],explanationZh:"magnify 指用透镜把物体放大，与望远镜看远处目标相符；amplify 多指放大声音或信号。",difficulty:3},{id:"vb-test-076",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Physicians need ______ expertise in pain and symptom management and skills in communication to meet the many needs of this population.",options:["complex","complicated","intricate","sophisticated"],answer:"sophisticated",acceptedAnswers:[],explanationZh:"sophisticated 意为「精深、先进的」，可修饰专业知识；其余三项侧重「复杂」。",difficulty:4},{id:"vb-test-077",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The council is refusing to ______ further information about the dispute and its settlement.",options:["disclose","expose","uncover","discover"],answer:"disclose",acceptedAnswers:[],explanationZh:"disclose 意为「披露、透露」，宾语常为信息、秘密；expose 侧重揭露丑闻，discover 指发现未知事物。",difficulty:3},{id:"vb-test-078",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"His plan is full of contradictions, so it is not a very ______ one.",options:["refined","complex","elaborate","ambitious"],answer:"elaborate",acceptedAnswers:[],explanationZh:"elaborate 意为「精心制定的」，与「充满矛盾、考虑不周」形成对照；refined 指精炼的、文雅的。",difficulty:3},{id:"vb-test-079",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Their reply was too ______ for anyone to doubt them.",options:["eloquent","effective","emotional","emphatic"],answer:"emphatic",acceptedAnswers:[],explanationZh:"emphatic 意为「斩钉截铁的、坚决的」，令人无可置疑；eloquent 意为「雄辩的」，侧重口才。",difficulty:4},{id:"vb-test-080",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Jack jumped off the porch and ______ across the lawn.",options:["paced","strolled","strode","swung"],answer:"strode",acceptedAnswers:[],explanationZh:"stride 意为「大步走」，与「跳下门廊」的连贯动作相符；pace 是踱步，stroll 是漫步。",difficulty:3},{id:"vb-test-081",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Judging by the enthusiastic reception given him everywhere, they felt that his election was in the bag. The underlined part means ______.",options:["sure to be made","being considered","well prepared","very successful"],answer:"sure to be made",acceptedAnswers:[],explanationZh:"in the bag 为习语，意为「十拿九稳、稳操胜券」，对应「必定成功」。",difficulty:3},{id:"vb-test-082",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Under the agreement, all trade barriers between the two countries will be ______ by the end of this year.",options:["abolished","canceled","eliminated","disposed"],answer:"eliminated",acceptedAnswers:[],explanationZh:"eliminate 意为「消除、根除」，与贸易壁垒搭配；abolish 多指废除制度、法律，cancel 指取消安排。",difficulty:3},{id:"vb-test-083",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The newspaper reporters ______ that the man was murdered but they have given no proof.",options:["assert","affirm","announce","proclaim"],answer:"assert",acceptedAnswers:[],explanationZh:"assert 意为「断言、坚称」，与「拿不出证据」呼应；affirm 指坚信不疑地肯定。",difficulty:3},{id:"vb-test-084",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"I must leave now. ______, if you want that dress I'll bring it next time.",options:["Incidentally","Accidentally","Naturally","Eventually"],answer:"Incidentally",acceptedAnswers:[],explanationZh:"incidentally 意为「顺便说一下」，用于引入题外话；accidentally 意为「偶然地」。",difficulty:3},{id:"vb-test-085",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"When Mary got into the exam room, she just became anxious and her mind went completely ______.",options:["blank","empty","vacant","hollow"],answer:"blank",acceptedAnswers:[],explanationZh:"go blank 指头脑「一片空白」；empty 指容器空，vacant 指空置，hollow 指中空的。",difficulty:2},{id:"vb-test-086",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"My finances are on the rocks just now. The underlined part means ______.",options:["safe","a mess","tight","bankrupt"],answer:"bankrupt",acceptedAnswers:[],explanationZh:"on the rocks 指财务陷入困境、濒临破产，对应 bankrupt。",difficulty:3},{id:"vb-test-087",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Sometimes the student may be asked to write about his ______ a certain book or article that has some bearing on the subject being studied.",options:["comment","reaction","impression","comprehension"],answer:"reaction",acceptedAnswers:[],explanationZh:"reaction to 意为「对……的反应」，指读后感；comment 后接 on。",difficulty:3},{id:"vb-test-088",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"If you've ever driven on a highway during a heavy rain, you know about the danger of ______.",options:["skating","skidding","sliding","slipping"],answer:"skidding",acceptedAnswers:[],explanationZh:"skid 专指车辆行驶中打滑、侧滑；slip 多指滑倒，slide 指滑动，skate 指溜冰。",difficulty:3},{id:"vb-test-089",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Phil ______ forecast a big increase in sales, and he turned out to be right.",options:["confidentially","proudly","assuredly","confidently"],answer:"confidently",acceptedAnswers:[],explanationZh:"confidently 意为「自信地」，修饰「预测」；confidentially 意为「机密地」，形近易混。",difficulty:2},{id:"vb-test-090",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"A group ______ casinos has urged officials not to grant a license to a facility in the city.",options:["opposed to","objected to","posed against","protested against"],answer:"opposed to",acceptedAnswers:[],explanationZh:"opposed to 作后置定语表「反对的」；objected、protested 是谓语，不能作定语。",difficulty:3},{id:"vb-test-091",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"After the war, he worked on an island in the Pacific, helping the natives and medical ______ understand each other's behavior and cultures.",options:["faculty","persons","members","personnel"],answer:"personnel",acceptedAnswers:[],explanationZh:"medical personnel 指医务人员，为固定说法；faculty 多指院系教职员。",difficulty:3},{id:"vb-test-092",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The subject of manners is complex. If it were not, there would not be so many ______ feelings and so much misunderstanding in international communication.",options:["injurious","injured","injuring","injury"],answer:"injured",acceptedAnswers:[],explanationZh:"injured feelings 指受伤害的感情，为固定搭配；injurious 意为「有害的」。",difficulty:2},{id:"vb-test-093",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"FC Barcelona, ______ the most iconic club in world soccer, beat Manchester United 2-0 to claim the UEFA Champions League title.",options:["controversially","arguably","debatably","finally"],answer:"arguably",acceptedAnswers:[],explanationZh:"arguably 意为「可以说是」，引出公认评价；controversially、debatably 表「有争议地」。",difficulty:4},{id:"vb-test-094",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"The three law ______ officers on the plane came to the rescue of a fellow passenger who was allegedly trying to kill herself.",options:["enforcement","reinforcement","imposition","coercion"],answer:"enforcement",acceptedAnswers:[],explanationZh:"law enforcement officers 为固定搭配，指执法人员；reinforcement 意为「增援」。",difficulty:2},{id:"vb-test-095",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"Prices have recently risen in order to ______ the increased cost of raw materials.",options:["cut","buoy","offset","offer"],answer:"offset",acceptedAnswers:[],explanationZh:"offset 意为「抵消、补偿」，指提价以弥补原材料成本上涨；cut 意为削减，buoy 意为提振。",difficulty:3},{id:"vb-test-096",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:'The celebrity says in court papers she "has no ______ of giving any authorization to anyone to proceed with a divorce."',options:["recommendation","recording","recognition","recollection"],answer:"recollection",acceptedAnswers:[],explanationZh:"have no recollection of 意为「完全不记得」；recognition 意为「认出」。",difficulty:3},{id:"vb-test-097",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"What actually ______ a good angle-- or a good selfie overall-- is rooted in what we consider beautiful.",options:["consists of","composes","constitutes","constructs"],answer:"constitutes",acceptedAnswers:[],explanationZh:"constitute 意为「构成、是」；consist of 表示「由……组成」，主宾关系相反。",difficulty:4},{id:"vb-test-098",nodeId:"vb-test",categoryId:"vb-test",kind:"multiple-choice",prompt:"A leading ______ intelligence and operations company has released its analysis of worldwide reported incidents of piracy and crime against mariners.",options:["oceangoing","oceanic","marine","maritime"],answer:"maritime",acceptedAnswers:[],explanationZh:"maritime 意为「海事的」，符合海事安全语境；marine 侧重「海洋的」，oceangoing 指远洋航行的。",difficulty:3}]},d={categories:[{id:"wr-fix",titleZh:"句子纠错",noteZh:"run-on、片段、错位修饰语 —— 动手改。"},{id:"wr-combine",titleZh:"句式变换",noteZh:"合句、改写、换开头，把句子调顺。"},{id:"wr-para",titleZh:"段落诊断",noteZh:"读一段，找毛病，再对照参考。"},{id:"wr-model",titleZh:"写作范例",noteZh:"先照题目写，再对照范文找差距。"}],items:[{id:"wr-fix-01",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 6",prompt:"用逗号加并列连词（and, but, for, so）改正下面的 run-on 句：He used to fill up his tank with $10 worth of gas today the gas costs him $15.",options:[],answer:"He used to fill up his tank with $10 worth of gas, but today the gas costs him $15.",acceptedAnswers:[],explanationZh:"run-on 句：两个完整句之间需补并列连词，but 表今昔对比。",difficulty:2,selfCheck:!0},{id:"wr-fix-02",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 7",prompt:"用分号（;）改正下面的 run-on 句：He took enormous bites of the roast beef sandwich it was the first decent thing he had eaten all day.",options:[],answer:"He took enormous bites of the roast beef sandwich; it was the first decent thing he had eaten all day.",acceptedAnswers:[],explanationZh:"run-on 句：关系紧密的两个完整句可用分号直接连接。",difficulty:2,selfCheck:!0},{id:"wr-fix-03",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 8",prompt:"用句号和大写字母改正下面的 run-on 句：Those berries are poisonous don't eat them.",options:[],answer:"Those berries are poisonous. Don't eat them.",acceptedAnswers:[],explanationZh:"run-on 句：无标点粘连的两个完整句可用句号拆开。",difficulty:1,selfCheck:!0},{id:"wr-fix-04",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 9",prompt:"改正下面的句子片段（dependent-word fragment），把它和后面的句子连成一个完整句：After I slid my aching bones into the hot tub water. I realized that there was no soap.",options:[],answer:"After I slid my aching bones into the hot tub water, I realized that there was no soap.",acceptedAnswers:[],explanationZh:"以 after 开头的从属分句不能独立成句，应并入主句，句首时加逗号。",difficulty:2,selfCheck:!0},{id:"wr-fix-05",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 10",prompt:"改正下面的句子片段（-ing fragment），把它并入前面的句子：After the alarm rang, he lay in bed ten minutes longer. Wishing that he had $100,000.",options:[],answer:"After the alarm rang, he lay in bed ten minutes longer, wishing that he had $100,000.",acceptedAnswers:[],explanationZh:"-ing 开头、缺主语和谓语动词的词组是片段，应并入前句。",difficulty:2,selfCheck:!0},{id:"wr-fix-06",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 11",prompt:"改正下面的句子片段（added-detail fragment），把它并入前面的句子：One of my greatest joys in life is eating desserts. Such as jello, cake or ice cream.",options:[],answer:"One of my greatest joys in life is eating desserts, such as jello, cake or ice cream.",acceptedAnswers:[],explanationZh:"such as 引出的细节缺少主语和动词，应并入前句。",difficulty:2,selfCheck:!0},{id:"wr-fix-07",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 12",prompt:"改正下面的句子片段（missing-subject fragment），把它并入前面的句子：Tom went to the refrigerator to get milk for his breakfast cereal. And discovered about one tablespoon of milk left.",options:[],answer:"Tom went to the refrigerator to get milk for his breakfast cereal and discovered about one tablespoon of milk left.",acceptedAnswers:[],explanationZh:"以 and 开头、缺主语的片段应并入前句，与前句共用主语。",difficulty:2,selfCheck:!0},{id:"wr-fix-08",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 16",prompt:"改正下面句子的平行结构错误：My father's car is sporty, fast, expensive, and it is also quite comfortable.",options:[],answer:"My father's car is sporty, fast, expensive, and comfortable.",acceptedAnswers:[],explanationZh:"并列成分要保持同一形式：四个形容词并列，删去 it is also。",difficulty:2,selfCheck:!0},{id:"wr-fix-09",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 17",prompt:"改正下面句子的平行结构错误（关联连词）：She is neither young nor is she inexperienced.",options:[],answer:"She is neither young nor inexperienced.",acceptedAnswers:[],explanationZh:"neither ... nor 前后要用相同的结构。",difficulty:2,selfCheck:!0},{id:"wr-fix-10",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"常见错误",prompt:"改正下面句子的 and which 错误：James Joyce's Ulysses, a long and complicated novel and which is on our reading list, has been banned by the school board.",options:[],answer:"James Joyce's Ulysses, which is a long and complicated novel and which is on our reading list, has been banned by the school board.",acceptedAnswers:[],explanationZh:"and which 前必须已有 which 从句，不能与名词短语并列。",difficulty:3,selfCheck:!0},{id:"wr-fix-11",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 18",prompt:"改正下面句子的修饰语位置错误，让 that 从句紧贴它所修饰的词：Charlotte returned the hamburger to the supermarket that was spoiled.",options:[],answer:"Charlotte returned the hamburger that was spoiled to the supermarket.",acceptedAnswers:[],explanationZh:"that was spoiled 修饰 hamburger，应紧跟其后。",difficulty:2,selfCheck:!0},{id:"wr-fix-12",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"常见错误",prompt:"改正下面句子的修饰语位置错误：Tony bought an old car from a crooked dealer with a faulty transmission.",options:[],answer:"Tony bought an old car with a faulty transmission from a crooked dealer.",acceptedAnswers:[],explanationZh:"with a faulty transmission 修饰 old car，应紧贴其后。",difficulty:2,selfCheck:!0},{id:"wr-fix-13",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 32",prompt:"改正下面句子的垂悬修饰语错误：Dilapidated and almost an eyesore, Shirley bought the old house to restore it to its original beauty.",options:[],answer:"Shirley bought the old house, which was dilapidated and almost an eyesore, to restore it to its original beauty.",acceptedAnswers:[],explanationZh:"垂悬修饰语：Dilapidated 描述的是房子，需改写为定语从句。",difficulty:3,selfCheck:!0},{id:"wr-fix-14",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 32",prompt:"改正下面句子的平行结构错误（注意省略造成的缺词）：There was a consultation between those who favored and opposed the project.",options:[],answer:"There was a consultation between those who favored the project and those who opposed it.",acceptedAnswers:[],explanationZh:"favored 后缺宾语，应补出 project 使并列结构完整。",difficulty:3,selfCheck:!0},{id:"wr-fix-15",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 32",prompt:"改正下面句子的垂悬修饰语错误：Dressed in her new spring finery, a passing taxi splashed her with mud from head to foot.",options:[],answer:"Dressed in her new spring finery, she was splashed with mud from head to foot by a passing taxi.",acceptedAnswers:[],explanationZh:"垂悬修饰语：Dressed in 的逻辑主语是 she，主句主语须一致。",difficulty:3,selfCheck:!0},{id:"wr-fix-16",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 32",prompt:"改正下面句子的片段错误，把细节并入前面的句子：The principal could get nothing done. Especially with the telephone ringing constantly and disgruntled parents barging into his office.",options:[],answer:"The principal could get nothing done, especially with the telephone ringing constantly and disgruntled parents barging into his office.",acceptedAnswers:[],explanationZh:"Especially 引出的细节缺主语和动词，应并入前句。",difficulty:3,selfCheck:!0},{id:"wr-fix-17",nodeId:"wr-fix",categoryId:"wr-fix",kind:"short-answer",label:"练习 32",prompt:"改正下面句子的代词一致错误：A test can let us know how you are getting on with your studies recently, and help us to realize the holes of our studies.",options:[],answer:"A test can let us know how we are getting on with our studies recently, and help us to realize the holes of our studies.",acceptedAnswers:[],explanationZh:"人称前后不一致：you 应改为 we，与 our 呼应。",difficulty:3,selfCheck:!0},{id:"wr-combine-01",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 3",prompt:"用从属连词 because 把下面两个简单句合并成一个复合句（从属分句在句首时加逗号）：The movie disgusted the coach. He walked out after fifteen minutes.",options:[],answer:"Because the movie disgusted the coach, he walked out after fifteen minutes.",acceptedAnswers:[],explanationZh:"because 引导原因从句，从句在句首时用逗号与主句隔开。",difficulty:1,selfCheck:!0},{id:"wr-combine-02",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 3",prompt:"用合适的从属连词把下面两个简单句合并成一个复合句（从属分句在句首时加逗号）：His vision begins to fade. He knows he'd better get some rest.",options:[],answer:"When his vision begins to fade, he knows he'd better get some rest.",acceptedAnswers:[],explanationZh:"when 引导时间从句，从句在前时加逗号。",difficulty:2,selfCheck:!0},{id:"wr-combine-03",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 4",prompt:"用从属结构（不用并列连词）改写下面的句子：The muffler shop advertised same-day service, but my car wasn't ready for three days.",options:[],answer:"Although the muffler shop advertised same-day service, my car wasn't ready for three days.",acceptedAnswers:[],explanationZh:"用 although 把并列句改为从属结构，让步从句在句首加逗号。",difficulty:2,selfCheck:!0},{id:"wr-combine-04",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 5",prompt:"用关系代词 who 把下面两个简单句合并成一个复合句，省略重复的词：Joan is a champion weight lifter. Joan is my neighbour.",options:[],answer:"Joan, who is my neighbour, is a champion weight lifter.",acceptedAnswers:[],explanationZh:"who 引导的非限定性定语从句前后加逗号。",difficulty:1,selfCheck:!0},{id:"wr-combine-05",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 5",prompt:"用关系代词 which 把下面两个简单句合并成一个复合句，省略重复的词：The letter is from my friend abroad. The letter arrived today.",options:[],answer:"The letter, which arrived today, is from my friend abroad.",acceptedAnswers:[],explanationZh:"which 引导的定语从句紧跟先行词 letter。",difficulty:1,selfCheck:!0},{id:"wr-combine-06",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 5",prompt:"用关系代词 which 把下面两个简单句合并成一个复合句，省略重复的词：The tall hedge muffled the highway noise. The hedge surrounded the house.",options:[],answer:"The tall hedge, which surrounded the house, muffled the highway noise.",acceptedAnswers:[],explanationZh:"which 引导的定语从句紧跟先行词 hedge。",difficulty:1,selfCheck:!0},{id:"wr-combine-07",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 26",prompt:"用 -ly 副词开头把下面两句合成一句：Mary squirmed in her seat as she waited for her turn to speak. She was nervous.",options:[],answer:"Nervously, Mary squirmed in her seat as she waited for her turn to speak.",acceptedAnswers:[],explanationZh:"形容词 nervous 变副词 nervously 放句首，句子更简洁有力。",difficulty:1,selfCheck:!0},{id:"wr-combine-08",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 26",prompt:"用 -ly 副词开头把下面两句合成一句：I tore the wrapping off the present. I was excited.",options:[],answer:"Excitedly, I tore the wrapping off the present.",acceptedAnswers:[],explanationZh:"形容词 excited 变副词 excitedly 放句首。",difficulty:1,selfCheck:!0},{id:"wr-combine-09",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 27",prompt:"用 to 动词不定式短语开头把下面两句合成一句，句首短语后用逗号：I fertilize the grass every spring. I want to make it greener.",options:[],answer:"To make the grass greener, I fertilize it every spring.",acceptedAnswers:[],explanationZh:"to 不定式短语放句首表目的，用逗号隔开。",difficulty:1,selfCheck:!0},{id:"wr-combine-10",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 25",prompt:"用 -ing 分词短语把下面两句合成一句，用逗号把 -ing 词组和其余部分隔开：The diesel truck chugged up the hill. It spewed out black smoke.",options:[],answer:"Chugging up the hill, the diesel truck spewed out black smoke.",acceptedAnswers:[],explanationZh:"-ing 分词短语放句首修饰主语，逻辑主语须一致。",difficulty:2,selfCheck:!0},{id:"wr-combine-11",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 29",prompt:"用 -ed 分词短语开头把下面两句合成一句，句首短语后用逗号：The old dollar bill felt like tissue paper. It was crinkled with age.",options:[],answer:"Crinkled with age, the old dollar bill felt like tissue paper.",acceptedAnswers:[],explanationZh:"-ed 分词短语放句首修饰主语，逻辑主语须一致。",difficulty:2,selfCheck:!0},{id:"wr-combine-12",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 31",prompt:"把下面三个短句合成一个长句（可省略重复的词、分组并用逗号隔开）：I studied history in the afternoon. Then in the evening I studied English. After that, I treated myself to a movie.",options:[],answer:"In the afternoon I studied history, in the evening I studied English, and after that I treated myself to a movie.",acceptedAnswers:[],explanationZh:"用并列结构把短句合成长句，节奏更连贯。",difficulty:2,selfCheck:!0},{id:"wr-combine-13",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 31",prompt:"用强调句式（It was ... that ...）改写下面两句，突出价格的作用：The fashion didn't make Hellen buy the clothes. The price made her do so.",options:[],answer:"It was the price, not the fashion, that made Hellen buy the clothes.",acceptedAnswers:[],explanationZh:"强调句式 It was ... that ... 突出真正的原因。",difficulty:3,selfCheck:!0},{id:"wr-combine-14",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 31",prompt:"用倒装语序改写下面的句子：Wisdom and the ability to help others with advice wisely given should come with old age.",options:[],answer:"With old age should come wisdom and the ability to help others with advice wisely given.",acceptedAnswers:[],explanationZh:"介词短语提前、主谓倒装，突出句末的主语。",difficulty:4,selfCheck:!0},{id:"wr-combine-15",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 31",prompt:"把下面的长句改写成更简短、直接的句子：It seemed to me that the noodles that they served were a bit gummy and stuck together.",options:[],answer:"The noodles they served seemed a bit gummy and stuck together.",acceptedAnswers:[],explanationZh:"删去 It seemed to me that 等套语，直接以 noodles 作主语。",difficulty:2,selfCheck:!0},{id:"wr-combine-16",nodeId:"wr-combine",categoryId:"wr-combine",kind:"short-answer",label:"练习 1",prompt:"把下面的句子改成圆周句（periodic sentence），让主要意思最后出现：The course was not very difficult although I didn't receive a high grade.",options:[],answer:"Although I didn't receive a high grade, the course was not very difficult.",acceptedAnswers:[],explanationZh:"圆周句：让步从句前置，主要意思留到最后，增强悬念。",difficulty:2,selfCheck:!0},{id:"wr-para-01",nodeId:"wr-para",categoryId:"wr-para",kind:"short-answer",label:"主题句",prompt:"下面两句都当不好段落主题句，请分别指出毛病，再把它们改成合格的主题句（点出话题，也给出段落要展开的方向）：(1) I have a roommate. (2) My roommate always leaves his dirty socks in the bathroom.",options:[],acceptedAnswers:[],answer:"(1) 太笼统：只有一个话题，没有告诉读者段落要展开什么。(2) 太具体：它本身就是段落里该出现的一个细节（例子），把展开的空间提前挤掉了。改成「话题 + 控制性观点」即可，改法不唯一，例如：My roommate is a messy person. / My roommate and I are very different. / A good roommate has three basic qualities.",explanationZh:"主题句 = 话题 + 控制性观点；既不笼统到无从下手，也不细到抢了支撑句的活。",difficulty:2,selfCheck:!0},{id:"wr-para-02",nodeId:"wr-para",categoryId:"wr-para",kind:"short-answer",label:"补主题句",prompt:"读下面的段落，从 A–D 里选一个最合适的主题句，并说明理由：Some stay up the night before, trying to cram into their brains what they avoided all term. Others pace themselves, spending a little time each night going over the notes they took in class that day. Still others cross their fingers and hope they absorbed enough from lectures. A dishonest few pray that their fellow students will give them the answers. In the end, though, everyone hopes the tests are easy. A. Final exams are drawing near. B. Preparing for final exams needs painstaking efforts. C. Final examinations are always difficult for students. D. Students have diverse ways of preparing for final exams.",options:[],acceptedAnswers:[],answer:"选 D。整段列举的都是不同的备考方式——熬夜突击、每晚消化、碰运气、指望同学给答案，正好落在「方式多样」上。A 只说考试临近；B 和 C 讲的是「费劲、难」，段落没有展开这一层，撑不住。",explanationZh:"主题句要统得起全部支撑句：段落讲什么，题句就写什么；说得通但撑不住的选项都不合格。",difficulty:2,selfCheck:!0},{id:"wr-para-03",nodeId:"wr-para",categoryId:"wr-para",kind:"short-answer",label:"句子节奏",prompt:"下面这段话句子又短又碎（choppy），读起来一顿一顿的。合并同类、去掉重复，把它改写成一个顺畅的段落：I enjoy Christmas very much. I like shopping. I like decorating the tree. I like giving presents. I enjoy eating on Christmas Day. I enjoy eating turkey. I like a lot of dressing. I like pumpkin pie. I also like being with the family. I like seeing my grandmother. I like seeing my nieces.",options:[],acceptedAnswers:[],answer:"I enjoy Christmas very much. I like shopping and decorating the tree, and I also enjoy giving presents. On Christmas Day, I love eating all the turkey, dressing, and pumpkin pie. Finally, I look forward to being with the family and seeing my grandmother and nieces in particular.",explanationZh:"删掉重复的 I like / I enjoy，把同类项并进一句，再用 On Christmas Day 与 Finally 分层，节奏就起来了。",difficulty:2,selfCheck:!0},{id:"wr-para-04",nodeId:"wr-para",categoryId:"wr-para",kind:"short-answer",label:"段落连贯",prompt:"下面的段落一句接一句地排着，没有衔接词，读起来像流水账。补上恰当的时间与先后衔接词，把它改写得连贯：My morning routine never changes. My alarm clock rings for the third time. I get up. I sleepwalk to the shower. I stand in the shower for ten minutes. I am finally awake. I get dressed. I go to the kitchen, make a cup of tea, and put a slice of bread in the toaster. I eat breakfast and feed my cat. I put her outside. I am ready to face the world. I get on the bus and go to school. My first class begins. I go back to sleep.",options:[],acceptedAnswers:[],answer:"My morning routine never changes. When my alarm clock rings for the third time, I get up and sleepwalk to the shower. I stand in the shower for ten minutes until I am finally awake. Then I get dressed. Next, I go to the kitchen, make a cup of tea, and put a slice of bread in the toaster. After I eat breakfast and feed my cat, I put her outside. Finally, I am ready to face the world, so I get on the bus and go to school. As soon as my first class begins, I go back to sleep.",explanationZh:"When / until / Then / Next / After / Finally / As soon as：衔接词把动作按先后串成一条线，句子也要顺手合并。",difficulty:2,selfCheck:!0},{id:"wr-para-05",nodeId:"wr-para",categoryId:"wr-para",kind:"short-answer",label:"支撑细节",prompt:"下面这段只有笼统的陈述，撑不起主题句。用数据、具体名字、事例和权威引语把它写具体（可参考：只有约 1,000 只野生大熊猫、栖息地化整为零、1999 年圣地亚哥动物园的 Bai Yun 和 Shi Shi）：Giant pandas are an endangered species. There are not many pandas still living in the wild. The area in China where they live is quite small, and they do not reproduce in zoos easily. There has been only one panda baby born in a zoo in the United States. Experts say that pandas in zoos don't reproduce well enough to maintain the species.",options:[],acceptedAnswers:[],answer:"Giant pandas are an endangered species. Only about 1,000 giant pandas still live in the wild, occupying six small forest fragments totaling 5,400 square miles in the provinces of Sichuan, Gansu, and Shaanxi in southwestern China. Not only is their natural habitat limited, but they also do not reproduce easily in zoos. In 1999, Bai Yun and Shi Shi, two pandas in the San Diego Zoo, produced the first zoo-born baby panda outside China in ten years. According to the San Diego Zoo's Center for Reproduction of Endangered Species, “Captive pandas are not reproducing well enough to maintain the species.”",explanationZh:"数据（1,000 只、5,400 平方英里）、具体名字（Bai Yun 和 Shi Shi）、事例（1999 年首例）和引语，把笼统断言撑成可信的段落。",difficulty:3,selfCheck:!0},{id:"wr-para-06",nodeId:"wr-para",categoryId:"wr-para",kind:"short-answer",label:"段落统一",prompt:"下面段落里混进了跑题的句子。先找出与主题无关的句子（可引用原句）并说明为什么跑题，再给出删改后的段落：Cigarette smoke is unhealthy even for people who don't have the nicotine habit themselves. Secondhand smoke can cause asthmatics and sufferers of sinusitis serious problems; doctors regularly advise heart patients to avoid confined smoky areas because coronary attacks might be triggered by the lack of clean air. Moreover, having the smell of smoke in one's hair and clothes is a real nuisance. Even if a person is without any health problems, exhaled smoke doubles the amount of carbon monoxide in the air, a condition that may cause lung problems in the future.",options:[],acceptedAnswers:[],answer:"跑题句：Moreover, having the smell of smoke in one's hair and clothes is a real nuisance. 这一段从头到尾讲二手烟对健康的危害（呼吸道、心脏、一氧化碳），而「衣服头发上的烟味难闻」是舒适度问题，和主题句里的 unhealthy 不沾边。删掉它，段落就统一了：Cigarette smoke is unhealthy even for people who don't have the nicotine habit themselves. Secondhand smoke can cause asthmatics and sufferers of sinusitis serious problems; doctors regularly advise heart patients to avoid confined smoky areas because coronary attacks might be triggered by the lack of clean air. Even if a person is without any health problems, exhaled smoke doubles the amount of carbon monoxide in the air, a condition that may cause lung problems in the future.",explanationZh:"统一 = 每一句都直接服务于同一个主题；讲着讲着拐到「难闻」这种旁枝，段落就松了。",difficulty:3,selfCheck:!0},{id:"wr-model-01",nodeId:"wr-model",categoryId:"wr-model",kind:"short-answer",label:"记叙文",prompt:"题目：An Unforgettable Experience——记叙一次难忘的经历。时间、地点、过程要交代清楚，按时间顺序推进，结尾写出这件事对你的意义。先在下面写，写完再对照范文。",options:[],acceptedAnswers:[],answer:`An Unforgettable Experience

The day I stood on the stage of the campus speech contest remains the most unforgettable experience of my freshman year. For two weeks, I had practiced my speech until I could recite it in my sleep, and yet my hands were still shaking when my name was called.

When I walked to the microphone, my mind suddenly went blank. For a few painful seconds, I could hear nothing but my own heartbeat. Then I caught sight of my roommate in the third row, giving me a thumbs-up, and the first sentence came back to me. After that, the words flowed naturally, and I even managed to smile at my own joke.

I only won third prize, but the contest changed me in a way no award could. It taught me that courage is not the absence of fear, but the decision to speak while your hands are still shaking.`,explanationZh:"开头一句点题；中段用时间衔接词（When / Then / After that）推进；结尾从经历里提炼出一句站得住的话。",difficulty:2,selfCheck:!0},{id:"wr-model-02",nodeId:"wr-model",categoryId:"wr-model",kind:"short-answer",label:"描写文",prompt:"题目：My Favorite Place——描写一个你最喜欢的地方。用看到的、听到的、闻到的细节把画面写活，让读者像站在那里一样；结尾说说这个地方对你意味着什么。先在下面写，写完再对照范文。",options:[],acceptedAnswers:[],answer:`My Favorite Place

My favorite place on campus is the old reading room on the fourth floor of the library. It is not beautiful by any standard, but the moment I push open its heavy wooden door, the rest of the world falls silent.

Pale winter light slants through the tall windows and lies across the long tables, where generations of students have left faint scratches and ink marks. The air smells of old paper and warm dust, and the only sound is the soft rustle of turning pages. Even the wooden chairs creak politely, as if they know that raised voices do not belong here.

Whenever my mind feels crowded, I carry my books to a corner seat by the window. Half an hour in that room does more for me than a whole afternoon of sleep.`,explanationZh:"以「不美但安静」的反差起句，随后全是感官细节（光、气味、翻页声），末段用一个对比收束。",difficulty:3,selfCheck:!0},{id:"wr-model-03",nodeId:"wr-model",categoryId:"wr-model",kind:"short-answer",label:"过程说明",prompt:"题目：How to Prepare for a Final Exam——按顺序说明你的复习步骤，用 First / Next / Then / Finally 一类的衔接词把过程串起来，让读者能照着做。先在下面写，写完再对照范文。",options:[],acceptedAnswers:[],answer:`How to Prepare for a Final Exam

Preparing well for a final exam is less about talent than about method. The following steps can turn a week of panic into a week of steady progress.

First, start by making a realistic plan. List every topic the exam will cover, and divide them into small daily tasks; crossing off each task gives you a sense of progress. Next, review your notes within twenty-four hours of every lecture, because memory fades fastest in the first day. Then, instead of rereading the textbook, test yourself with questions you write in advance—active recall is far more effective than passive reading. Finally, on the night before the exam, close your books early and sleep well. A fresh mind with eight hours of rest will always beat a tired mind with one more chapter.

Follow these steps, and you will walk into the exam room prepared, calm, and confident.`,explanationZh:"过程说明的标准骨架：总起一句 + First / Next / Then / Finally 四步，每步都配一个理由，结尾回扣主题。",difficulty:2,selfCheck:!0},{id:"wr-model-04",nodeId:"wr-model",categoryId:"wr-model",kind:"short-answer",label:"对比说明",prompt:"题目：Living in a Dormitory or Living at Home——对比住校与走读两种生活（时间安排、独立程度、与家人的关系等），用 On the one hand / On the other hand / In contrast / However 一类的衔接词组织。先在下面写，写完再对照范文。",options:[],acceptedAnswers:[],answer:`Living in a Dormitory or Living at Home

Choosing between living in a dormitory and living at home is a choice between two different ways of growing up.

Living in a dormitory teaches independence and friendship. On the one hand, students must manage their own time, money, and laundry, and nobody wakes them up for an eight o'clock class. On the other hand, the shared room and the crowded corridor may be the most valuable part of campus life: roommates discuss books and dreams late into the night, and they learn to settle differences politely. Nor should the advantages of living at home be neglected. In contrast to the noisy dormitory, home offers quiet space, home-cooked meals, and the steady support of family.

Neither choice is perfect. However, for a student who wants to grow up quickly, the dormitory, with all its noise and friendship, is often the better teacher.`,explanationZh:"对比说明的两面都写足：一边的独立与友谊，另一边的安静与支持；结尾不回避两面，而是给出取舍。",difficulty:3,selfCheck:!0},{id:"wr-model-05",nodeId:"wr-model",categoryId:"wr-model",kind:"short-answer",label:"议论文",prompt:"题目：Should College Students Take Part-time Jobs?——亮明你的立场，用两到三个理由支撑，预想一个反对意见并作出回应，最后收束观点。先在下面写，写完再对照范文。",options:[],acceptedAnswers:[],answer:`Should College Students Take Part-time Jobs?

More and more college students spend part of their week at part-time jobs, and whether they should has become a common topic on campus. In my opinion, a sensible part-time job does students far more good than harm.

First, it gives them a taste of the real world. Standing behind a counter or translating for a company, students learn that punctuality, teamwork, and patience matter more than exam scores. Second, earning their own money teaches responsibility. A student who works for two months to pay for a laptop will treat that laptop quite differently. Admittedly, some people worry that a job will occupy too much study time. However, this problem can be avoided if the job is limited to weekends and the student remembers that study comes first.

A part-time job is not a distraction from college, but part of it. What we learn outside the classroom may stay with us even longer than what we learn inside.`,explanationZh:"议论文的常用骨架：立场—理由两条—让步并反驳（Admittedly... However...）—收束，条条都有着落。",difficulty:3,selfCheck:!0},{id:"wr-model-06",nodeId:"wr-model",categoryId:"wr-model",kind:"short-answer",label:"建议信",prompt:"题目：A Letter of Advice——朋友李明来信说，社团活动占用了太多学习时间，心里很烦恼。写一封约 120–150 词的回信，给出三条可操作的建议，注意书信格式（称呼、正文、落款）。先在下面写，写完再对照范文。",options:[],acceptedAnswers:[],answer:`Dear Li Ming,

I am sorry to hear that club activities are taking up so much of your time. I have been in the same situation, and I would like to offer three pieces of advice.

To begin with, list everything you do in a week, including meetings and homework. Seeing your time on paper will show you where it goes. Secondly, learn to say no politely. Clubs welcome helpers, but a firm 'not this week' will not hurt your friendships. Finally, combine the two when possible: if your club needs a poster or a report, volunteer to make it, and practice your writing at the same time.

Your enthusiasm for your club is a gift, not a problem. With a plan and a friendly 'no', I am sure you can keep both your grades and your friends.

Yours,
Zhang Wei`,explanationZh:"建议信格式完整（称呼、致意、三条建议、鼓励、落款），建议用 To begin with / Secondly / Finally 排开，条条可操作。",difficulty:2,selfCheck:!0}]},c=[{id:"tr-han-01",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《匆匆》· 一",prompt:"燕子去了，有再来的时候；杨柳枯了，有再青的时候；桃花谢了，有再开的时候。但是，聪明的，你告诉我，我们的日子为什么一去不复返呢？——是有人偷了他们罢：那是谁？又藏在何处呢？是他们自己逃走了罢：现在又到了哪里呢？",options:[],answer:"Swallows may have gone, but there is a time of return; willow trees may have died back, but there is a time of regreening; peach blossoms may have fallen, but they will bloom again. Now, you the wise, tell me, why should our days leave us, never to return? —If they had been stolen by someone, who could it be? Where could he hide them? If they had made the escape themselves, then where could they stay at the moment?",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-02",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《匆匆》· 二",prompt:"我不知道他们给了我多少日子；但我的手确乎是渐渐空虚了。在默默里算着，八千多日子已经从我手中溜去；像针尖上一滴水滴在大海里，我的日子滴在时间的流里，没有声音，也没有影子。我不禁头涔涔而泪潸潸了。",options:[],answer:"I do not know how many days I have been given to spend, but I do feel my hands are getting empty. Taking stock silently, I find that more than eight thousand days have already slid away from me. Like a drop of water from the point of a needle disappearing into the ocean, my days are dripping into the stream of time, soundless, traceless. Already sweat is starting on my forehead, and tears welling up in my eyes.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-03",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《匆匆》· 三",prompt:"去的尽管去了，来的尽管来着，去来的中间，又怎样地匆匆呢？早上我起来的时候，小屋里射进两三方斜斜的太阳。太阳他有脚啊，轻轻悄悄地挪移了；我也茫茫然跟着旋转。于是——洗手的时候，日子从水盆里过去；吃饭的时候，日子从饭碗里过去；默默时，便从凝然的双眼前过去。我觉察他去的匆匆了，伸出手遮挽时，他又从遮挽着的手边过去，天黑时，我躺在床上，他便伶伶俐俐地从我身上跨过，从我脚边飞去了。等我睁开眼和太阳再见，这算又溜走了一日。我掩着面叹息。但是新来的日子的影儿又开始在叹息里闪过了。",options:[],answer:"Those that have gone have gone for good, those to come keep coming; yet in between, how swift is the shift, in such a rush? When I get up in the morning, the slanting sun marks its presence in my small room in two or three oblongs. The sun has feet, look, he is treading on, lightly and furtively; and I am caught, blankly, in his revolution. Thus—the day flows away through the sink when I wash my hands, wears off in the bowl when I eat my meal, and passes away before my day-dreaming gaze as I reflect in silence. I can feel his haste now, so I reach out my hands to hold him back, but he keeps flowing past my withholding hands. In the evening, as I lie in bed, he strides over my body, glides past my feet, in his agile way. The moment I open my eyes and meet the sun again, one whole day has gone. I bury my face in my hands and heave a sigh. But the new day begins to flash past in the sigh.",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-han-04",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《匆匆》· 四",prompt:"在逃去如飞的日子里，在千门万户的世界里的我能做些什么呢？只有徘徊罢了，只有匆匆罢了；在八千多日的匆匆里，除徘徊外，又剩些什么呢？过去的日子如轻烟被微风吹散了，如薄雾，被初阳蒸融了；我留着些什么痕迹呢？我何曾留着像游丝样的痕迹呢？我赤裸裸来到这世界，转眼间也将赤裸裸的回去罢？但不能平的，为什么偏要白白走这一遭啊？",options:[],answer:"What can I do, in this bustling world, with my days flying in their escape? Nothing but to hesitate, to rush. What have I been doing in that eight-thousand-day rush, apart from hesitating? Those bygone days have been dispersed as smoke by a light wind, or evaporated as mist by the morning sun. What traces have I left behind me? Have I ever left behind any gossamer traces at all? I have come to this world, stark naked; am I to go back, in a blink, in the same stark nakedness? It is not fair though: why should I have made such a trip for nothing!",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-05",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《匆匆》· 五",prompt:"你聪明的，告诉我，我们的日子为什么一去不复返呢？",options:[],answer:"You the wise, tell me, why should our days leave us, never to return?",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-06",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《丑石》· 一",prompt:"我常常遗憾我家门前的那块丑石呢：它黑黝黝地卧在那里，牛似的模样；谁也不知道是什么时候留在这里的，谁也不去理会它。只是麦收时节，门前摊了麦子，奶奶总是要说：这块丑石，多碍地面哟，多时把它搬走吧。",options:[],answer:'I used to feel sorry for that ugly black piece of stone lying like an ox in front of our door; none knew when it was left there and none paid any attention to it, except at the time when wheat was harvested and my grandma, seeing the grains of wheat spread all over the ground in the front yard of the house, would grumble: "This ugly stone takes so much space. Move it away someday."',acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-07",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《丑石》· 二",prompt:"终有一日，村子里来了一个天文学家。他在我家门前路过，突然发现了这块石头，眼光立即就拉直了。他再没有走去，就住了下来；以后又来了好些人，说这是一块陨石，从天上落下来已经有二三百年了，是一件了不起的东西。不久便来了车，小心翼翼地将它运走了。",options:[],answer:"Then one day an astronomer came to the village. He looked the stone square in the eye the moment he came across it. He didn't take his leave but decided to stay in our village. Quite a number of people came afterwards, saying the stone was a piece of aerolite which had fallen down from the sky two or three hundred years ago—what a wonder indeed! Pretty soon a truck came, and carried it away carefully.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-08",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《丑石》· 三",prompt:"这使我们都很惊奇！这又怪又丑的石头，原来是天上的呢！它补过天，在天上发过热，闪过光，我们的先祖或许仰望过它，它给了他们光明、向往、憧憬；而它落下来了，在污土里，荒草里，一躺就是几百年了？！",options:[],answer:"It gave us a great surprise! We had never expected that such a strange and ugly stone should have come from the sky! So it had once mended the sky, given out its heat and light there, and our ancestors should have looked up at it. It had given them light, brought them hopes and expectations, and then it had fallen down to the earth, in the mud and among the weeds, lying there for hundreds of years!",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-09",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《丑石》· 四",prompt:"奶奶说：“真看不出！它那么不一般，却怎么连墙也垒不成，台阶也垒不成呢？”",options:[],answer:`My grandma said: "I never expected it should be so great! But why can't people build a wall or pave steps with it?"`,acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-10",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《丑石》· 五",prompt:"我感到自己的可耻，也感到了丑石的伟大；我甚至怨恨它这么多年竟会默默地忍受着这一切，而我又立即深深地感到它那种不屈于误解、寂寞的生存的伟大。",options:[],answer:"I feel shame while I feel the greatness of the ugly stone; I have even complained about it having pocketed silently all it had experienced for so many years, but again I am struck by the greatness that lies in its lonely unyielding existence of being misunderstood by people.",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-11",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《落花生》· 一",prompt:"我们屋后有半亩隙地。母亲说：“让它荒芜着怪可惜，既然你们那么爱吃花生，就辟来做花生园罢。”我们几姊弟和几个小丫头都很喜欢——买种的买种，动土的动土，灌园的灌园；过不了几个月，居然收获了！",options:[],answer:`At the back of our house there was half a mu of vacant land. "It's a pity to let it go to waste like that," Mother said. "Since you all enjoy eating peanuts, let us open it up and make it a peanut garden." At that my brother, sister and I were all delighted and so were the young housemaids. Some went to buy seeds, some dug the ground and others watered it and, in a couple of months, we had a harvest!`,acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-12",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《落花生》· 二",prompt:"妈妈说：“今晚我们可以做一个收获节，也请你们爹爹来尝尝我们底新花生，如何？”我们都答应了。母亲把花生做成好几样食品，还吩咐这节期要在园里底茅亭举行。",options:[],answer:'"Let us have a party tonight to celebrate," Mother suggested, "and ask Dad to come for a taste of our fresh peanuts. What do you say?" We all agreed, of course. Mother cooked the peanuts in different styles and told us to go to the thatched pavilion in the garden for the celebration.',acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-13",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《落花生》· 三",prompt:"我说：“无论何等人都可以用贱价买它来吃；都喜欢吃它。这就是它的好处。”",options:[],answer:'"It is inexpensive," I said. "Almost everyone can afford it and everyone enjoys eating it. I think this is what it is good for."',acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-14",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《落花生》· 四",prompt:"爹爹说：“花生底用处固然很多；但有一样是很可贵的。这小小的豆不像那好看的苹果、桃子、石榴，把它们底果实悬在枝上，鲜红嫩绿的颜色，令人一望而发生羡慕的心。它只把果子埋在地底，等到成熟，才容人把它挖出来。你们偶然看见一棵花生瑟缩地长在地上，不能立刻辨出它有没有果实，非得等到你接触它才能知道。”",options:[],answer:`"Peanut is good for many things," Dad said, "but there is one thing that is particularly good about it. Unlike apples, peaches or pomegranates that display their fruits up in the air, attracting you with their beautiful colours, peanut buries its fruit in the earth. It does not show itself until you dig it out when it is ripe and, unless you dig it out, you can't tell whether it bears fruit or not just by its frail stems above ground."`,acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-15",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《雄辩症》· 一",prompt:"病人说：“为什么要坐呢？难道你要剥夺我的不坐权吗？”",options:[],answer:'"Why should I?" the patient asked. "Are you going to deprive me of my right not to sit down?"',acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-16",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《雄辩症》· 二",prompt:"病人说：“这样谈问题是片面的，因而是荒谬的，并不是所有的水都能喝。例如你如果在水里掺上氰化钾，就绝对不能喝。”",options:[],answer:'The patient retorted, "This is lopsided talk, so it is absurd. Not all water is drinkable. If you put some potassium cyanide in it, it will be undrinkable."',acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-17",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《雄辩症》· 三",prompt:"医生毫无办法，便叹了口气，换一个话题说：“今天天气不错。”",options:[],answer:`The doctor could not but have a sigh and switched to another topic, "It's fine today."`,acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-18",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《雄辩症》· 四",prompt:"病人说：“纯粹胡说八道！你这里天气不错，并不等于全世界在今天都是好天气。例如北极，今天天气就很坏，刮着大风，漫漫长夜，冰山正在撞击……”",options:[],answer:`The patient replied, "Nonsense! The fact that it is fine here doesn't mean that it is fine everywhere else in the world. At the North Pole, for example, it must be freezing, with strong winds, long nights and icebergs colliding with one another..."`,acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-19",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《雄辩症》· 五",prompt:"医生说：“你走吧。”",options:[],answer:'Finally the doctor begged him, "Please go away."',acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-20",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《雄辩症》· 六",prompt:"病人说：“你无权命令我走。你是医院，不是公安机关，你不可能逮捕我，你不可能枪毙我。”",options:[],answer:`The patient again answered back. "You have no right to order me to leave. Yours is a hospital, not a public security office. So you can't arrest me, nor shoot me to death."`,acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-21",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《野草》· 一",prompt:"有这样一个故事。",options:[],answer:"There is a story which goes like this:",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-22",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《野草》· 二",prompt:"有人问：世界上什么东西的气力最大？回答纷纭的很，有的说“象”，有的说“狮”，有人开玩笑似的说：是“金刚”。金刚有多少气力，当然大家全不知道。",options:[],answer:`Someone asked, "What is the most powerful thing in the world?" There was a variety of answers. "Elephant," someone said. "Lion," another said. "Buddha's guardian warrior," still another said half-jokingly. As to how powerful the Buddha's guardian warrior was, no one was sure.`,acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-23",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《野草》· 三",prompt:"人的头盖骨，结合得非常致密与坚固，生理学家和解剖学者用尽了一切的方法，要把它完整地分出来，都没有这种力气，后来忽然有人发明了一个方法，就是把一些植物的种子放在要剖析的头盖骨里，给它以温度与湿度，使它发芽，一发芽，这些种子便可以可怕的力量，将一切机械力所不能分开的骨骼，完整地分开了，植物种子力量之大，如此如此。",options:[],answer:"The bones of a human skull are so tightly and firmly joined that no physiologist and anatomist had succeeded in taking them apart whatever means they tried. Then someone invented a method. He put some seeds of a plant in the skull to be dissected and provided the necessary temperature and moisture to make them germinate. Once the seeds germinated, they manifested a terrible force with which he succeeded in opening up the human skull that had failed to be opened even by mechanical means. This story tells us how powerful the seeds of plants can be.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-24",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《野草》· 四",prompt:"这，也许特殊了一点，常人不容易理解，那么，你看见笋的成长吗？你看见过被压在瓦砾和石块下面的一颗小草的生成吗？他为着向往阳光，为着达成它的生之意志，不管上面的石块如何重，石块与石块之间如何狭，它必定要曲曲折折地，但是顽强不屈地透到地面上来，它的根往土壤钻，它的芽往地面挺，这是一种不可抗的力，阻止它的石块，结果也被它掀翻，一粒种子的力量的大，如此如此。",options:[],answer:"You may think this is too unusual a story to be grasped by the common mind. Well, have you ever seen how the bamboo shoots grow? Have you ever seen how frail young grass grow out from under debris and rubble? In order to get the sunshine and bring its will to grow into play, no matter how heavy the rocks are and how narrow the space between the rocks, it will wind its way up irresistibly, its roots drilling downward and its sprouts shooting upward. This is an irresistible force. Any rock lying in its way will be overturned. This again shows how powerful a seed can be.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-25",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《野草》· 五",prompt:"没有一个人将小草叫做“大力士”，但是它的力量之大，的确是世界无比。这种力，是一般人看不见的生命力，只要生命存在，这种力就要显现，上面的石块，丝毫不足以阻挡，因为它是一种“长期抗战”的力、有弹性，能屈能伸的力，有韧性，不达目的不止的力。",options:[],answer:"Though the little grass has never been said to be herculean, the power it shows is matchless in the world. It is an invisible force of life. So long as there is life, the force will show itself. The rock above it is not heavy enough to prevent it from growing because it is a force that keeps growing over a period of time, because it is an elastic force that can shrink and expand, because it is a tenacious force that will not stop growing until it is grown.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-26",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《黄昏》· 一",prompt:"海是深蓝色的，说不上光滑；排了队的小浪开正步走，数不清有多少，喊着口令“一，二——”似的，朝喇叭口的海塘来了。挤到沙滩边，噗嘶！——队伍解散，喷着愤怒的白沫。然而后一排又赶着扑上来了。",options:[],answer:'The sea is deep blue, and cannot be called smooth, for countless rows of small breakers are marching in parade-step as if following the shouted command, "One, two! One!"—towards the trumpet-shaped jetty. Crowded close together, they rush to the sandy beach—splash! The marching ranks scatter and burst into angry spray. The rows immediately behind follow suit.',acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-27",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《黄昏》· 二",prompt:"风在掌号：冲锋号！小波浪跳跃着，每一个像个大眼睛，闪射着金光。满海全是金眼睛，全在跳跃。海塘下空隆空隆地腾起了喊杀。",options:[],answer:"The wind is trumpeting, a bugle calling to charge! Small breakers spring up, each breaker like a large eye casting out golden sparks. The whole sea is full of golden eyes, all leaping. Rumble—rumble...beneath the jetty a battle cry bursts forth.",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-28",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《黄昏》· 三",prompt:"而这些海的跳跃着的金眼睛重重叠叠一排接一排，一排怒似一排，一排比一排浓溢着血色的赤，连到天边，成为绀金色的一抹。这上头，半轮火红的夕阳！",options:[],answer:"The sea's golden eyes fall into ranks, each rank pursued by the next, each angrier than the last and deepening to blood-red as they stretch to the golden line of the horizon. There, above, lies the fiery half circle of the setting sun!",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-29",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《黄昏》· 四",prompt:"哦，哦！我已经尽了今天的历史的使命，我已经走完了今天的路程了！现在，现在，是我的休息时间到了，是我的死期到了！哦，哦！却也是我的新生期快开始了！明天，从海的那一头，我将威武地升起来，给你们光明，给你们温暖，给你们快乐！",options:[],answer:`"Oh! Oh! I have completed today's historic duty; I have finished today's journey! Now, now, my time to rest has come; my time to die is here. Oh! Oh! And yet, it is also my rebirth that will soon begin! Tomorrow, from the other end of the sea, I shall bravely hoist myself up, give you light, give you warmth, give you joy!"`,acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-30",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《黄昏》· 五",prompt:"风带着永远不会死的太阳的宣言到全世界。高的喜马拉雅山的最高峰，汪洋的太平洋，阴郁的古老的小村落，银的白光冰凝了的都市——一切，一切，夕阳都喷上了一口血焰！",options:[],answer:"The wind carries the declaration of the never-dying sun to all the world. The highest peaks of the Himalayas; the endless waters of the Pacific; small, old, gloomy villages; cities frozen by silver lights upon each and every one, the setting sun scatters its blood-red flames!",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-31",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《黄昏》· 六",prompt:"夜的黑幕沉重地将落未落。",options:[],answer:"Night's black curtain will be heavily lowered, but has not yet completely fallen.",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-32",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《黄昏》· 七",prompt:"在夜的海上，大风雨来了！",options:[],answer:"To the night-bound sea a storm has come!",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-33",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《盼头》· 一",prompt:"细娃盼过年，大人盼开春。儿时，对于大人的盼是不能理解的，但过年，对我来说，可是一年的大盼头了。过年，不但好玩，且有肉吃，那气氛是迷人的。年一过，又盼日子快些流，好流来又一个春节。",options:[],answer:"Little children look forward to the arrival of lunar New Year, adults to that of spring. When a child I couldn't understand what the elders hoped for. But New Year's Day was always the greatest red-letter day of all the year, for it meant the nicest food as well as a lot of fun, which was really fascinating. As soon as the festival was over, another one was my dream and I wished time flew as fast as possible.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-34",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《盼头》· 二",prompt:"没有盼头的日子是苍白不可想象的。人，得天天有点什么盼头，生活才不至于暗淡。有了盼头，会觉得太阳每天都是新的。不管是望梅止渴，还是画饼充饥，它都会激励你不停手中的桨，去追逐哪怕一星微小的火光。",options:[],answer:"A day without hope would be unimaginably pale. There must be something to look forward to each day to brighten one's life and keep it out of shadows. To a person cherishing hopes every morning rises a new sun. Even if it is a fantasy or an illusion, so long as it shows a ray of hope it still urges you on in pursuit of that little sparkle without letup.",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-han-35",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《盼头》· 三",prompt:"土地去掉水分，就成了沙漠；人没有了盼，还剩什么？小盼头支撑人的一天，大盼头支撑人的一生。",options:[],answer:"Deprived of moisture content, soil turns into desert. Deprived of hope, what is there left to a person? A small hope sustains a person for a day, a great one for a lifetime.",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-han-36",nodeId:"tr-han",categoryId:"tr-han",kind:"translation",label:"《盼头》· 四",prompt:"人，是绝不能没有盼头的。",options:[],answer:"Human beings cannot do without something to look forward to.",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-01",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《滚球》· 一",prompt:"I lost my sight when I was four years old by falling off a box car in a freight yard in Atlantic City and landing on my head. Now I am thirty-two. I can vaguely remember the brightness of sunshine and what color red is. It would be wonderful to see again, but a calamity can do strange things to people. It occurred to me the other day that I might not have come to love life as I do if I hadn't been blind. I believe in life now. I am not so sure that I would have believed in it so deeply, otherwise. I don't mean that I would prefer to go without my eyes. I simply mean that the loss of them made me appreciate the more what I had left.",options:[],answer:"四岁那年在大西洋城，我从货场一辆货车上摔下来，头先着地，于是双目失明。现在我已经32岁了。我还模糊地记得阳光是多么灿烂，红色是多么鲜艳。能恢复视觉固然好，但灾难也能对人产生奇妙的作用。有一天我突然想到，倘若我不是盲人，我或许不会变得像现在这样热爱生活。现在我相信生活，但我不能肯定如果自己是明眼人，会不会像现在这样深深地相信生活。这并不意味着我宁愿成为盲人，而只是意味着失去视力使我更加珍惜自己其他的能力了。",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-02",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《滚球》· 二",prompt:"Life, I believe, asks a continuous series of adjustments to reality. The more readily a person is able to make these adjustments, the more meaningful his own private world becomes. The adjustment is never easy. I was bewildered and afraid. But I was lucky. My parents and my teachers saw something in me—a potential to live, you might call it—which I didn't see, and they made me want to fight it out with blindness.",options:[],answer:"我认为，生活要求人不断地自我调整以适应现实。人愈能及时地进行调整，他的个人世界便愈有意义。调整决非易事。我曾感到茫然害怕。但我很幸运。父母和老师在我身上发现了某种东西——可以称之为活下去的潜力吧——而我自己却没有发现。他们激励我誓与失明拼搏到底。",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-03",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《滚球》· 三",prompt:"The hardest lesson I had to learn was to believe in myself. That was basic. If I hadn't been able to do that, I would have collapsed and become a chair rocker on the front porch for the rest of my life. When I say belief in myself I am not talking about simply the kind of self-confidence that helps me down an unfamiliar staircase alone. That is part of it. But I mean something bigger than that: an assurance that I am, despite imperfections, a real, positive person; that somewhere in the sweeping, intricate pattern of people there is a special place where I can make myself fit.",options:[],answer:"我必须学会的最艰难的一课就是相信自己，这是基本条件。如做不到这一点，我的精神就会崩溃，只能坐在前门廊的摇椅中度过余生。相信自己并不仅仅指支持我独自走下陌生的楼梯的那种自信。那是一部分。但我指的是大事：是坚信自己虽然有缺陷，却是一个真正的有进取心的人；坚信在芸芸众生错综复杂的格局当中，自有我可以安身立命的一席之地。",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-04",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《滚球》· 四",prompt:`It took me years to discover and strengthen this assurance. It had to start with the most elementary things. Once a man gave me an indoor baseball. I thought he was mocking me and I was hurt. "I can't use this," I said. "Take it with you," he urged, "and roll it around." The words stuck in my head. "Roll it around!" By rolling the ball I could hear where it went. This gave me an idea how to achieve a goal I had thought impossible: playing baseball. At Philadelphia's Overbrook School for the Blind I invented a successful variation of baseball. We called it ground ball.`,options:[],answer:"我花了很长时间才树立并不断加强这一信念。这要从最简单的事做起。有次一个人给我一个室内玩的棒球，我以为他在嘲笑我，心里很难受。“我不能使这个。”我说。“你拿去，”他竭力劝我，“在地上滚。”他的话在我脑子里生了根。“在地上滚！”滚球使我听见它朝哪儿滚动。我马上想到一个我曾认为不可能达到的目标：打棒球。在费城的奥弗布鲁克盲人学校，我发明了一种很受人欢迎的棒球游戏，我们称它为地面球。",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-05",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《滚球》· 五",prompt:"All my life I have set ahead of me a series of goals and then tried to reach them, one at a time. I had to learn my limitations. It was no good to try for something I knew at the start was wildly out of reach because that only invited the bitterness of failure. I would fail sometimes anyway but on the average I made progress.",options:[],answer:"我这一辈子给自己树立了一系列目标，然后努力去达到，一次一个。我必须了解自己能力有限。若开始就知道某个目标根本达不到却硬要去实现，那不会有任何好处，因为那只会带来失败的苦果。我有时也失败过，但一般说来总有进步。",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-06",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《爱情不是商品》· 一",prompt:`A reader in Florida, apparently bruised by some personal experience, writes in to complain, "If I steal a nickel's worth of merchandise, I am a thief and punished; but if I steal the love of another's wife, I am free."`,options:[],answer:"佛罗里达州的一位读者显然是在个人经历上受过创伤，他写信来抱怨道：“如果我偷走了五分钱的商品，我就是个贼，要受到惩罚，但是如果我偷走了他人妻子的爱情，我没事儿。”",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-07",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《爱情不是商品》· 二",prompt:"But love is not a commodity; the real thing cannot be bought, sold, traded or stolen. It is an act of the will, a turning of the emotions, a change in the climate of the personality.",options:[],answer:"但是爱情并不是商品；真情实意不可能买到，卖掉，交换，或者偷走。爱情是志愿的行动，是感情的转向，是个性发挥上的变化。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-08",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《爱情不是商品》· 三",prompt:'When a husband or wife is "stolen" by another person, that husband or wife was already ripe for the stealing, already predisposed toward a new partner. The "love bandit" was only taking what was waiting to be taken, what wanted to be taken.',options:[],answer:"当丈夫或妻子被另一个人“偷走”时，那个丈夫或妻子就已经具备了偷走的条件，事先已经准备接受新的伴侣了。这位“爱匪”不过是取走等人取走、盼人取走的东西。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-09",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《爱情不是商品》· 四",prompt:'Most of us, when young, had the experience of a sweetheart being taken from us by somebody more attractive and more appealing. At the time, we may have resented this intruder—but as we grew older, we recognized that the sweetheart had never been ours to begin with. It was not the intruder that "caused" the break, but the lack of a real relationship.',options:[],answer:"我们多数人年轻时都有过恋人被某个更有迷惑力、更有吸引力的人夺去的经历。在当时，我们兴许怨恨这位不速之客——但是后来长大了，也就认识到了心上人本来就不属于我们。并不是不速之客“导致了”决裂，而是缺乏真实的关系。",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-10",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《爱情不是商品》· 五",prompt:'Nothing is more futile and more self-defeating than the bitterness of spurned love, the vengeful feeling that someone else has "come between" oneself and a beloved. This is always a distortion of reality, for people are not the captives or victims of others—they are free agents, working out their own destinies for good or for ill.',options:[],answer:"因失恋而痛苦，因别人“插足”于自己与心上人之间而图报复，是最没有出息、最自作自受的了。这种事总是歪曲了事实真相，因为谁都不是给别人当俘虏或牺牲品——人都是自由行事的，不论命运是好是坏，都由自己来做主。",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-11",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《爱情不是商品》· 六",prompt:'But the rejected lover or mate cannot afford to believe that his beloved has freely turned away from him—and so he ascribes sinister or magical properties to the interloper. He calls him a hypnotist or a thief or a home-breaker. In the vast majority of cases, however, when a home is broken, the breaking has been long before any "third party" has appeared on the scene.',options:[],answer:"但是，遭离弃的情人或配偶无法相信他的心上人是自由地背离他的——因而他归咎于插足者心术不正或迷人有招。他把他叫做催眠师、“第三者”或破坏家庭的人。然而，从大多数事例看，一个家的破裂，是早在什么“第三者”出现之前就开始了的。",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-12a",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《谈读书》· 一",prompt:"Studies serve for delight, for ornament, and for ability. Their chief use for delight, is in privateness and retiring; for ornament, is in discourse; and for ability, is in the judgment and disposition of business. For expert men can execute, and perhaps judge of particulars, one by one; but the general counsels, and the plots and marshalling of affairs, come best from those that are learned.",options:[],answer:"读书足以怡情，足以傅彩，足以长才。其怡情也，最见于独处幽居之时；其傅彩也，最见于高谈阔论之中；其长才也，最见于处世判事之际。练达之士虽能分别处理细事或一一判别枝节，然纵观统筹，全局策划，则舍好学深思者莫属。",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-12b",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《谈读书》· 二",prompt:"To spend too much time in studies is sloth; to use them too much for ornament, is affectation; to make judgment wholly by their rules, is the humour of a scholar. They perfect nature, and are perfected by experience: for natural abilities are like natural plants, that need pruning by study; and studies themselves do give forth directions too much at large, except they be bounded in by experience. Crafty men contemn studies, simple men admire them, and wise men use them; for they teach not their own use; but that is a wisdom without them, and above them, won by observation.",options:[],answer:"读书费时过多易惰，文采藻饰太盛则矫，全凭条文断事乃学究故态。读书补天然之不足，经验又补读书之不足，盖天生才干犹如自然花草，读书然后知如何修剪移接；而书中所示，如不以经验范之，则又大而无当。有一技之长者鄙读书，无知者羡读书，唯明智之士用读书，然书并不以用处告人，用书之智不在书中，而在书外，全凭观察得之。",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-12c",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《谈读书》· 三",prompt:"Read not to contradict and confute; nor to believe and take for granted; nor to find talk and discourse; but to weigh and consider. Some books are to be tasted, others to be swallowed, and some few to be chewed and digested; that is, some books are to be read only in parts; others to be read, but not curiously; and some few to be read wholly, and with diligence and attention. Some books also may be read by deputy, and extracts made of them by others; but that would be only in the less important arguments, and the meaner sort of books; else distilled books are, like common distilled waters, flashy things.",options:[],answer:"读书时不可存心诘难作者，不可尽信书上所言，亦不可只为寻章摘句，而应推敲细思。书有可浅尝者，有可吞食者，少数则须咀嚼消化。换言之，有只须读其部分者，有只须大体涉猎者，少数则须全读，读时须全神贯注，孜孜不倦。书亦可请人代读，取其所作摘要，但只限题材较次或价值不高者，否则书经提炼犹如水经蒸馏，淡而无味矣。",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-13a",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《谈读书》· 四",prompt:"Reading maketh a full man; conference a ready man; and writing an exact man. And therefore, if a man write little, he had need have a great memory; if he confer little, he had need have a present wit; and if he read little, he had need have much cunning, to seem to know that he doth not. Histories make men wise; poets witty; the mathematics subtile; natural philosophy deep; moral grave; logic and rhetoric able to contend. Abeunt studia in mores. Nay, there is no stand or impediment in the wit, but may be wrought out by fit studies: like as diseases of the body may have appropriate exercises.",options:[],answer:"读书使人充实，讨论使人机智，笔记使人准确。因此不常做笔记者须记忆特强，不常讨论者须天生聪颖，不常读书者须欺世有术，始能无知而显有知。读史使人明智，读诗使人灵秀，数学使人周密，科学使人深刻，伦理学使人庄重，逻辑修辞之学使人善辩：凡有所学，皆成性格。人之才智但有滞碍，无不可读适当之书使之顺畅，一如身体百病，皆可借相宜之运动除之。",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-13b",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《谈读书》· 五",prompt:"Bowling is good for the stone and reins; shooting for the lungs and breast; gentle walking for the stomach; riding for the head; and the like. So if a man's wit be wandering, let him study the mathematics; for in demonstrations, if his wit be called away never so little, he must begin again. If his wit be not apt to distinguish or find differences, let him study the schoolmen; for they are cymini sectores. If he be not apt to beat over matters, and to call up one thing to prove and illustrate another, let him study the lawyers' cases. So every defect of the mind may have a special receipt.",options:[],answer:"滚球利睾肾，射箭利胸肺，慢步利肠胃，骑术利头脑，诸如此类。如智力不集中，可令读数学，盖演题须全神贯注，稍有分散即须重演；如不能辨异，可令读经院哲学，盖是辈皆吹毛求疵之人；如不善求同，不善以一物阐证另一物，可令读律师之案卷。如此头脑中凡有缺陷，皆有特药可医。",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-14",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《论领导》· 一",prompt:"What is leadership? Its qualities are difficult to define. But they are not so difficult to identify.",options:[],answer:"什么是领导？领导应具备什么品质，这很难精确地解说，但辨认指陈却不难。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-15",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《论领导》· 二",prompt:"Leaders don't force other people to go along with them. They bring them along. Leaders get commitment from others by giving it themselves, by building an environment that encourages creativity, and by operating with honesty and fairness.",options:[],answer:"领导者不强制别人与自己协调一致，而是帮助他们跟上。领导者让别人承担义务，首先自己承担义务，造成一种能鼓励创造的环境，待人诚恳，处事公正。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-16",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《论领导》· 三",prompt:"Leaders know that when there are two opinions on an issue, one is not bound to be wrong. They recognize that hustle and rush are the allies of superficiality. They are open to new ideas, but they explore their ramifications thoroughly.",options:[],answer:"领导者明白，在争论的问题上出现两种意见时，并非必然有一种是错的。他们认识到匆忙草率就会促成肤浅片面。他们愿意接受新的设想或建议，但对它们的后果要作认真的探讨。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-17",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《论领导》· 四",prompt:"Successful leaders are emotionally and intellectually oriented to the future—not wedded to the past. They have a hunger to take responsibility, to innovate, and to initiate. They are not content with merely taking care of what's already there. They want to move forward to create something new.",options:[],answer:"成功的领导者无论是感情上还是理智上都着眼未来而不眷恋过去。他们渴望负责、改革、开拓。他们不仅仅满足于守成，他们要前进，要创新。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-18",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《论领导》· 五",prompt:"Leaders are flexible rather than dogmatic. They believe in unity rather than conformity. And they strive to achieve consensus out of conflict.",options:[],answer:"领导者处事灵活而不武断。他们认为与其循规蹈矩不如目标一致。他们力图在矛盾冲突中求得意见协调。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-19",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《论领导》· 六",prompt:"A good leader, an effective leader, is one who has respect. Respect is something you have to have in order to get. A leader who has respect for other people at all levels of an organization, for the work they do, and for their abilities, aspirations and needs, will find that respect is returned. And all concerned will be motivated to work together.",options:[],answer:"好的领导者，卓有成效的领导者，善于对人关怀尊重。要得人尊重必须尊重别人。领导者对本组织各级人员都表示尊重，对他们的工作、能力、愿望与要求表示关怀，他就会发现人家也尊重他关怀他。这样，所有有关人员就都会激励起来共同努力。",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-20a",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《天空的色彩》· 一",prompt:"If we look at the sky on a perfectly fine summer's day we shall find that the blue colour is the most pure and intense overhead, and when looking high up in a direction opposite to the sun. Near the horizon it is always less bright, while in the region immediately around the sun it is more or less yellow. The reason of this is that near the horizon we look through a very great thickness of the lower atmosphere, which is full of the larger dust particles reflecting white light, and this dilutes the pure blue of the higher atmosphere seen beyond.",options:[],answer:"晴空万里的夏日，如果我们观察一下天空，且背向太阳，极目仰望，就会发现头顶上空的蓝色最纯净，最浓郁。靠近天边，色彩往往较暗淡，太阳周围的地方则略呈黄色。这是因为我们向天边望去时，目光要穿过一层极厚的低空大气层，其中布满颗粒较大的尘埃，反射出白光，这就冲淡了天际高空大气层的纯蓝色。",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-20b",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《天空的色彩》· 二",prompt:"And in the vicinity of the sun a good deal of the blue light is reflected back into space by the finer dust, thus giving a yellowish tinge to that which reaches us reflected chiefly from the coarse dust of the lower atmosphere. At sunset and sunrise, however, this last effect is greatly intensified, owing to the great thickness of the strata of air through which the light reaches us. The enormous amount of this dust is well shown by the fact that then only we can look full at the sun, even when the whole sky is free from clouds and there is no apparent mist.",options:[],answer:"在太阳附近，大量蓝光则由细微的尘埃反射回太空，这样，主要由低空大气层的粗粒尘埃反射到地面的光线，便带有浅黄色。不过，在日出日落时，由于光线到达地面需要穿过厚厚的大气层，这种反射效果大大增强了。只有在这种时候，我们才可以直视太阳，即使万里长空没有一点云彩，不见一丝雾霭。这就充分显示了低空尘埃的数量之大。",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-20c",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《天空的色彩》· 三",prompt:"But the sun's rays then reach us after having passed, first, through an enormous thickness of the higher strata of the air, the minute dust of which reflects most of the blue rays away from us, leaving the complementary yellow light to pass on. Then, the somewhat coarser dust reflects the green rays, leaving a more orange-coloured light to pass on; and finally some of the yellow is reflected, leaving almost pure red.",options:[],answer:"但是太阳的光线终于到达了地面。它们先是穿过厚度极大的高空大气层，其中的细微尘埃把大部分蓝色的光反射掉了，让补色的黄光继续通行。然后，粗粒尘埃又反射掉绿色的光，让偏橙色的光继续通行；最后，部分黄色的光也反射掉，剩下几乎是纯红色的了。",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-20d",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《天空的色彩》· 四",prompt:"But owing to the constant presence of air currents, arranging both the dust and vapour in strata of varying extent and density, and of high or low clouds which both absorb and reflect the light in varying degrees, we see produced all those wondrous combinations of tints and those gorgeous ever-changing colours which are a constant source of admiration and delight to all who have the advantage of an uninterrupted view to the west and who are accustomed to watch for those not infrequent exhibitions of nature's kaleidoscopic colour painting.",options:[],answer:"不过，由于不断出现气流，把尘埃与水汽分层排列，广度不均，密度各异，加上高低空常有云层，不同程度地吸收并反射阳光，我们这才看到各种奇异的色调斑驳陆离，诸多绚丽的色彩变化万千；任何人只要有幸将西天的景致一览无余，只要有心观看大自然不时展现的那一幅幅瞬息万变的彩画，都会为之赞不绝口，喜不自胜。",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-21",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《天空的色彩》· 五",prompt:"With every change in the altitude of the sun the display changes its character; and most of all when it has sunk below the horizon, and owing to the more favourable angles a larger quantity of the coloured light is reflected toward us. Especially when there is a certain amount of cloud is this the case. These, so long as the sun was above the horizon, intercepted much of the light and colour; but when the great luminary has passed away from our direct vision, his light shines more directly on the under sides of all the clouds and air strata of different densities; a new and more brilliant light flushes the western sky, and a display of gorgeous ever-changing tints occurs which are at once the delight of the beholder and the despair of the artist. And all this unsurpassable glow we owe to dust!",options:[],answer:"随着夕阳缓缓西坠，这种景观也不断变幻；尤其是在太阳沉入地平线之后，由于角度更加适宜，五颜六色的光就都反射到地面上来。遇有些许云雾，更是如此。本来，只要太阳还位于地平线之上，云雾便截住了不少阳光和色彩；而今太阳从我们的视野消失，阳光便更为直接地照射到密度各异的重重云霭与层层大气的底部；一片崭新的、更加灿烂的阳光染红了西天，一幅景观色彩绚丽，变化万千，观赏者固然赏心悦目，丹青手只好自叹莫及。而我们之所以能领略如此无与伦比的美景，全应归功于——尘埃！",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-22",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《父亲失约》· 一",prompt:"It happened in one of those picturesque Danish taverns that cater to tourists and where English is spoken. I was with my father on a business-and-pleasure trip, and in our leisure hours we were having a wonderful time.",options:[],answer:"故事发生在丹麦的一家美丽如画的小旅舍里。这种旅舍备有酒食招待游客，通用英语。我和父亲这次旅行，既为了公事，也为了游乐，有空的时候玩得挺欢。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-23",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《父亲失约》· 二",prompt:'He had visited Denmark when he was a young man. I asked him, "How long is it since you were here?"',options:[],answer:"父亲年青时到过丹麦。我问他：“你上次来是什么时候？”",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-24",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《父亲失约》· 三",prompt:'"Oh, about 30 years. I remember being in this very inn, by the way." He looked around, remembering. "Those were gracious days—" He stopped suddenly, and I saw that his face was pale. I followed his eyes and looked across the room to a woman who was setting a tray of drinks before some customers. She might have been pretty once, but now she was stout and her hair was untidy. "Do you know her?" I asked.',options:[],answer:"“哦，大约30年前。我记得就在这家店里，说真的。”他四下望望，一边在追忆。“那些日子真美好……”突然他住口不说，脸色煞白。我顺着他的眼光，看到餐厅那边有个女人端着托盘正在给客人上酒。她从前可能很漂亮，可现在发胖了，头发也不那么修整。我问父亲：“你认识她？”",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-25",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《父亲失约》· 四",prompt:`The woman came to our table. "Drinks?" she inquired. "We'll have beer," I said. She nodded and went away.`,options:[],answer:"女人走到我们桌前。“喝点什么？”她问。我说：“要啤酒。”她点点头，走了。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-26",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《父亲失约》· 五",prompt:`"Oh, yes, I want to tell you. I don't want you wondering about this. Her father objected to our romance. I was a foreigner. I had no prospects, and was dependent on my father. When I wrote to tell Father that I wanted to get married he cut off my allowance. And I had to go home. But I met the girl once more, and told her I would return to America, borrow enough money to get married on, and come back for her in a few months."`,options:[],answer:"“哦，我是要告诉你的，别让你乱猜。她父亲反对我们谈情说爱；我是外国人，没什么前途，还要依靠父亲。我写信给父亲说要结婚，父亲就不寄钱来。我只好回家。但是我又跟她见了一面，告诉她我要回美国去借钱结婚，过几个月就来找她。”",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-27",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《父亲失约》· 六",prompt:`"We knew," he continued, "that her father might intercept a letter, so we agreed that I would simply mail her a slip of paper with a date on it, the time she was to meet me at a certain place; then we'd get married. Well, I went home, got the loan and sent her the date. She received the note. She wrote me: 'I'll be there.' But she wasn't. Then I found that she had been married about two weeks before, to a local innkeeper. She hadn't waited."`,options:[],answer:"“我们知道，”他接着说，“她父亲可能把信截下来，所以商量好只寄她一张纸条，写个日期，让她去某处和我见面，然后结婚。后来我回家去借到了钱，把日期寄给她。她收到了纸条，回信说‘准去’。但是她并没有去。后来我才知道，她在两星期前嫁给了当地的一个小客栈老板。她没等我。”",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-28",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《父亲失约》· 七",prompt:'We drank our beer and left. Outside I said, "Father, just how did you write that date on which she was to meet you?"',options:[],answer:"我们喝完啤酒出来，我问父亲：“爸，你叫她去见你，那日期到底是怎么写的？”",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-29",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《父亲失约》· 八",prompt:'He stopped, took out an envelope and wrote on it. "Like this," he said. "12/11/73, which was, of course, December 11, 1973."',options:[],answer:"他站住，拿出一个信封，在上面写了下来。他说：“这样写的：12/11/73，当然指1973年12月11日啦。”",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-30",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《父亲失约》· 九",prompt:`"No!" I exclaimed. "It isn't in Denmark or any European country. Over here they write the day first, then the month. So that date wouldn't be December 11 but the 12th of November!"`,options:[],answer:"我叫道：“不对！在丹麦，在欧洲国家，都不是这样写的。他们这儿是先写日子，再写月份。所以那个日期不是12月11日，而是11月12日！”",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-31",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《父亲失约》· 十",prompt:`Father passed his hand over his face. "And she was there!" he exclaimed. "And it was because I didn't show up that she got married." He was silent a while. "Well," he said, "I hope she's happy. She seems to be."`,options:[],answer:"父亲抬起手摸了摸脸，叫道：“这么说她是去过了！因为我没有到，她嫁了别人！”他沉默了一会又说，“也好。我希望她快乐，看起来她也很快乐。”",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-32",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《父亲失约》· 十一",prompt:`He put his arm around my shoulders, looked at me with a hearty smile, and said, "I was doubly lucky, young fellow, for otherwise I wouldn't have met you, either!"`,options:[],answer:"父亲伸手搂着我的肩膀，温情地向我笑道：“小家伙，要不然也不会有你！我是幸上加幸呢！”",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-33",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《信任》· 一",prompt:"Last night I was driving from Harrisburg to Lewisburg, Pa., a distance of about eighty miles. It was late, I was late and if anyone asked me how fast I was driving, I'd have to plead the Fifth Amendment to avoid self-incrimination. Several times I got stuck behind a slow-moving truck on a narrow road with a solid white line on my left, and I was clinching my fists with impatience.",options:[],answer:"昨晚，我驱车从宾夕法尼亚州的哈里斯堡赶赴刘易斯堡，其间约有80英里的路程。夜幕已笼罩着大地，我动身又晚了，要是有人问我车开得有多快，我就得根据《美国宪法修正案》第五条不予回答，以免自证其罪。在狭窄的公路上，我的车几次被慢慢爬行的货车挡在后面，左侧是一条严禁超越的白色实线，急得我把拳头握得紧紧的。",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-34",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《信任》· 二",prompt:"At one point, along an open highway, I came to a crossroads with a traffic light. I was alone on the road by now, but as I approached the light, it turned red and I braked to a halt. I looked left, right and behind me. Nothing. Not a car, no suggestion of headlights, but there I sat, waiting for the light to change, the only human being for at least a mile in any direction.",options:[],answer:"我正驾车行驶在一条畅通的公路上，前面出现一个有交通指示灯的十字路口。当时公路上就我一人。我的车刚驶近路口，红灯就亮了，我赶紧刹住了车。我环顾四周，什么也没看到，没有一辆汽车，连车灯的影子也没有。尽管如此，我还是一直端坐着，等待指示灯的转换。至少在周围一英里范围内，就我一人。",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-35",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《信任》· 三",prompt:"I started wondering why I refused to run the light. I was not afraid of being arrested, because there was obviously no cop around, and there certainly would have been no danger in going through it.",options:[],answer:"我开始琢磨起自己为什么不肯闯红灯这个问题来。我并不是害怕被抓住，因为周围根本没有警察，即使闯红灯也不会有什么危险。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-36",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《信任》· 四",prompt:"Much later that night, after I'd met with a group in Lewisburg and had climbed into bed near midnight, the question of why I'd stopped for that light came back to me. I think I stopped because it's part of a contract we all have with each other. It's not only the law, but it's an agreement we have, and we trust each other to honor it: we don't go through red lights. Like most of us, I'm more apt to be restrained from doing something bad by the social convention that disapproves of it than by any law against it.",options:[],answer:"当晚在刘易斯堡会见了不少人，半夜时分我才上床。夜深人静，我仍久久不能入睡，自己为什么不肯闯红灯这个问题又一次回到我的脑海中。我想我之所以遇红灯而停车，是因为这是我们大家彼此之间契约的一部分。它既是法律的规定，也是我们共同的协议。我们不闯红灯，而且我们都相信人人都会遵守这一协议，和大多数人一样。",acceptedAnswers:[],explanationZh:"",difficulty:3,selfCheck:!0},{id:"tr-eng-37",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《信任》· 五",prompt:"It's amazing that we ever trust each other to do the right thing, isn't it? And we do, too. Trust is our first inclination. We have to make a deliberate decision to mistrust someone or to be suspicious or skeptical. Those attitudes don't come naturally to us.",options:[],answer:"我们大家一向彼此信任，相信他人会做社会公德所倡导的事情，这着实令人惊奇，是不是？然而我们的确是这样做的。信任是我们固有的心理倾向。当我们对某人表示不信任，或对某件事情持怀疑态度时，我们往往需要认真思考才能做出决定。这种不信任感并不是自然而然地在我们脑海中产生的。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0},{id:"tr-eng-38",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《信任》· 六",prompt:"It's a damn good thing, too, because the whole structure of our society depends on mutual trust, not distrust. This whole thing we have going for us would fall apart if we didn't trust each other most of the time. In Italy, they have a hard time getting any money for the government, because many people just plain don't pay their income tax. Here the Internal Revenue Service makes some gestures toward enforcing the law, but mostly they just have to trust that we'll pay what we owe. There has often been talk of a tax revolt in this country, and most recently among unemployed auto workers in Michigan, and our government pretty much admits if there was a widespread tax revolt here, they wouldn't be able to do anything about it.",options:[],answer:"这的确是令人非常欣慰之事，因为我们的整个社会体系依赖于人们的相互信任，而不是相互猜疑。如果我们在大部分时间里不能相互信任，那么我们享有其利益的整个社会体系就会崩溃。在意大利，政府很难收到税款，因为很多人明目张胆地不缴所得税。在美国，国内税务局也做出了姿态说要执行法律，但政府主要还得靠信任，相信公民会依法纳税。在美国时常听到有人扬言要抗税，最近声言抗税的是密歇根州的一些失业汽车工人。我们的政府也完全承认，如果“抗税”在全国蔓延，政府将毫无办法。",acceptedAnswers:[],explanationZh:"",difficulty:4,selfCheck:!0},{id:"tr-eng-39",nodeId:"tr-eng",categoryId:"tr-eng",kind:"translation",label:"《信任》· 七",prompt:"I was so proud of myself for stopping for that red light, and inasmuch as no one would ever have known what a good person I was on the road from Harrisburg to Lewisburg, I had to tell someone.",options:[],answer:"我为自己昨晚没闯红灯感到非常自豪。由于没有人知道在从哈里斯堡至刘易斯堡的路上我是一个多么好的人，我得把它写出来公之于众。",acceptedAnswers:[],explanationZh:"",difficulty:2,selfCheck:!0}],p={categories:[{id:"tr-han",titleZh:"汉译英",noteZh:"七篇中文散文选段，一段一段译成英文；先落笔，再对照参考译文。"},{id:"tr-eng",titleZh:"英译汉",noteZh:"七篇英文短文选段，一段一段译成中文；先落笔，再对照参考译文。"}],items:c},f={language:r,vocabulary:l,writing:d,translation:p},s="leafia.practice.customQuestions.v1";function h(t){if(!t||typeof t!="object")return null;const e=t,n=typeof e.id=="string"?e.id:"",i=typeof e.trackId=="string"?e.trackId:"",o=typeof e.prompt=="string"?e.prompt.trim():"",a=typeof e.answer=="string"?e.answer.trim():"";return!n||!i||!o||!a?null:{id:n,trackId:i,prompt:o,answer:a,explanationZh:typeof e.explanationZh=="string"?e.explanationZh.trim():"",createdAt:typeof e.createdAt=="number"&&Number.isFinite(e.createdAt)?e.createdAt:Date.now()}}function m(){if(typeof window>"u")return[];try{const t=window.localStorage.getItem(s);if(!t)return[];const e=JSON.parse(t);return Array.isArray(e)?e.map(h).filter(n=>n!==null):[]}catch{return[]}}function g(t){if(!(typeof window>"u"))try{window.localStorage.setItem(s,JSON.stringify(t))}catch{}}function u(t){return{id:`custom-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`,trackId:t.trackId,prompt:t.prompt.trim(),answer:t.answer.trim(),explanationZh:t.explanationZh.trim(),createdAt:Date.now()}}export{f as P,u as c,m as l,g as s};
